#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_MESSAGE_T {
    // Define your message structure here
} NFAPI_MESSAGE_T;

typedef struct DynamicArray {
    pthread_mutex_t mutex; 
    NFAPI_MESSAGE_T **messages;
    size_t count;
    size_t capacity;
} DynamicArray;

int initDynamicArray(DynamicArray *arr) {
    arr->count = 0;
    arr->capacity = 10;
    arr->messages = (NFAPI_MESSAGE_T**) malloc(sizeof(NFAPI_MESSAGE_T*) * arr->capacity);

    if (!arr->messages) {
        return -1;  // out of memory
    }

    if (pthread_mutex_init(&arr->mutex, NULL)) {
        free(arr->messages);
        return -2;  // failed to initialize mutex
    }

    return 0;  // success
}

int addMessage(DynamicArray *arr, NFAPI_MESSAGE_T* message) {
    pthread_mutex_lock(&arr->mutex);

    if (arr->count == arr->capacity) {
        size_t newCapacity = arr->capacity * 2;
        NFAPI_MESSAGE_T **newMessages = realloc(arr->messages, sizeof(NFAPI_MESSAGE_T*) * newCapacity);

        if (!newMessages) {
            pthread_mutex_unlock(&arr->mutex);
            return -1;  // out of memory
        }

        arr->messages = newMessages;
        arr->capacity = newCapacity;
    }

    arr->messages[arr->count] = message;
    (arr->count)++;

    pthread_mutex_unlock(&arr->mutex);

    return 0;  // success
}

int removeMessage(DynamicArray *arr, size_t index) {
    pthread_mutex_lock(&arr->mutex);

    if (index >= arr->count) {
        pthread_mutex_unlock(&arr->mutex);
        return -1;  // invalid index
    }

    free(arr->messages[index]);  // Free memory of message structure

    for(size_t i = index; i < arr->count - 1; ++i) {
        arr->messages[i] = arr->messages[i + 1];
    }

    (arr->count)--;

    if ((arr->capacity > 10) && (arr->count <= arr->capacity / 4)) {
        size_t newCapacity = arr->capacity / 2;
        NFAPI_MESSAGE_T **newMessages = realloc(arr->messages, sizeof(NFAPI_MESSAGE_T*) * newCapacity);

        if (!newMessages) {
            pthread_mutex_unlock(&arr->mutex);
            return -2;  // out of memory
        }

        arr->messages = newMessages;
        arr->capacity = newCapacity;
    }

    pthread_mutex_unlock(&arr->mutex);

    return 0;  // success
}

NFAPI_MESSAGE_T* getMessage(DynamicArray *arr, size_t index) {
    pthread_mutex_lock(&arr->mutex);

    if (index >= arr->count) {
        pthread_mutex_unlock(&arr->mutex);
        return NULL;  // invalid index
    }

    NFAPI_MESSAGE_T *message = arr->messages[index];

    pthread_mutex_unlock(&arr->mutex);

    return message;
}
```
