#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
    double value;
} Record;

void allocate_and_initialize() {
    // Allocate and initialize arrays
    long* offsets = malloc(3 * sizeof(long));
    int* keys = malloc(3 * sizeof(int));
    double* values = malloc(3 * sizeof(double));

    for (int i = 0; i < 3; ++i) {
        offsets[i] = rand() % 1000; // Random numbers within the range of a long value. Adjust accordingly.
        keys[i] = rand() % 100;    // Random numbers within the range of an int value. Adjust accordingly.
        values[i] = 1.0 * rand() / RAND_MAX; // Random double in the range [0,1). Adjust if necessary.
    }

    Record* records = malloc(3 * sizeof(Record));

    for (int i = 0; i < 3; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = values[i];
    }

    // Free allocated memory after use.
    free(offsets);
    free(keys);
    free(values);
    free(records);
}
```
