['Here is an example of how you might implement this kind of command line argument parser using the `argp` library in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h> 
#include <errno.h>
#include <argp.h>
#include <syslog.h>
#define MAX_LINE 1024

const char *argp_program_version = "argp-ex3 1.0";
const char *argp_program_bug_address = "<bug-gnu-utils@gnu.org>";
static char doc[] = "Argp example #3 -- a program with options and arguments using argp";
static char args_doc[] = "[FILES...]";  // Files argument should be optional
static struct argp_option options[] = {
    {"output", 'o', "FILE", OPTION_ARG_OPTIONAL, "Output to FILE instead of standard output" },
    {"chars", 'c', "NUM", OPTION_ARG_OPTIONAL, "Print lines with more than NUM characters"},
    { 0 }
};
struct arguments{
    char *args[2]; //input file and threshold
    int threshold;
    FILE *output;
};

static error_t parse_opt(int key, char *arg, struct argp_state *state){
    struct arguments *arguments = state->input;
    switch (key) {
        case 'c': 
            arguments->threshold = atoi(arg); break;
        case 'o': 
            if((arguments->output=fopen(arg,"w")) == NULL){
                syslog(LOG_ERR, "Error opening file %s: %m\n", arg);
                exit(EXIT_FAILURE);
            } break;
        case ARGP_KEY_ARG: 
            if (state->arg_num > 2){ // too many arguments
                argp_usage(state);
            }
            arguments->args[state->arg_num] = arg; 
            break;
        default: return ARGP_ERR_UNKNOWN;
    }   
    return 0;
}
static struct argp argp = { options, parse_opt, args_doc, doc };
int main(int argc, char **argv){
    struct arguments arguments;
    openlog("customLog", LOG_PID|LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Program started by User %d\n", getuid()); 
    arguments.output = stdout;
    argp_parse(&argp, argc, argv, 0, 0, &arguments);

    if(!strlen(arguments.args[0])){
        syslog(LOG_WARNING,"No file provided"); 
        return EXIT_FAILURE;
    }

    FILE *file = fopen(arguments.args[0],"r");
    if (file == NULL) {
        syslog(LOG_ERR, "Error opening input file %s: %m\n", arguments.args[0]);
        return EXIT_FAILURE;
    }

    char line[MAX_LINE];
    int count = 0;
    while (fgets(line, MAX_LINE, file) != NULL){
        ++count;
        if ((int)strlen(line)-1 > arguments.threshold) {  // -1 to avoid counting the newline character
            fprintf(arguments.output, "%s", line);
        }
    }

    syslog(LOG_INFO,"Number of lines in file: %d\n", count);
    fclose(file);
    if (arguments.output != stdout) {
        fclose(arguments.output);
    }
    closelog(); 
    return EXIT_SUCCESS;
}
```
This program reads command line arguments and options using argp, opens an input file for reading and optionally redirects output to a specified output file. It also logs errors and warnings using syslog. If the number of characters in a line exceeds a certain threshold, it is printed out. 

Please note that this program can be improved by adding error handling (especially around memory allocation), integrating multi-threading for efficient processing of lines when writing to the output file, and improving overall resource usage for large files or systems with limited resources. However, these improvements are beyond the scope of a simple command line parser and would require a more in-depth understanding of C programming and system optimization techniques.
']

