#include <stdio.h>
#include <stdlib.h>
#define MAX_SIZE 10000

void findMinMax(int* arr, int size) {
    if (size == 0) {
        printf("The list is empty.\n");
        return;
    }

    int min = arr[0];
    int max = arr[0];
    for(int i = 1; i < size; i++){
        if(arr[i] > max) {
            max = arr[i];
        } else if(arr[i] < min) {
            min = arr[i];
        }
    }

    printf("Largest number in the list: %d\n", max);
    printf("Smallest number in the list: %d\n", min);
}

int main() {
    int* array;
    int i, size;

    printf("Enter the size of the list (<= 10000): ");
    scanf("%d", &size);

    if(size > MAX_SIZE) {
        fprintf(stderr, "Error: List too large.\n");
        return -1;
    }

    array = malloc(size * sizeof(*array));
    if (array == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    printf("Enter %d integers:\n", size);
    for (i = 0; i < size; i++){
        scanf("%d", &array[i]);
    }

    findMinMax(array, size);

    free(array);

    return 0;
}
```

This code first prompts the user to enter a number that represents the length of an integer list. If the entered number exceeds `MAX_SIZE` (10000), the program prints out an error message and exits. Then, it dynamically allocates memory for the array using `malloc()`. After entering the numbers in the console, it calls the function `findMinMax()` which finds the smallest and largest number in the list. Finally, after usage, it frees up the memory allocated to the array with `free()`.
