```c
#include <stdio.h>
#include <stdarg.h>
#include <string.h>
#include <pthread.h>
#include <syslog.h>

#define MAX_MSG_LEN 1024
#define FLUSH_INTERVAL_SEC 60

typedef struct {
    int level;
    char message[MAX_MSG_LEN];
} LogEntry;

static LogEntry *logBuffer = NULL;
static size_t logSize = 0, logCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t lastFlushTime = 0;

void flushLog() {
    // Implement log flushing here. This may involve writing the logs to a file, rotating the files based on size or age, compressing old logs, etc.
}

void logMessage(int level, const char *format, ...) {
    pthread_mutex_lock(&lock);

    if (logCount >= logSize && !logBuffer) {
        // If the buffer is full and no compression thread is active, start one.
        pthread_t compressThread;
        pthread_create(&compressThread, NULL, flushLog, NULL);
    }

    if (logCount < logSize) {
        va_list args;
        va_start(args, format);
        vsnprintf(logBuffer[logCount].message, MAX_MSG_LEN, format, args);
        va_end(args);

        logBuffer[logCount++].level = level;
    }

    time_t now = time(NULL);
    if (now - lastFlushTime >= FLUSH_INTERVAL_SEC) {
        // If enough time has passed, flush logs.
        flushLog();
        lastFlushTime = now;
    }

    pthread_mutex_unlock(&lock);
}
```
This code will only buffer messages when the log is full and no compression thread is active. If you'd like to always maintain a constant number of buffered messages regardless of whether or not compression has finished, you could remove the `if (logCount < logSize)` check. 

Please note that this code does not include the specifics of how log rotation and compression would be implemented. You might want to use third-party libraries like zlib for compression or log4cplus for more sophisticated logging frameworks. The implementation of thread safety is also simplified for clarity - in a real system, you'd need to handle potential errors that could occur during locking.
