['```c
#include <jansson.h>
#include <openssl/evp.h>

EVP_CIPHER* select_cipher(const char* json_str) {
    json_t *root, *token, *expires;
    json_error_t error;

    root = json_loads(json_str, 0, &error);

    if(!root) {
        // Invalid JSON string. Return invalid cipher
        return NULL;
    }

    token = json_object_get(root, "access_token");
    expires = json_object_get(root, "expires_in");

    if(!json_is_string(token) || !json_string_length(token)) {
        // Invalid access_token. Return invalid cipher
        return NULL;
    }

    if(!json_is_integer(expires) || json_integer_value(expires) <= 0) {
        // Invalid expires_in. Return invalid cipher
        return NULL;
    }

    const char* token_type = json_string_value(json_object_get(root, "token_type"));
    if(!token_type || strcmp(token_type, "Bearer") != 0) {
        // Invalid token_type. Return invalid cipher
        return NULL;
    }

    const char* refresh_token = json_string_value(json_object_get(root, "refresh_token"));
    if(!refresh_token || !json_is_string(refresh_token)) {
        // Invalid refresh_token. Return invalid cipher
        return NULL;
    }

    // All fields are valid. Select a cipher based on configuration
    EVP_CIPHER* cipher = EVP_get_cipherbyname("AES-256-ECB");

    json_decref(root);

    return cipher;
}
```
Note: This code requires the OpenSSL and Jansson libraries. You may need to adjust this sample based on your specific requirements, such as how you are handling the JSON string or what configuration scheme you're using for selecting a cipher.
