                return "Name: " + pokemon.getName() + 
                        ", Weaknesses: " + weaknesses + 
                        ", Resistances: " + resistances + 
                        ", Immunities: " + immunities;
            }
        } catch (MalformedURLException ex) {
            return "Invalid URL, fallback report: Name: " + pokemon.getName() + 
