['```c
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>

typedef struct SemaphorePool {
  sem_t *semaphores;
  size_t capacity;
  size_t count;
} SemaphorePool;

void initSemaphorePool(SemaphorePool *pool, size_t initialCapacity) {
    pool->capacity = initialCapacity;
    pool->count = 0;
    pool->semaphores = malloc(sizeof(sem_t) * initialCapacity);
}

void destroySemaphorePool(SemaphorePool *pool) {
    for (size_t i = 0; i < pool->count; ++i) {
        sem_destroy(&pool->semaphores[i]);
    }
    free(pool->semaphores);
}

sem_t* allocateSemaphore(SemaphorePool *pool) {
    if (pool->count >= pool->capacity) {
        pool->capacity *= 2;
        pool->semaphores = realloc(pool->semaphores, sizeof(sem_t) * pool->capacity);
    }
    sem_init(&pool->semaphores[pool->count], 0, 1);
    ++pool->count;
    return &pool->semaphores[pool->count - 1];
}

void deallocateSemaphore(SemaphorePool *pool, sem_t *sem) {
    --pool->count;
    sem_destroy(sem);
    if (pool->count < pool->capacity / 2) {
        pool->capacity /= 2;
        pool->semaphores = realloc(pool->semaphores, sizeof(sem_t) * pool->capacity);
    }
}
```
']

