```rust
use std::fs;
use std::io::Read;
use std::path::Path;
use std::sync::Arc;
use std::thread;
use std::collections::HashSet;
use lexer::Lexer;
use parser::Parser;
use ir_generator::IrGenerator;

mod lexer {
    // Your implementation for the Lexer goes here.
}

mod parser {
    // Your implementation for the Parser goes here.
}

mod ir_generator {
    // Your implementation for the IrGenerator goes here.
}

fn parse(file_path: &str, allowed_directories: HashSet<String>) -> Result<(), String> {
    // Validate file path
    let path = Path::new(file_path);
    if !allowed_directories.contains(&path.parent().unwrap().to_string_lossy().into()) {
        return Err("Invalid directory".to_string());
    }

    // Read file content
    let mut file = match fs::File::open(file_path) {
        Ok(f) => f,
        Err(_) => return Err("Failed to open the file".to_string()),
    };
    let mut contents = String::new();
    if let Err(_) = file.read_to_string(&mut contents) {
        return Err("Failed to read the file content".to_string());
    }

    // Determine file type and create appropriate lexer, parser and IR generator
    let lexer;
    let parser;
    let ir_generator;

    if /* text file */ {
        lexer = Lexer::new(contents.clone());
        parser = Parser::new(LexerType::Text);
        ir_generator = IrGenerator::new();
    } else if /* binary file */ {
        lexer = Lexer::new(contents.clone());
        parser = Parser::new(LexerType::Binary);
        ir_generator = IrGenerator::new();
    } else {
        return Err("Unsupported file type".to_string());
    }

    // Parse the content, generate LLVM IR code and handle errors
    let parsed_nodes = match parser.parse(&lexer) {
        Ok(n) => n,
        Err(_) => return Err("Failed to parse file content".to_string()),
    };

    // Generate LLVM IR code
    ir_generator.generate(&parsed_nodes);

    Ok(())
}

fn main() {
    let allowed_directories: HashSet<String> = /* your directories */;
    let file_paths: Vec<String> = /* your files */;

    // Process files in parallel
    let handles: Vec<thread::JoinHandle<Result<(), String>>> = 
        file_paths.into_iter().map(|path| {
            let allowed_directories = Arc::new(&allowed_directories);

            thread::spawn(move || parse(&path, allowed_directories))
        }).collect();

    for handle in handles {
        match handle.join() {
            Ok(_) => println,
            Err(e) => eprintln,
        };
    }
}
```

The actual code would be much longer and more complex, requiring separate modules for lexer, parser and LLVM IR generator, with proper error handling and concurrency control. Also, it's important to note that Rust has a strong type system which allows you to catch many errors at compile-time rather than run-time, so error handling might be different from what's shown here.
']

