['Here is an example code snippet that uses Boost library for creating a sandesh client which simulates network conditions, retry mechanism, interface table mocking and concurrent request handling. 

```cpp
#include <boost/asio.hpp>
#include <boost/thread/thread.hpp>
#include <iostream>
#include <random>

class InterfaceTable {
public:
    virtual bool FindVmUuidFromMetadataIp() = 0;
};

class MockInterfaceTable : public InterfaceTable {
public:
    bool FindVmUuidFromMetadataIp() override {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> distr(0, 1);
        return distr(gen) == 1;
    }
};

void simulateNetworkConditions() {
    static thread_local std::random_device rd;
    static thread_local std::mt19937 gen(rd());
    static thread_local std::uniform_int_distribution<> distr(50, 200);
    boost::this_thread::sleep_for(boost::chrono::milliseconds(distr(gen)));
}

void handleRequest() {
    MockInterfaceTable mock;
    int retry = 0;
    while (retry < 5) {
        simulateNetworkConditions();
        if (!mock.FindVmUuidFromMetadataIp()) {
            boost::this_thread::sleep_for(boost::chrono::milliseconds((1 << retry++) * 100));
        } else {
            break;
        }
    }
}

void threadFunction() {
    handleRequest();
}

int main(int argc, char** argv) {
    if (argc < 2) {
        std::cout << "Please provide the number of requests to send.\n";
        return 1;
    }
    int num_requests = std::stoi(argv[1]);

    boost::thread_group threads;
    for (int i = 0; i < num_requests; ++i) {
        threads.create_thread(&threadFunction);
    }

    threads.join_all();

    // TODO: Implement tracking and printing of successful requests, proxy sessions, internal errors and average response time
    return 0;
}
