const fs = require('fs');
const util = require('util');
const readFile = util.promisify(fs.readFile);
const booksRegex = /(\b[A-Z][a-z]+\s)+\b/g;
const apiURL = 'https://example.com/api'; // replace with actual API URL
let excludedWords = [];

// Assume the function is given an array of book names to match, e.g., ['Genesis', 'Exodus']
async function extractBookNames(text, books) {
  const startTime = Date.now();
  text = text.replace(/[^a-zA-Z ]/g, "").toLowerCase().split(' '); // remove punctuation and convert to lowercase

  let bookMatches = {};
  for (let i = 0; i < text.length - books.length + 1; i++) {
    const slice = text.slice(i, i + books.length).join(' ');
    if (booksRegex.test(slice)) {
      bookMatches[slice] = (bookMatches[slice] || 0) + 1;
    }
  }

  // Verify accuracy with external API
  const apiResponse = await fetch(apiURL, { method: 'POST', body: JSON.stringify({books: Object.keys(bookMatches)}) });
  const verifiedBooks = (await apiResponse.json()).verifiedBooks;

  let finalResult = {};
  for (let book in bookMatches) {
    if (verifiedBooks[book] && !excludedWords.includes(book)) {
      finalResult[book] = bookMatches[book];
    }
  }

  console.log(`Time taken: ${Date.now() - startTime}ms, Matches found: ${Object.keys(finalResult).length}`);
  return finalResult;
}
```
This function works by first sanitizing the input text (removing punctuation and special characters) then using a sliding window to find book names in the text. It uses a regular expression for this purpose, with each word being split into a group of words that matches the regex pattern. The result is stored in an object where each key is a found book name, and its value is the number of times it appears in the text.

The function then sends a POST request to an external API with the list of potential books it has identified, asking for verification if they are indeed from the Old Testament or not. The response is parsed to obtain the verified books only, which are stored separately.

Finally, it compares this list with the original book matches, excluding any that were found in the excludedWords array. It also logs detailed information about the performance of the text processing before returning the final result. 

This function can be run concurrently by calling the `extractBookNames` function multiple times with different texts and books, as they are all handled independently by promises. The list of Old Testament books to match and the excluded words can also be customized.
