['```javascript
function loadModules(modules) {
  const cache = new Map(); // Caching resolved modules

  return Promise.allSettled(modules.map(({ name, version, url }) => {
    if (cache.has(url)) {
      return Promise.resolve(cache.get(url));
    }

    return fetch(url)
      .then(response => response.text()) // Fetching module content as text
      .then((content) => {
        const module = new Function("exports", "module", content)({}, { exports: {} }); // Dynamically executing the module code

        cache.set(url, module);
        return module;
      })
      .catch((error) => { // Handling network errors gracefully
        console.log(`Failed to load module ${name}@${version}:`, error);
        return null;
      });
  }));
}
```
