    function addVertex() {
        const vertexId = Math.random().toString(); // unique identifiers 
        graph.push({ id: vertexId, properties: {}, edges: [] });
    }

    function addEdge(source, destination) {
        const edgeId = Math.random().toString(); // unique identifiers
