let cache = {};
function findValues(nestedObject, targetKey, targetValue) {
    let cachedResult = cache[[targetKey, targetValue]];
   if (cachedResult !== undefined) {
        return cachedResult;
    }

    let results = [];
    for (let key in nestedObject) {
        if (!nestedObject.hasOwnProperty(key)) continue;

        if (typeof nestedObject[key] == 'object' && nestedObject[key]) {
            results = results.concat(findValues(nestedObject[key], targetKey, targetValue));
        } else if (key === targetKey && nestedObject[targetKey] === targetValue) {
            results.push(nestedObject);
        }
    }

    cache[[targetKey, targetValue]] = results;
    return results;
}
