["Here is how you could accomplish this using Rust's `hyper` library:

```rust
use std::sync::Arc;
use hyper::service::make_service_fn;
use hyper::service::service_fn::ServiceFn;
use hyper::client::{HttpConnector, HttpClient};
use hyper::Body;
use futures_util::future::join_all;
use std::sync::atomic::AtomicUsize;
use std::thread;
use std::time::Duration;
use std::net::ToSocketAddrs;
use std::io::Error as IoError;

#[derive(Debug, Clone)]
pub struct RetryClient {
    max_retries: u8,
    timeout: Duration,
}

impl RetryClient {
    pub fn new(max_retries: u8, timeout: Duration) -> Self {
        RetryClient { max_retries, timeout }
    }

    // Function to get request builder
    pub async fn get(&self, url: &str) -> Result<Body, IoError> {
        let connector = HttpConnector::new(4).unwrap(); 
        let client = HttpClient::builder()
            .timeout(self.timeout)
            .build(Arc::clone(&connector));

        let request_parts = hyper::client::request::Parts::default().uri(url);
        let mut attempts = 0;
        loop {
            match client.request(request_parts).await {
                Ok(res) if res.status().is_success() => return Ok(res.into_body()),
                Err(_e) if attempts < self.max_retries => {
                    thread::sleep(Duration::from_secs(2));
                    attempts += 1;
                },
                Err(err) => return Err(err),
            }
        }
    }
}
