use sync_lazy::SyncLazy;

#[derive(Debug)]
struct ResourceUsage {
    memory: u64,
    cpu_time: u64,
}

fn rustc_compiler() -> Result<(), String> {
    let mut hook = SyncLazy::new(|| {});

    let start = Instant::now();

    // Install logging hook.
    *hook.get() = hook::install(move || {
        let duration = start.elapsed().as_secs();
        let resource_usage: ResourceUsage = get_resource_usage();

        report(&duration, &resource_usage);
    });

    // Run Rust compiler with a custom logging hook installed.
    let output = Command::new("rustc")
        .arg("--test")
        .stderr(Stdio::piped())
        .output()
        .catch_with_exit_code(|| {
            // Handle errors that occur during compilation.
            early_error(&hook);
            0
        })?;

    // Uninstall logging hook.
    *hook.get() = std::sync::OnceCell::default();

    if !output.status.success() {
        let error = String::from_utf8(output.stderr)?;

        // Report any errors that occur during compilation.
        early_error(&hook);

        return Err(format![
            "rustc failed with status code {}: {}",
            output.status.code().unwrap_or(-1),
            error,
        ]);
    }

    Ok(())
}
