["Here is a sample solution for your problem written in C language:

```c
#include <stdlib.h>
#include <string.h>

// Define the finite state automaton (FSA) data type
typedef struct FSA {
    int state;
    char transition;
    int nextState;
} FSA;

// Define the state list data type
typedef struct StateList {
    int state;
    struct StateList *next;
} StateList;

StateList* manageFSA(int* states, int numStates, FSA* fsa, int lastState, bool includeNonFinal) 
{
    if (numStates == 0 || states == NULL || fsa == NULL) {
        return NULL; // invalid input pointers
    }

    StateList *stateList = NULL, *tail = NULL;
    int i, j;
    for(i = 0; i < numStates; ++i) 
    {
        bool isFinalState = true;
        // check if the state has transitions and if it's a final state (if needed)
        for(j = 0; j < numStates && (includeNonFinal || isFinalState); ++j) {
            if(fsa[j].state == states[i]) 
            {
                // create new node in the list
                StateList* temp = (StateList*)malloc(sizeof(StateList));
                if(temp == NULL) return NULL; // insufficient memory

                temp->state = fsa[j].nextState;
                temp->next = NULL;

                // add the node to the list
                if(stateList == NULL) 
                {
                    stateList = tail = temp;
                } 
                else 
                {
                    tail->next = temp;
                    tail = temp;
                }

                // check if it's a final state
                isFinalState &= (fsa[j].transition == '\0');
            }
        }

        if(includeNonFinal && !isFinalState) 
        {
            StateList* temp = (StateList*)malloc(sizeof(StateList));
            if(temp == NULL) return NULL; // insufficient memory

            temp->state = states[i];
            temp->next = NULL;

            // add the node to the list
            if(stateList == NULL) 
            {
                stateList = tail = temp;
            } 
            else 
            {
                tail->next = temp;
                tail = temp;
            }
        }
    }

    // update the 'next' pointer of the last state in the list to point to the newly created state list
    if(lastState != -1) 
    {
        StateList *temp = stateList;
        while (temp->state != lastState && temp != NULL) 
        {
            temp = temp->next;
        }

        if(temp != NULL) 
        {
            temp->next = stateList;
        }
    }

    return stateList; // returns the newly created state list or NULL if there is insufficient memory
}
```
Please note that this code does not handle the case when FSA has invalid transitions (transitions from a non-existing state) as it's not clearly defined in your problem. This would require more details about the FSA data structure and how to identify valid and invalid transitions.
