["Here's a C code snippet for the problem. Please note, as C is not typically used in concurrent applications, it might be harder to achieve thread safety with plain C. This example uses POSIX threads (pthreads) for threading and simple linked list for sliding window of transactions:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>

typedef struct Transaction {
    long id;
    double value, weight;
    struct timeval timestamp;
    struct Transaction *next;
} Transaction;

typedef struct {
    pthread_mutex_t lock;
    Transaction *head, *tail;
    unsigned int count;
    double sum, max_weighted_sum;
} WindowManager;

WindowManager window = {{0}, NULL, NULL, 0, 0, -1};

long getCurrentTime() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return (long) tv.tv_sec * 1000 + tv.tv_usec / 1000;
}

void pushTransaction(WindowManager* manager, Transaction* t) {
    pthread_mutex_lock(&manager->lock);

    if (manager->head == NULL) {
        manager->head = manager->tail = t;
    } else {
        manager->tail->next = t;
        manager->tail = t;
    }

    double weighted_sum = t->value * t->weight;
    if (++manager->count <= 100 && getCurrentTime() - t->timestamp.tv_sec < 3000) {
        manager->sum += weighted_sum;

        if (weighted_sum > manager->max_weighted_sum) {
            manager->max_weighted_sum = weighted_sum;
        }
    } else {
        Transaction *prev = NULL, *curr = manager->head;
        while(curr != NULL && curr->timestamp.tv_sec + 3000 >= getCurrentTime()) {
            prev = curr;
            curr = curr->next;
        }

        if (prev == NULL) {
            manager->head = t;
        } else {
            prev->next = t;
        }

        if (curr != NULL) {
            manager->sum += weighted_sum - curr->value * curr->weight;

            if(manager->max_weighted_sum == curr->value * curr->weight) {
                Transaction *temp = manager->head;
                double max_w = temp->value * temp->weight;

                while(temp != NULL && temp->timestamp.tv_sec + 3000 >= getCurrentTime()) {
                    if(max_w < temp->value * temp->weight) {
                        max_w = temp->value * temp->weight;
                    }

                    temp = temp->next;
                }

                manager->max_weighted_sum = max_w;
            } else if(weighted_sum > manager->max_weighted_sum) {
                manager->max_weighted_sum = weighted_sum;
            }

            free(curr);
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void *processTransaction(void* arg) {
    Transaction* t = (Transaction*)arg;
    pushTransaction(&window, t);
    return NULL;
}
```
This code is a very basic implementation and assumes that transactions arrive in the correct order. It could be improved by sorting incoming transactions or using more efficient data structures for better performance. For production use cases, you would likely want to use a language built for concurrent programming like Java or Go, which have more mature thread safety features.
"]

