class AttackManager {
private:
    enum class AttackStatus { Idle, Cooldown, Checking, Executed };

    struct Attack {
        std::string name;
        AttackStatus status;
    };

    using clock = std::chrono::steady_clock;
    const int cooldownTime = 9; // seconds

    std::vector<Attack> attacks{ {"attack1", AttackStatus::Idle}, {"attack2", AttackStatus::Idle} };
    clock::time_point lastAttackTime = clock::now();
    std::condition_variable cv;
    std::mutex mtx;

public:
    void selectAndExecuteAttack() {
        // Randomly shuffle the attack list for a uniform distribution
        std::shuffle(attacks.begin(), attacks.end(), std::mt19937{std::random_device{}()}); 

        Attack& selectedAttack = *std::find_if(attacks.begin(), attacks.end(), [](const auto& attack) {
            return attack.status == AttackStatus::Idle;
        });

        // Ensure cooldown period
        const auto elapsedTime = std::chrono::duration_cast<std::chrono::seconds>(clock::now() - lastAttackTime).count();
        if (elapsedTime < cooldownTime) {
            std::this_thread::sleep_for(std::chrono::seconds(cooldownTime - elapsedTime));
        }

        selectedAttack.status = AttackStatus::Checking;

        // Validate attack effectiveness asynchronously
        auto validateAttackEffectiveness = [&](const std::string& attackName) {
            bool isEffective = false;

            try {
                isEffective = isAttackEffective(attackName);
            } catch (std::exception& e) {
                std::cerr << "Failed to validate effectiveness of '" << attackName 
                          << "' due to: " << e.what() << '\n';
                isEffective = true; // Fallback option, if the external check fails
            }

            return isEffective;
        };

        bool isEffective = false;
        std::thread effectivenessCheckThread([&] {
            isEffective = validateAttackEffectiveness(selectedAttack.name);
            cv.notify_all(); // Notify the main thread that validation has been completed
        });

        {
            std::unique_lock<std::mutex> lock(mtx);

            // Wait until effectiveness check finishes or 5 seconds have passed (for potential network latency)
            cv.wait_for(lock, std::chrono::seconds(5), [&] { return isEffective; });
        }

        if (!isEffective) {
            std::cout << "Attack '" << selectedAttack.name 
                      << "' was not effective and has been skipped.\n";
        } else {
            // Execute the attack here...

            selectedAttack.status = AttackStatus::Executed;
            lastAttackTime = clock::now();
            std::cout << "Successfully executed attack '" << selectedAttack.name 
                      << "' and put it on cooldown for 9 seconds.\n";
        }

        effectivenessCheckThread.join(); // Cleanup
    }
};
```
