static void safe_memcpy(char *dst, const char *src, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        dst[i] = src[i];
    }
}

char* append_slash(Config *config, const char *str) {
    pthread_mutex_lock(&config->lock);
    size_t len = strlen(str), limit = config->limit;
    int half = limit / 2;
    if (config->append_half && len < half || !config->append_half) {
        char *result = malloc((len + 1)*sizeof(char));
        assert(result);
        safe_memcpy(result, str, len);
        result[len] = 0;
        log_operation(str, result);
        pthread_mutex_unlock(&config->lock);
        return result;
    } else {
        char *result = malloc((len + 2)*sizeof(char));
        assert(result);
        safe_memcpy(result, str, len);
        result[len] = '/';
        result[len+1] = 0;
        log_operation(str, result);
        pthread_mutex_unlock(&config->lock);
        return result;
    }
}
```
