int validateLine(char* line, double *average) {
    int fieldsCount = 0;
    double sum = 0.0;
    char* token = strtok(line, " ");

    while (token != NULL) {
        if (sscanf(token, "%lf", average) == 1) {
            sum += *average;
            fieldsCount++;
        }
        token = strtok(NULL, " ");
    }

    if (fieldsCount >= 3) {
        *average = sum / fieldsCount;
        return 0;
    } else {
        logError("Not enough numeric fields in the line.");
        return -1;
    }
}

void processLine(char* line, int lineNumber) {
    char* duplicate = malloc((strlen(line) + 1) * sizeof(char)); 

    if (duplicate == NULL) {
        logError("Failed to allocate memory for the line.");
        return;
    }

    strcpy(duplicate, line); 
    double average = 0.0;

    if (validateLine(line, &average) == 0) {
        printf("%s, %f\n", duplicate, average);
    } else {
        logError("Failed to process the line.");
    }

    free(duplicate); 
}

void* readFileByLine(void *arg) {
    FILE* file = fopen("filename.txt", "r"); 

    if (file == NULL) {
        logError("Failed to open the file.");
        return NULL;
    }

    char buffer[256];
    int lineNumber = 1;

    while (fgets(buffer, sizeof(buffer), file)) {
        processLine(buffer, lineNumber); 
        lineNumber++;
    }

    fclose(file); 
    return NULL; 
}

int main() {
