int init_cipher(CipherContext* cipher, const unsigned char *password, 
                int passlen, unsigned char *salt, int saltlen) {

    if (cipher == NULL || password == NULL || salt == NULL) return -1; // Error handling

    cipher->ctx = EVP_CIPHER_CTX_new();

