    if (PKCS5_PBKDF2_HMAC(password, passlen, salt, saltlen, 
                          2000, EVP_aes_256_cbc(), 
                          EVP_MAX_KEY_LENGTH, cipher->key) != 1) return -1; // Error handling

    /* Initialize cipher */
    if (EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, 
                           cipher->key, cipher->iv) != 1) return -1; // Error handling

    return 0;
}

void cleanup_cipher(CipherContext *cipher){
    EVP_CIPHER_CTX_free(cipher->ctx);

    free(cipher->key);
