int log_command(const char *cmd, const int cpu_usage, const int mem_usage) {
    FILE *logfile = fopen("commands.log", "a");
    if (logfile == NULL) return -1; // Logging service failure

    fprintf(logfile, "%s CPU usage: %d, Memory usage: %d\n", cmd, cpu_usage, mem_usage);
    fclose(logfile);

    return 0;
}

// The main function that runs a command in the background
int run_command(const char *cmd, const char **envp) {
    pid_t pid = fork();

    if (pid == 0) { // Child process
        int res = execve("/bin/sh", (char*[]){"sh","-c", cmd, NULL}, envp);

        // If execve returns, it means an error occurred.
        perror("execve"); 
        exit(EXIT_FAILURE);
    } else if (pid < 0) { // Fork failed
        perror("fork"); 
        return -1; 
    } else { 
        int status;
        waitpid(pid, &status, 0); // Parent waits for child to terminate

        // Here we would typically measure CPU and memory usage and log it. For simplicity, let's pretend...
        if (log_command(cmd, rand() % 100, rand() % 500) < 0){
            fprintf(stderr, "Failed to log command: %s\n", cmd);
        }

        // Return whether the child process exited successfully
        return WIFEXITED(status) && WEXITSTATUS(status) == EXIT_SUCCESS;
    }
}

int main() {
    char *cmd1[] = {"VAR=value command", NULL};
    char *cmd2[] = {"OTHERVAR=othervalue othercommand", NULL};

    // Run commands in parallel (simplified)
    int result = 0; 
    if (!run_command(cmd1[0], cmd1 + 1)) result++;
    if (!run_command(cmd2[0], cmd2 + 1)) result++;

