    private static Dictionary<string, string> cache = new Dictionary<string, string>();

    public static string DecryptAndTransform(string encryptedBase64)
    {
        if (encryptedBase64 == null) throw new ArgumentNullException("encryptedBase64");
        if (cache.ContainsKey(encryptedBase64)) return cache[encryptedBase64];

        string decrypted;
        using (TripleDES des = TripleDES.Create())
        {
            try
            {
                byte[] encryptedBytes = Convert.FromBase64String(encryptedBase64);
                ICryptoTransform decryptor = des.CreateDecryptor(des.Key, des.IV);
                byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
                decrypted = Encoding.UTF8.GetString(decryptedBytes);
            }
            catch (CryptographicException ex)
            {
                Console.WriteLine("Decryption failed: " + ex.Message);
                return null;
            }
        }

        string transformed = 
            new String(decrypted
                    .Trim()
                    .ToUpperInvariant()
                    .Select(c => Char.IsLetterOrDigit(c) ? c : '_')
                    .ToArray());

        using (MD5 md5 = MD5.Create())
        {
            byte[] hashBytes = md5.ComputeHash(Encoding.UTF8.GetBytes(transformed));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < hashBytes.Length; i++)
                sb.Append(hashBytes[i].ToString("x2"));

            cache[encryptedBase64] = sb.ToString();
        }

        return cache[encryptedBase64];
    }
}
```
