function loadAndExecuteScripts(scripts, onFinishCallback) {
    let remainingFiles = scripts.length;
    const statuses = {};

    function executeFile(url) {
        fetch(url).then(response => response.text())
            .then(data => {
                // Execute the script in a new context
                try {
                    eval(data);
                    statuses[url] = 'Success';
                } catch (e) {
                    console.error('Script execution failed: ' + url, e);
                    statuses[url] = `Error: ${e}`;
                } finally {
                    remainingFiles--;
                    if (remainingFiles === 0) {
                        onFinishCallback(statuses);
                    }
                }
            })
            .catch(error => {
                console.log('Failed to load file: ' + url, error);
                statuses[url] = `Error: ${error}`;
                remainingFiles--;
                if (remainingFiles === 0) {
                    onFinishCallback(statuses);
                }
            });
    }

    // Load and execute each script in sequence
    scripts.forEach(scriptUrl => executeFile(scriptUrl));
}
```
The `loadAndExecuteScripts` function loads and executes JavaScript files asynchronously, providing a callback with the status of each file after they have all been processed. 
It logs any errors that occur during loading or execution, preserving the rest of the application's operations.
The implementation is quite rough but gives you a good starting point for these tasks in Java/JavaScript. In practice, this could be vastly improved with more comprehensive error handling and logging.
