static LOCK: Arc<SpinLock> = Arc::new(SpinLock::unfair());
static LOGGER: Arc<log::Logger> = log::logger();

pub fn manage_config_directory(project_name: &str, config_dir_name: &str) -> Result<()> {
    let guard = LOCK.lock();

    let home_path = env::var("HOME")?;
    let project_dir = PathBuf::from(&home_path).join(project_name);
    fs::create_dir_all(&project_dir)?;

    let config_dir_full_path = project_dir.join(config_dir_name);
    if !fs::metadata(&config_dir_full_path).is_ok() {
        create_dir(&config_dir_full_path)?;
        LOGGER.log_str(log::LevelFilter::Info, "config directory created", config_dir_full_path.to_string_lossy().into_owned());
    } else {
        LOGGER.log_str(log::LevelFilter::Debug, "config directory already exists", config_dir_full_path.to_string_lossy().into_owned());
    }

    env::set_var("CONFIG_DIR_PATH", config_dir_full_path)?;

    Ok(())
}
