['Here's a sample C implementation for your problem:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int integer;
    double floating_point;
    char* string;
} dataRecord;

void readFile(char* filename, long** offsets, int** keys, double** values, dataRecord** records) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file\n");
        return;
    }

    // Get the size of the file
    fseek(file, 0L, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    *offsets = malloc((fileSize / sizeof(long)) * sizeof(long));
    *keys = malloc((fileSize / sizeof(int)) * sizeof(int));
    *values = malloc((fileSize / sizeof(double)) * sizeof(double));

    // Assume each record takes 32 bytes of data (adjust as needed)
    int numRecords = fileSize / 32;
    *records = malloc(numRecords * sizeof(dataRecord));

    for (int i = 0; i < numRecords; ++i) {
        fread(&((*records)[i].integer), sizeof(int), 1, file);
        fread(&((*values)[i]), sizeof(double), 1, file);

        int strLen;
        fread(&strLen, sizeof(int), 1, file);
        (*records)[i].string = malloc(strLen + 1); // +1 for null terminator
        fread((*records)[i].string, strLen, 1, file);
        (*records)[i].string[strLen] = '\0'; // Add null terminator
    }

    fclose(file);
}
```
This function assumes each record takes exactly 32 bytes of data (an int, a double, an integer for the string length, and the string itself). It also assumes that there are no gaps between records in the file.

The `offsets` pointer is not needed in this context as file offsets are typically expressed using `ftell` or similar library functions.

Don't forget to call `free` on each of these arrays and structures after you're done with them:
```c
