#define CHUNK_SIZE 1024 // Adjust to your needs

typedef struct {
    char *filename;
    char *new_extension;
} FileMetadata;

void* compute_md5(void *args) {
    FileMetadata *metadata = (FileMetadata*) args;
    FILE *file = fopen(metadata->filename, "rb");
    if (!file) {
        perror("Error opening file: ");
        return NULL;
    }

    MD5_CTX mdContext;
    int bytes;
    unsigned char data[CHUNK_SIZE];
    unsigned char digest[MD5_DIGEST_LENGTH];

    MD5_Init (&mdContext);
    while ((bytes = fread(data, 1, CHUNK_SIZE, file)) != 0) {
        MD5_Update(&mdContext, data, bytes);
    }
    MD5_Final(digest, &mdContext);

    char mdString[33]; // 32 hex characters and null terminator
    for (int i = 0; i < 16; ++i) {
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    }

    char new_filename[512]; // Adjust to your needs
    strcpy(new_filename, metadata->filename);
    char *dot = strrchr(new_filename, '.');
    if (dot != NULL) {
        sprintf(dot, "_%d.%s", strlen(mdString), metadata->new_extension);
    } else {
        sprintf(&new_filename[strlen(metadata->filename)], ".%s", metadata->new_extension);
    }

    FILE *output = fopen(new_filename, "wb");
    if (!output) {
        perror("Error opening output file: ");
        return NULL;
    }
    fwrite(digest, 1, MD5_DIGEST_LENGTH, output);

    fclose(file);
    fclose(output);
}

int main() {
    FileMetadata metadata = {"test.txt", "md5"}; // replace with actual values

    pthread_t thread;
    int rc = pthread_create(&thread, NULL, compute_md5, (void *) &metadata);
    if (rc) {
        printf("ERROR; return code from pthread_create() is %d\n", rc);
        exit(-1);
    }

    // Wait for the thread to finish.
    pthread_join(thread, NULL);

    return 0;
}
```
