['Sure, here's an example of how you might implement this in C. This code requires `stdlib` and `time.h` for dynamic memory allocation and random number generation respectively, as well as `errno` and `string` for error handling and file I/O.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <errno.h>
#include <string.h>

typedef struct record {
    int value;
} Record;

void read_data(const char* filename, long** offsets, int** keys, Record*** records) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file: %s\n", strerror(errno));
        exit(1);
    }

    size_t size = 0;
    char buffer[256];  // Temporary buffer for data.

    while (fgets(buffer, sizeof(buffer), file)) {
        size++;
        *offsets = realloc(*offsets, size * sizeof **offsets);
        if (*offsets == NULL) exit(1);
        srand(time(NULL));  // Seed for random number generation.
        (*offsets)[size - 1] = rand() % LONG_MAX;  // Generate a random offset within range.

        *keys = realloc(*keys, size * sizeof **keys);
        if (*keys == NULL) exit(1);
        sscanf(buffer, "%d", &((*keys)[size - 1]));  // Read the key from file.
    }

    fclose(file);

    *records = malloc(size * sizeof **records);
    if (*records == NULL) exit(1);

    for (int i = 0; i < size; ++i) {
        (*records)[i].value = (*keys)[i];  // Initialize each record with its corresponding key.
    }
}
```
This function reads a file line by line, dynamically allocating memory as needed and generating random offsets for each line. After reading all lines, it initializes an array of `record` structures, using the keys read from the file. 

When you're done with these arrays, don't forget to free the allocated memory:
```c
