```c
#include <stdio.h>
#include <string.h>
#include <zlib.h>
#include <pthread.h>
#include <curl/curl.h>

typedef struct {
    FILE *file;
    char *url;
} UploadContext;

// Function to compress data
int deflateData(char* in, int inLen, char* out, int outLen) {
    z_stream strm  = {0};
    int ret = Z_OK;

    // Initialize the stream
    ret = deflateInit(&strm, Z_BEST_COMPRESSION);
    if (ret != Z_OK) return ret;

    // Compress input data into output buffer
    strm.next_in = in;
    strm.avail_in = inLen;
    strm.next_out = out;
    strm.avail_out = outLen;

    ret = deflate(&strm, Z_FINISH);
    if (ret == Z_STREAM_END) {
        ret = Z_OK;
    }

    // Cleanup and return result
    (void)deflateEnd(&strm);
    return ret;
}

// Function to upload compressed data to URL
static size_t read_callback(void *ptr, size_t size, size_t nmemb, void *userp){
    UploadContext* ctx = (UploadContext*)userp;

    // Read and compress the file in chunks. 
    size_t bytesRead = fread(ptr, size, nmemb, ctx->file);

    if(bytesRead == 0){
        return -1;  /* no more data left to deliver */ 
    }

    // Compress the chunk of file and store in 'out' buffer.
    char out[size*nmemb];
    deflateData((char*)ptr, size*nmemb, out, sizeof(out));

    return bytesRead;
}

// Function to handle URL uploads
void *uploadFileToUrl(void *arg) {
    UploadContext* ctx = (UploadContext*) arg;

    CURL *curl_handle;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_ALL);

    /* init the curl session */ 
    curl_handle = curl_easy_init();

    /* set URL to get here */ 
    curl_easy_setopt(curl_handle, CURLOPT_URL, ctx->url);

