#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include "external_logging_library.h" // placeholder for external logging library
#include "custom_allocator.h" // placeholder for custom allocator

typedef struct NFAPI_MESSAGE_T {
    int data;
} NFAPI_MESSAGE_T;

typedef struct DynamicArray {
    NFAPI_MESSAGE_T *array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

void init(DynamicArray *a, size_t initialSize) {
    a->array = (NFAPI_MESSAGE_T *) custom_alloc(initialSize * sizeof(NFAPI_MESSAGE_T));
    if (a->array == NULL) {
        // handle out of memory
    }

    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);
}

void insert(DynamicArray *a, NFAPI_MESSAGE_T element) {
    pthread_mutex_lock(&a->lock);

    if (a->used == a->size) {
        a->size *= 2;
        a->array = (NFAPI_MESSAGE_T *) custom_realloc(a->array, a->size * sizeof(NFAPI_MESSAGE_T));

        if (a->array == NULL) {
            // handle out of memory
        }
    }

    a->array[a->used++] = element;
    external_log("Added new NFAPI_MESSAGE_T");

    pthread_mutex_unlock(&a->lock);
}

void removeByIndex(DynamicArray *a, size_t index) {
    if (index >= a->used) {
        // handle invalid index error
        return;
    }

    pthread_mutex_lock(&a->lock);

    for (size_t i = index + 1; i < a->used; ++i) {
        a->array[i - 1] = a->array[i];
    }
    --a->used;

    external_log("Removed NFAPI_MESSAGE_T at index %zu", index);

    pthread_mutex_unlock(&a->lock);
}

NFAPI_MESSAGE_T getByIndex(DynamicArray *a, size_t index) {
    if (index >= a->used) {
        // handle invalid index error
    }

    return a->array[index];
}

void freeArray(DynamicArray *a) {
    custom_free(a->array);
    a->array = NULL;
    a->used = a->size = 0;
}
```
This implementation uses a simple dynamic array. It doubles the size of the array each time it is full to minimize memory fragmentation. All operations are thread-safe by using pthread mutexes. When an operation fails (like trying to get or remove an element at an invalid index), error handling code has been commented out.

