#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <assert.h>

typedef struct Semaphore {
    sem_t *sem;
} Semaphore;

Semaphore* create_semaphore(int value) {
    assert(value >= 0);

    Semaphore* semaphore = malloc(sizeof(Semaphore));
    if (!semaphore) return NULL;

    semaphore->sem = malloc(sizeof(sem_t));
    if (sem_init(semaphore->sem, 0, value) == -1) {
        free(semaphore);
        return NULL;
    }

    return semaphore;
}

void destroy_semaphore(Semaphore* semaphore) {
    assert(semaphore != NULL);

    if (sem_destroy(semaphore->sem) == -1) {
        // Log error here.
    }

    free(semaphore->sem);
    free(semaphore);
}
```
