import java.io.*;
import java.util.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.security.NoSuchAlgorithmException;
import java.lang.Thread;

public class FileProcessor {

    private static final Map<String, String> CACHE = new HashMap<>(); 

    public static void main(String[] args) throws Exception {
        // Process file in a separate thread for concurrency handling
        Thread fileProcessingThread = new Thread(() -> processFile("filename.txt"));

        fileProcessingThread.start();
    }

    private synchronized static void processFile(String filename) {
        try (BufferedReader br = new BufferedReader(new FileReader(filename))) {
            String line;

            while ((line = br.readLine()) != null) {
                if (!validateFields(line)) {
                    // log error and continue processing next line
                    System.err.println("Error: Invalid format for line " + line);
                    continue;
                }

                String[] fields = line.split(",");
                int sum = 0;
                int fieldCount = 0;

                // Process numeric fields in reverse order to get the last three numbers
                for (int i=fields.length-1; i>=0 && fieldCount<3; --i) {
                    try {
                        sum += Integer.parseInt(fields[i].trim());
                        ++fieldCount;
                    } catch (NumberFormatException e) {
                        System.err.println("Error: Non numeric value found in line " + line);
                    }
                }

                int average = fieldCount != 0 ? sum / fieldCount : 0;

                StringBuilder sb = new StringBuilder();

                for (int i=0; i<fields.length-1; ++i) {
                    sb.append(fields[i]).append(", ");
                }

                // Append the average of last three fields
                sb.append(average);

                System.out.println(sb.toString());
            }
        } catch (IOException e) {
            System.err.println("Error: Cannot read file " + filename);
        }
    }

    private static boolean validateFields(String line) {
        String[] fields = line.split(",");

        int numCount = 0;

        for (int i=fields.length-1; i>=0 && numCount<3; --i) {
            try {
                Integer.parseInt(fields[i].trim());
                ++numCount;
            } catch (NumberFormatException e) {}
        }

        return numCount == 3;
    }

    public static String hashString(String input) throws NoSuchAlgorithmException {
        if (input == null || input.isEmpty()) {
            throw new IllegalArgumentException("Input cannot be null or empty");
        }

        // Check cache for previously computed hash
        if (CACHE.containsKey(input)) {
            return CACHE.get(input);
        }

        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hashBytes = digest.digest(input.trim().toUpperCase()
                                                    .replaceAll("\\W", "_")
                                                    .getBytes(StandardCharsets.UTF_8));

        StringBuilder hexString = new StringBuilder();

        for (byte b : hashBytes) {
            hexString.append(String.format("%02x", b));
        }

        String resultHash = hexString.toString();

        CACHE.put(input, resultHash); // Add to cache

        return resultHash;
    }
}
```
The code uses synchronized keyword for thread safety in the processFile method, ensuring that only one thread at a time can access it. The hashString method also has a basic caching mechanism implemented using a simple HashMap with strings as keys and values. This is not very sophisticated or fault tolerant; for production use, you would need to consider things like cache size limits and expiration policies, and perhaps use an established caching library.
']

