    char *base_file_name;
    char *output_ext;
} thread_data;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* convert(void *arg) {
    thread_data *data = (thread_data*) arg;

    AVFormatContext *input_format_context = NULL, *output_format_context = NULL;
    //... process files ...
    pthread_mutex_unlock(&lock);

    if (!input_format_context) return (void *)1;
    if (!output_format_context) return (void *)2;

    return (void *)0;
}

int process_audio_files(char *directory_path, char *base_file_name, char *output_ext) {
    DIR *d = opendir(directory_path); // open the directory
    if (!d) return 1;

    struct dirent *dir;
    pthread_t threads[50];
    int i = 0;
    while ((dir = readdir(d)) != NULL && i < 50) {
        char input[256], output[256];

        sprintf(input, "%s/%s", directory_path, dir->d_name); // create the full path for input file
        if (!strcmp(dir->d_name + strlen(dir->d_name) - 4, ".wav")) { // check for wav files
            sprintf(output, "%s/%s.mp3", directory_path, base_file_name); // create the full path for output file

            pthread_mutex_lock(&lock);
            thread_data data = {directory_path, base_file_name, output_ext};
            if (pthread_create(&(threads[i++]), NULL, convert, &data)) return 1; // start a new thread for each file to be converted
        }
    }

    while (--i >= 0) pthread_join(threads[i], NULL); // join all threads before returning
    closedir(d);
    return 0;
}
