};

void initializeOctreeWithRecords(int featureSize, int numLeafNodes, int dataCapacity,
                                 std::forward_list<std::string>& dataList,
                                 const std::string& searchString, const std::string& targetString) {
  // Create and initialize the octree with given size
  OctreeNode* octree = new OctreeNode[numLeafNodes];
  for (int i = 0; i < numLeafNodes; ++i) {
    octree[i].data = featureSize * i;
  }

  // Create and initialize the records with random values within a range
  std::random_device rd;
  std::mt19937 gen(rd());
  std::uniform_int_distribution<> dis(-50, 50);

  int* records = new int[dataCapacity];
  for (int i = 0; i < dataCapacity; ++i) {
    records[i] = dis(gen);
  }

  // Modify the forward list by inserting targetString after searchString if found, else append to end
  auto it = std::find(dataList.begin(), dataList.end(), searchString);
  if (it != dataList.end()) {
    dataList.insert_after(it, targetString);
  } else {
    dataList.push_front(targetString);
  }

  // Deallocate memory for octree and records
  delete[] octree;
  delete[] records;
}
