#include <ctype.h>
#include <pthread.h>
#include <sys/stat.h>

#define MAX_FILENAME 128
#define MAX_EXTENSION (5 + 3 + 1) // ".xxx" + null terminator
#define MAX_LENGTH (MAX_FILENAME + MAX_EXTENSION)

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

char* modify_filename(const char *filename, struct stat *fileStat, char **err){
    if(!filename || !err || strlen(filename) > MAX_FILENAME){
        *err = "Invalid filename or buffer overflow";
        return NULL;
    }

    pthread_mutex_lock(&lock);

    size_t len = strlen(filename);
    char newFilename[MAX_LENGTH]; // including null terminator
    int digits = 0;
    for (int i=0; isalpha((unsigned char)filename[i]) && digits<5; ++i){
        ++digits;
    }

    if(digits > 0){
        sprintf(newFilename, "%.*s.%.*s", len - digits, filename, digits, &filename[len-digits]);
    } else {
        sprintf(newFilename, "%s.txt", filename);
    }

    pthread_mutex_unlock(&lock);

    if (strlen(newFilename) > MAX_LENGTH - 1){
        *err = "New filename too long";
        return NULL;
    } else {
        *err = "";
    }

    if (fileStat != NULL){
        // process file metadata here, e.g.:
        struct stat buf;
        int ret = stat(newFilename, &buf);
        if (ret == 0) {
            *fileStat = buf;
        } else {
            *err = "Error getting file stats";
        }
    }

    return strdup(newFilename); // must free after use
}
