#include "logger.h" // You need to have a custom logger library
#define READ_BUFFER_SIZE 4096

typedef struct {
    char* filename;
    int sizeLimit;
} FileProcessingData;

void* computeHash(void* arg) {
    FileProcessingData* data = (FileProcessingData*)arg;

    MD5_CTX ctx;
    unsigned char md5[MD5_DIGEST_LENGTH];
    char buffer[READ_BUFFER_SIZE];

    FILE *inFile = fopen(data->filename, "rb");
    if (inFile == NULL) {
        logError("Failed to open the file for hash computation");
        return NULL;
    }

    MD5_Init(&ctx);
    while (!feof(inFile)) {
        size_t bytesRead = fread(buffer, 1, READ_BUFFER_SIZE, inFile);
        if (ferror(inFile)) {
            logError("Failed to read from the file for hash computation");
            return NULL;
        }

        MD5_Update(&ctx, buffer, bytesRead);
    }

    MD5_Final(md5, &ctx);

    fclose(inFile);

    // Convert md5 to hex string and append to the filename.
    char hashString[MD5_DIGEST_LENGTH*2+1];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(&hashString[i*2], "%02x", md5[i]);
    }

    char* processedFilename = malloc(strlen(data->filename) + strlen(hashString) + 1); // Assumes hashString and filename fit within limits.
    if (processedFilename == NULL) {
        logError("Failed to allocate memory for the processed filename");
        return NULL;
    }

    strcpy(processedFilename, data->filename);
    strcat(processedFilename, hashString);

    if (strlen(processedFilename) < data->sizeLimit / 2 && data->filename[strlen(data->filename) - 1] != '/') {
        processedFilename = realloc(processedFilename, strlen(processedFilename) + 2); // Assumes the allocation fits within limits.
        if (processedFilename == NULL) {
            logError("Failed to allocate memory for the slash appending in filename");
            return NULL;
        }

        strcat(processedFilename, "/");
    }

    data->filename = processedFilename; // Update the original pointer.

    logInfo("Computed hash and updated filename successfully");

    return NULL;
}

void processAndLogFilename(char* filename, int sizeLimit) {
    FileProcessingData data = {filename, sizeLimit};
    pthread_t threadId;
    if (pthread_create(&threadId, NULL, computeHash, &data)) {
        logError("Failed to create a new thread for hash computation");
        return;
    }

    // This will wait until the hash computation is finished.
    pthread_join(threadId, NULL);
}
```
