    // Determine number of digits and file type based on filename
    int numDigits = strlen(filename);
    char *fileType = strrchr(filename, '.');

    if (fileType != NULL) {
        sprintf(newFilename + MD5_DIGEST_LENGTH * 2, "_%d.%s", numDigits, fileType + 1);
    } else {
        sprintf(newFilename + MD5_DIGEST_LENGTH * 2, "_%d", numDigits);
    }

    // Rename the file to new filename
    if (rename(filename, newFilename) != 0) {
        zlog_error(logger, "Failed to rename %s to %s", filename, newFilename);
    } else {
        zlog_info(logger, "Successfully renamed %s to %s", filename, newFilename);
    }

    fclose(inFile);
}

void *file_processor(void *args) {
    file_processor_param_t *param = (file_processor_param_t *) args;
    process_file(param->filename);
