#include <errno.h>

#define BUFFER_SIZE 16384
#define MAX_FILENAME 512

// External logging system is assumed to be defined and available in the environment
extern void logOperation(const char *operation, const char *file);

typedef struct {
    char *filename;
    off_t sizeLimit;
    int priorityLevel;
} FileProcessorParams;

pthread_mutex_t processMutex = PTHREAD_MUTEX_INITIALIZER;

// Function to compute MD5 hash of file, returns the hash as a string.
char *computeMD5(const char *filename) {
    unsigned char c[MD5_DIGEST_LENGTH];
    int fd = open(filename, O_RDONLY);
    if (fd < 0) return NULL;

    MD5_CTX mdContext;
    MD5_Init(&mdContext);

    char buffer[BUFFER_SIZE];
    ssize_t bytesRead;
    while ((bytesRead = read(fd, buffer, BUFFER_SIZE)) > 0) {
        MD5_Update(&mdContext, buffer, bytesRead);
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &mdContext);

    close(fd);

    // Convert the hash to string format
    static char mdString[33];
    for (int i = 0; i < 16; ++i) {
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    }

    return mdString;
}

// Function to process a file and generate the new filename
void *processAndLogFilename(void *params) {
    FileProcessorParams *fileParams = params;

    // Obtain lock before processing the file, avoiding race conditions.
    pthread_mutex_lock(&processMutex);

    char *md5Hash = computeMD5(fileParams->filename);
    if (md5Hash == NULL) {
        logOperation("compute MD5 hash", strerror(errno));
        pthread_exit(NULL);
    }

    off_t fileSize = lseek(open(fileParams->filename, O_RDONLY), 0, SEEK_END);
    if (fileSize < 0) {
        logOperation("get file size", strerror(errno));
        pthread_exit(NULL);
    }

    char newFilename[MAX_FILENAME];
    snprintf(newFilename, MAX_FILENAME, "%s-%ld-%d-%s", md5Hash, fileSize, 
             fileParams->priorityLevel, strrchr(fileParams->filename, '.'));

    // If string length is less than half of the specified size limit and we are allowed to append a slash.
    if (strlen(newFilename) < fileParams->sizeLimit / 2 && /* check for slash append condition */ ) {
        strcat(newFilename, "/");
    }

    logOperation("original filename", fileParams->filename);
    logOperation("processed filename", newFilename);

    // Release lock as the processing is done.
    pthread_mutex_unlock(&processMutex);

    return NULL;
}
```
