DynamicArray* createDynamicArray() {
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (arr == NULL) return NULL;

    arr->capacity = 10;
    arr->size = 0;
    arr->array = malloc(sizeof(LTE_RRC_CriticalSection*) * arr->capacity);
    if (arr->array == NULL) {
        free(arr);
        return NULL;
    }

    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void addToArray(DynamicArray* arr, LTE_RRC_CriticalSection* section) {
    if (section == NULL || arr == NULL) return;

    pthread_mutex_lock(&arr->lock);

    // Resize array when full
    if (arr->size >= arr->capacity) {
        arr->capacity *= 2;  // Double the capacity each time
        LTE_RRC_CriticalSection** newArray = realloc(arr->array, sizeof(LTE_RRC_CriticalSection*) * arr->capacity);

        if (newArray == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return;
        }

        arr->array = newArray;
    }

    // Check for duplicate sequence numbers within the same transaction ID
    int duplicates = 0;
    for (size_t i = 0; i < arr->size; ++i) {
        if (arr->array[i]->LTE_RRCNAS_TransactionID == section->LTE_RRCNAS_TransactionID && 
            arr->array[i]->LTE_RRCNAS_SequenceNumber == section->LTE_RRCNAS_SequenceNumber) {
            ++duplicates;
        }
    }

    if (duplicates > 0) {
        // Handle duplicate error, e.g., by logging and discarding the new section
        pthread_mutex_unlock(&arr->lock);
        return;
    }

    arr->array[arr->size] = section;
    ++(arr->size);

    pthread_mutex_unlock(&arr->lock);
}
