typedef struct TransformationContext {
    xmlDocPtr doc;
    char *output_format;
} TransformationContext;

// Example transformation function for demonstration purpose, you may customize it according to your needs
static void transform(TransformationContext *ctx) {
    if (ctx == NULL || ctx->doc == NULL) return;
    // Transform XML to required format here. For simplicity sake, this is just a placeholder
}

static size_t write_data(void *ptr, size_t size, size_t nmemb, FILE *stream) {
    size_t written = fwrite(ptr, size, nmemb, stream);
    return written;
}

static void* download_file(void *url) {
    CURL *curl;
    FILE *fp;
    CURLcode res;

    char outfilename[FILENAME_MAX] = "/tmp/out";
    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();

    if (curl) {
        fp = fopen(outfilename,"wb");
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_data);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);

        res = curl_easy_perform(curl);

        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        fclose(fp);
    }

    return NULL;
}

static xmlDocPtr parse_document(char *url) {
    // Here is an example of parsing XML with Libxml2. Customize it according to your needs
    xmlDocPtr doc = xmlReadFile(url, NULL, 0);
    if (doc == NULL) {
        fprintf(stderr,"Failed to parse %s\n", url);
        return NULL;  // Parsing failed
    }

    xmlFreeDoc(doc);   // Free the document when done.
    xmlCleanupParser();

    return doc;
}

static void process_document(char *url, TransformationContext *ctx) {
    if (ctx == NULL || url == NULL) return; 

    pthread_t thread1, thread2;
    int status1 = pthread_create(&thread1, NULL, download_file, (void*) url);
    xmlDocPtr doc = parse_document(url);
    ctx->doc = doc;
    transform(ctx);

    if (status1 != 0) {
        printf("Thread creation failed: %d\n", status1);
        return;
    }

    pthread_join(thread2, NULL);
}

int main() {
    TransformationContext ctx = { .output_format = "JSON" };  // Initialize your context here.
    char *url = "http://example.com/document.xml";   // Your URL goes here.

    process_document(url, &ctx);

    return 0;
