typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

// Initialize the dynamic array
int initDynamicArray(DynamicArray *a, size_t initialSize) {
    a->array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initialSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (a->array == NULL) return -1; // malloc failed
    a->size = 0;
    a->capacity = initialSize;
    pthread_mutex_init(&a->mutex, NULL);
    return 0;
}

// Insert an item to the dynamic array
int insertDynamicArray(DynamicArray *a, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&a->mutex);

    if (a->size == a->capacity) { // Array is full; double the capacity
        a->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T *temp = realloc(a->array, a->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (temp == NULL) { // realloc failed
            pthread_mutex_unlock(&a->mutex);
            return -1; 
        }
        a->array = temp;
    }

    a->array[a->size++] = element;
    pthread_mutex_unlock(&a->mutex);
    return 0;
}

// Free the memory of dynamic array
void freeDynamicArray(DynamicArray *a) {
    pthread_mutex_lock(&a->mutex);
    free(a->array);
    a->array = NULL;
    a->size = 0;
    a->capacity = 0;
    pthread_mutex_unlock(&a->mutex);
}

// Generate NFAPI_CRC_INDICATION_PDU_T structures and insert them to the dynamic array
