#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <glib.h>

typedef struct {
    int LTE_RRCNAS_TransactionID;
    char *LTE_RRCNAS_Message;
    unsigned LTE_RRCNAS_SequenceNumber;
} LTE_RRC_CriticalSections;

GHashTable* transactions = NULL;
pthread_mutex_t lock; 

void initAndManageCriticalSectionArray(LTE_RRC_CriticalSections *array, int arraySize) {
    pthread_mutex_init(&lock, NULL);
    transactions = g_hash_table_new(g_int_hash, g_int_equal);  // Create a new hash table for efficient sequence number checking

    for (int i = 0; i < arraySize; i++) {
        LTE_RRC_CriticalSections *criticalSection = &array[i];

        pthread_mutex_lock(&lock);  // Lock the critical section to avoid race conditions

        if (g_hash_table_contains(transactions, &criticalSection->LTE_RRCNAS_TransactionID)) {
            GHashTable *sequenceNumbers = g_hash_table_lookup(transactions, &criticalSection->LTE_RRCNAS_TransactionID);
            if (g_hash_table_contains(sequenceNumbers, &criticalSection->LTE_RRCNAS_SequenceNumber)) {
                printf("Duplicate sequence number found for transaction ID %d. Ignoring this critical section.\n", criticalSection->LTE_RRCNAS_TransactionID);
                continue;  // Skip if the sequence number already exists in this transaction ID
            } else {
                g_hash_table_add(sequenceNumbers, &criticalSection->LTE_RRCNAS_SequenceNumber);  // Add the new sequence number to the list for this transaction ID
            }
        } else {
            GHashTable *newTransaction = g_hash_table_new(g_int_hash, g_int_equal);
            g_hash_table_add(newTransaction, &criticalSection->LTE_RRCNAS_SequenceNumber);  // Add the new sequence number to a new list for this transaction ID
            g_hash_table_insert(transactions, &criticalSection->LTE_RRCNAS_TransactionID, newTransaction);  // Insert the new list into the main hash table
        }

        pthread_mutex_unlock(&lock);  // Unlock the critical section after processing
    }

    g_hash_table_destroy(transactions);  // Cleanup when done
}
```

This code snippet assumes `LTE_RRCNAS_TransactionID` and `LTE_RRCNAS_SequenceNumber` are integers, adjust the type definitions and hash functions accordingly if they're different. Furthermore, it logs an error message but does not prevent further execution in case of duplicate sequence numbers. Depending on your specific needs, you might want to handle these errors differently (e.g., by throwing exceptions or exiting the program).

