// AES, Camellia and SHA-256 cipher primitives are represented as structs
typedef struct aes_ctx {
  AES_KEY key;
} aes_ctx;

typedef struct camellia_ctx {
  CAMELLIA_KEY key;
} camellia_ctx;

typedef struct sha256_ctx {
  SHA256_CTX ctx;
} sha256_ctx;

// Initialize the cryptographic primitives with keys and other setup.
void aes_init(aes_ctx *ctx, const unsigned char *key) {
  AES_set_encrypt_key(key, 128, &(ctx->key));
}

// Do the same for Camellia and SHA-256.
void camellia_init(camellia_ctx *ctx, const unsigned char *key) {
  CAMELLIA_set_key_enc(&(ctx->key), key);
}

void sha256_init(sha256_ctx *ctx) {
  SHA256_Init(&(ctx->ctx));
}

// Then we define the functions for ciphering and hashing.
void aes_encrypt(aes_ctx *ctx, const unsigned char *in, unsigned char *out) {
  AES_ecb_encrypt(in, out, &(ctx->key), AES_ENCRYPT);
}

// Do the same for Camellia and SHA-256.
void camellia_encrypt(camellia_ctx *ctx, const unsigned char *in, unsigned char *out) {
  CAMELLIA_ecb_encrypt(in, out, &(ctx->key), AES_ENCRYPT);
}

void sha256_update(sha256_ctx *ctx, const void *data, size_t len) {
  SHA256_Update(&(ctx->ctx), data, len);
}

// Now we define the main function that uses these primitives.
void cryptographic_operation(aes_ctx *aes_context, camellia_ctx *camellia_context, sha256_ctx *sha256_context, const unsigned char *input, size_t len, unsigned char *output) {
  aes_encrypt(aes_context, input, output);
  camellia_encrypt(camellia_context, output, output);
  sha256_update(sha256_context, output, len);
}
