    manager->count = 0;
    manager->packets = NULL;
    pthread_mutex_init(&manager->mutex, NULL);
}

void PacketManager_AddPacket(PacketManager* manager, MAC_PACKET packet) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->count > 0 && manager->packets[manager->count - 1].dst_ip == packet.dst_ip) {
        // To avoid congestion, ignore packets with the same destination IP as the previous one
        pthread_mutex_unlock(&manager->mutex);
        return;
    }

    manager->packets = realloc(manager->packets, sizeof(MAC_PACKET) * (manager->count + 1));
    manager->packets[manager->count] = packet;
    manager->count++;

    pthread_mutex_unlock(&manager->mutex);
}

void PacketManager_Destroy(PacketManager* manager) {
    free(manager->packets);
    pthread_mutex_destroy(&manager->mutex);
}
```
