// A dynamically growing array of structures.
NFAPI_UL_AZT *array = NULL;
size_t size = 0, capacity = 0;

void addStructure(int PHY_CELL_ID, int PCI, float SNR_DB) {
    pthread_mutex_lock(&lock); // Ensure thread safety.

    if (capacity == size) {
        // If we need to allocate more memory, calculate the new capacity.
        size_t newCapacity = capacity == 0 ? 1 : 2 * capacity;
        NFAPI_UL_AZT *newArray = realloc(array, sizeof(NFAPI_UL_AZT) * newCapacity);
        if (newArray == NULL) {
            // Handle out of memory error.
            pthread_mutex_unlock(&lock);
            return;
        }

        array = newArray;
        capacity = newCapacity;
    }

    // Add the structure to the array.
    NFAPI_UL_AZT *newStructure = &array[size];
    newStructure->PHY_CELL_ID = PHY_CELL_ID;
    newStructure->PCI = PCI;
    newStructure->SNR_DB = SNR_DB;
    ++size;

    // Ensure that no two consecutive structures have the same PCI.
    if (size > 1 && array[size - 2].PCI == PCI) {
        // Handle error: duplicate PCI value.

        --size; // Remove the last structure.
    }

    pthread_mutex_unlock(&lock);
}

void aggregate() {
    pthread_mutex_lock(&lock);

    size_t newSize = (float)size * REDUCTION_FACTOR;
    NFAPI_UL_AZT *newArray = realloc(array, sizeof(NFAPI_UL_AZT) * newSize);
    if (newArray == NULL) {
        // Handle out of memory error.
        pthread_mutex_unlock(&lock);
        return;
    }

    array = newArray;
    size = newSize;
    capacity = newSize;

    pthread_mutex_unlock(&lock);
}
