["Here's a rudimentary approach in C. We are assuming the `ElementInfo` structure contains the fields `tagName`, `attributes`, and `childNodes` which are character arrays, character pointers, and another ElementInfo array respectively. The memory management strategy is a simplistic Binary Search Tree (BST) where nodes can be dynamically created or deleted without requiring complete re-allocation of the tree. It's thread safe with use of mutexes, but there are potential bottlenecks that could be optimized depending on further requirements.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct ElementInfo {
    char *tagName;
    char **attributes; //Assuming attribute is an array of character pointers 
    struct ElementInfo **childNodes; //Assuming child nodes are an array of ElementInfo pointers
} ElementInfo;

ElementInfo* createNode(char* tag, int attrCount, int childrenCount) {
    ElementInfo* node = (ElementInfo*) malloc(sizeof(ElementInfo));
    node->tagName = tag;
    node->attributes = (char**) calloc(attrCount, sizeof(char*));
    node->childNodes = (ElementInfo**) calloc(childrenCount, sizeof(ElementInfo*));
    return node;
}

void deleteNode(ElementInfo *node){
    free(node->tagName);
    for(int i=0;i<attrCount;i++) {
        free(node->attributes[i]);
    }
    free(node->attributes);

    for(int i = 0; i < childrenCount; i++){
        deleteNode(node->childNodes[i]);
    }
    free(node->childNodes);
    free(node);
}

typedef struct BST {
    ElementInfo *data;
    pthread_mutex_t lock;
    struct BST *left, *right;
} BST;

BST* newNode(ElementInfo* data) {
    BST* node = (BST*)malloc(sizeof(BST));
    node->data  = data;
    node->left   = NULL;
    node->right  = NULL;
    pthread_mutex_init(&node->lock, NULL);

    return(node);
}

void insertNode(BST* root, ElementInfo *info) {
    if (root == NULL) {
        root = newNode(info);
    } else if (strcmp(info->tagName, root->data->tagName) > 0) {
        pthread_mutex_lock(&root->lock);
        insertNode(root->right, info);
        pthread_mutex_unlock(&root->lock);
    } else if (strcmp(info->tagName, root->data->tagName) < 0){
        pthread_mutex_lock(&root->lock);
        insertNode(root->left, info);
        pthread_mutex_unlock(&root->lock);
    }
}
```
This code is a very simplistic approach. It doesn't consider the memory fragmentation and reallocation issues. For these scenarios, you would need to use different strategies such as Buddy Allocators or Slab Allocators that allocates fixed size blocks from a pool of already allocated objects. Also, it does not implement garbage collection for excessively used memory. That can be implemented with a separate thread that monitors the heap usage and deallocates nodes when required.
"]

