typedef struct {
    EVP_CIPHER_CTX* ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} cipher_data;

cipher_data* init_cipher(const char* passphrase, const unsigned char* salt) {
    EVP_PKEY_CTX *pctx = NULL;
    pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_HKDF, NULL);

    if (EVP_PKEY_derive_init(pctx) <= 0 ||
        EVP_PKEY_hkdf_ctrl(pctx, -1, EVP_PKSALT, salt, strlen((const char*)salt)) <= 0 ||
        EVP_PKEY_CTX_set_hkdf_md(pctx, EVP_sha256()) <= 0) {
        return NULL;
    }

    if (EVP_PKEY_derive(pctx, NULL, &key_len) <= 0 || key_len != sizeof(key)) {
        return NULL;
    }

    if (EVP_PKEY_derive(pctx, key, NULL) <= 0) {
        return NULL;
    }

    EVP_PKEY_CTX_free(pctx);

    cipher_data* data = malloc(sizeof(cipher_data));
    if (data == NULL) {
        return NULL;
    }

    // Initialize the encryption context with AES-256-GCM
    EVP_CIPHER_CTX_init(&data->ctx);
    data->ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(data->ctx, EVP_aes_256_gcm(), NULL, key, iv);

    // Generate random IV and set it for the context
    RAND_bytes(iv, sizeof(iv));
    data->iv = iv;

    return data;
}

void cleanup_cipher(cipher_data* cipher) {
    if (cipher != NULL) {
        EVP_CIPHER_CTX_cleanup(cipher->ctx);
        free(cipher);
    }
}
