        self.buffer = deque() # Use a buffer to store incoming data packets
        self.latest_offset = 0

    def consume_data(self, topics):
        try:
            self.consumer.subscribe(topics)

            while True:
                msg = self.consumer.poll(timeout=1.0) # Poll for new data packets every second

                if msg is None: continue
                if msg.error(): raise KafkaException(msg.error())

                self._process_packet(msg.value()) # Process the packet
