// Thread safe memory deallocation. Batch strategy is considered to reduce system calls and improve performance.
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Initialize a global lock
void batchFree(cipher *data, int size) {
    pthread_mutex_lock(&mutex);  // Lock before accessing shared data.

    for (int i = 0; i < size; i++) {
