unsigned char* getMD5HashFromFile(const std::string& filename) {
    unsigned char c[MD5_DIGEST_LENGTH];

    FILE *file = fopen (filename.c_str(), "rb");
    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    if (file == NULL) {
