import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public String hashStringMD5(String str) {
    if (str == null || str.isEmpty()) return null; // Return graceful failure on invalid input

    try {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(str.getBytes(StandardCharsets.UTF_8));

        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) 
            sb.append(String.format("%02x", b & 0xff));

        return sb.toString();
    } catch (NoSuchAlgorithmException e) {
        // This shouldn't ever happen with "MD5" as input, so we can safely ignore it here
        throw new RuntimeException(e);
    }
}
```
