import java.util.logging.*;

public class DeviceValidator {
    private static final Logger logger = Logger.getLogger(DeviceValidator.class.getName());

    public List<String> validateDevices(List<NetworkDevice> devices) {
        List<String> reports = new ArrayList<>();

        for (NetworkDevice device : devices) {
            String report;

            switch (device.getType()) {
                case "router":
                    report = validateRouterConfiguration(device);
                    break;
                case "switch":
                    report = validateSwitchConfiguration(device);
                    break;
                default:
                    logger.log(Level.SEVERE, "Unsupported device type: " + device.getType());
                    continue; // ignore unsupported devices and move to the next one
            }

            reports.add(report);
        }

        return reports;
    }

    private String validateRouterConfiguration(NetworkDevice router) {
        try {
            Configuration configuration = UtilityFunctions.parseConfigurationFile(router.getConfigurationFile());

            if (!UtilityFunctions.isValidIPAddress(configuration.getIp())) {
                return "Invalid IP address for router: " + configuration.getIp();
            }
            // add more validation checks as needed
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error validating router configuration", e);
            return "Error validating router configuration";
        }

        return "Router is correctly configured.";
    }

    private String validateSwitchConfiguration(NetworkDevice switchDevice) {
        try {
            Configuration configuration = UtilityFunctions.parseConfigurationFile(switchDevice.getConfigurationFile());

            if (!UtilityFunctions.isValidIPAddress(configuration.getIp())) {
                return "Invalid IP address for switch: " + configuration.getIp();
            }
            // add more validation checks as needed
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error validating switch configuration", e);
            return "Error validating switch configuration";
        }

        return "Switch is correctly configured.";
    }
}
