typedef struct {
    int value;
} record;

void process_data(const char* filename, long offset_range) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Determine the number of records by counting lines in the file.
    int num_records = 0;
    int ch;
    while ((ch = fgetc(file)) != EOF) {
        if (ch == '\n') ++num_records;
    }

    // Allocate memory for arrays and structures.
    long* offsets = malloc(sizeof(*offsets) * num_records);
    int* keys = malloc(sizeof(*keys) * num_records);
    record* records = malloc(sizeof(*records) * num_records);

    // Reset file pointer to beginning.
    fseek(file, 0L, SEEK_SET);

    // Read keys from the file and initialize arrays with random offsets.
    srand((unsigned int) time(NULL));
    for (int i = 0; i < num_records; ++i) {
        fscanf(file, "%d", &keys[i]);
        offsets[i] = rand() % offset_range;  // random offset within range

        records[i].value = keys[i];   // initialize record's value with key
    }

    fclose(file);

    // Process data...

    free(records);
    free(offsets);
    free(keys);
}
```
Note: This code assumes a file that contains one integer per line. It counts the number of lines in the file to determine how many records are needed, then allocates memory for arrays and structures accordingly. After reading keys from the file, it initializes each record's value with corresponding key and generates random offset within specified range for each record. At the end, it frees all allocated memory. It also assumes that `offset_range` is a non-negative integer denoting maximum value of generated offsets.
