        pthread_mutex_lock(&lock);
        while (isPaused) {
            pthread_cond_wait(&cond, &lock);
        }

        // Assuming data from stream is 'long', 'int' and 'double'
        long offset = rand() % 100;
        int key = rand() % 100;
        double value = ((double)rand()) / RAND_MAX;

        // Reallocate memory as needed for arrays
        if (i >= records_count) {
            records_count += 50;

            offsets = realloc(offsets, sizeof(*offsets)*records_count);
            keys = realloc(keys, sizeof(*keys)*records_count);
            precision_values = realloc(precision_values, sizeof(*precision_values)*records_count);
            records = realloc(records, sizeof(*records)*records_count);
        }

        // Store data in arrays
        offsets[i] = offset;
        keys[i] = key;
        precision_values[i] = value;

        // Generate record with unique identifier and empty metadata
        records[i] = malloc(sizeof(**records));
        asprintf(&records[i]->name, "record-%zu", i);
        records[i]->value = 0.0;

        records[i]->md = malloc(sizeof(*records[i]->md));
        records[i]->md->count = 0;
        records[i]->md->values = NULL;

        pthread_mutex_unlock(&lock);
    }

    return NULL;
}
