#include <stdlib.h>
#include <math.h>

#define BUFFER_SIZE 1024
#define MAX_EVENTS 500000
#define TIMESTAMP_LEN 32
#define EVENTTYPE_LEN 64
#define DURATION_LEN 32
#define LOGDETAILS_LEN 1024

typedef struct {
    char eventType[EVENTTYPE_LEN];
    double totalDuration;
    int count;
} EventSummary;

void processCSVFile(char *inputFileName, char *outputFileName, char *aggregationRules, int includeDetailedLogs, double performanceThreshold) {

    FILE *file = fopen(inputFileName, "r");
    if (file == NULL) {
        printf("Error opening the file.\n");
        return;
    }

    char buffer[BUFFER_SIZE];
    int numEvents = 0;
    time_t startTimes[MAX_EVENTS], endTimes[MAX_EVENTS];
    double durations[MAX_EVENTS];
    EventSummary eventSummaries[MAX_EVENTS];

    while (fgets(buffer, BUFFER_SIZE, file)) {
        if (numEvents == MAX_EVENTS) {
            printf("Reached maximum number of events. Increase the value of MAX_EVENTS.\n");
            break;
        }

        char timestamp[TIMESTAMP_LEN], eventType[EVENTTYPE_LEN], duration[DURATION_LEN], logDetails[LOGDETAILS_LEN];
        sscanf(buffer, "%s,%s,%s,%s", timestamp, eventType, duration, logDetails);

        startTimes[numEvents] = strtoul(timestamp, NULL, 10);
        endTimes[numEvents] = startTimes[numEvents];
        durations[numEvents] = atof(duration);

        int eventIndex;
        for (eventIndex = 0; eventIndex < numEvents; ++eventIndex) {
            if (strcmp(eventType, eventSummaries[eventIndex].eventType) == 0)
                break;
        }
        if (eventIndex == numEvents) {
            strncpy(eventSummaries[numEvents].eventType, eventType, EVENTTYPE_LEN);
            eventSummaries[numEvents].totalDuration = durations[numEvents];
            eventSummaries[numEvents++].count = 1;
        } else {
            ++eventSummaries[eventIndex].count;
            eventSummaries[eventIndex].totalDuration += durations[numEvents];
        }
    }

    fclose(file);

    FILE *outputFile = fopen(outputFileName, "w");
    if (outputFile == NULL) {
        printf("Error opening the output file.\n");
        return;
    }

    int eventIndex;
    for (eventIndex = 0; eventIndex < numEvents; ++eventIndex) {
        fprintf(outputFile, "%s: %d events, average duration: %.2f\n", eventSummaries[eventIndex].eventType, 
                eventSummaries[eventIndex].count, eventSummaries[eventIndex].totalDuration / (double)eventSummaries[eventIndex].count);
    }

    fclose(outputFile);
}
```
