#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    unsigned int index;
    char* string;
    double min, max;
} ConfigRecord;

void generate_data(ConfigRecord *record, double **doubles, unsigned int **indices, char ***strings) {
    FILE *file = fopen("config.txt", "r");
    if (file == NULL) {
        perror("Error opening file");
        return;
    }

    size_t len = 0;
    ssize_t read;
    char *line = NULL, *endptr;

    while ((read = getline(&line, &len, file)) != -1) {
        record->index = strtoul(line, &endptr, 10);
        if (record->index == 0 && errno == ERANGE) {
            perror("Invalid unsigned int");
            continue;
        }

        *strings = realloc(*strings, (record->index + 1) * sizeof(char *));
        (*strings)[record->index] = malloc((strlen(endptr) + 1) * sizeof(char));
        strcpy((*strings)[record->index], endptr);

        record->min = strtod(fgets(line, read, file), &endptr);
        if (errno == ERANGE) {
            perror("Invalid double");
            continue;
        }

        record->max = strtod(endptr, NULL);
        if (errno == ERANGE) {
            perror("Invalid double");
            continue;
        }

        *doubles = realloc(*doubles, (record->index + 1) * sizeof(double));
        (*indices) = realloc(*indices, (record->index + 1) * sizeof(unsigned int));

        srand((unsigned int) time(NULL) + record->index);
        for (size_t i = 0; i <= record->index; ++i) {
            (*doubles)[i] = ((double) rand() / RAND_MAX) * (record->max - record->min) + record->min;
            (*indices)[i] = i;
        }
    }

    free(line);
    fclose(file);
}
```

