['Here is an example implementation in Java using Kafka as the distributed NoSQL database, Spring Boot for creating Restful services and Hazelcast as an in-memory distributed data grid:

```java
import com.hazelcast.core.Hazelcast;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import java.util.*;

@SpringBootApplication
public class EventStreamingPlatform {

    private KafkaProducer<String, byte[]> producer;
    private HazelcastInstance hazelcastInstance;

    public static void main(String[] args) {
        SpringApplication.run(EventStreamingPlatform.class, args);
    }

    // Constructor to initialize Kafka Producer and Hazelcast instance
    public EventStreamingPlatform() {
        Properties props = new Properties();
        props.put("bootstrap.servers", "localhost:9092");
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.ByteArraySerializer");
        producer = new KafkaProducer<>(props);
        hazelcastInstance = Hazelcast.newHazelcastInstance();
    }

    // Method to publish event on kafka topic
    public void publishEvent(String topic, byte[] event) {
        producer.send(new ProducerRecord<>(topic, UUID.randomUUID().toString(), compressData(event)));
    }

    // Custom data compression method
    public static byte[] compressData(byte[] input) {
        Deflater compressor = new Deflater();
        compressor.setInput(input);
        compressor.finish();
        ByteArrayOutputStream bos = new ByteArrayOutputStream(input.length);

        try {
            byte[] buf = new byte[1024];
            while (!compressor.finished()) {
                int count = compressor.deflate(buf);
                bos.write(buf, 0, count);
            }
        } finally {
            compressor.end();
        }
        return bos.toByteArray();
    }

    // Other methods and classes...
}
```

Please note that this is a simplified example to give you an idea of how it can be done. In a real-world scenario, there would need to be additional components for deduplication, schema validation, error handling, caching, event correlation, namespace management etc. 

