#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // ... structure members here ...
} TX_FRAME_DESCRIPTOR_T;

typedef struct {
    // ... structure members here ...
} TX_RLC_AM_HEADER_T;

// and so on for all the structures...

typedef struct node{
    TX_FRAME_DESCRIPTOR_T txFrameDescriptor;
    float SNR;
    struct node* next;
} Node;

Node *head = NULL, *tail = NULL;
pthread_mutex_t lock;
int filter_threshold = 0; // Configurable threshold for filtering.

void manageList(float loadFactor) {
    pthread_mutex_lock(&lock);

    int size = (int)(loadFactor * 1e6); // Calculate size based on system load factor.
    if (size < 1000) size = 1000; // Ensure there's a minimum of 1000 structures.

    float snr_value = -128.f; // Start from the lowest possible SNR value.

    for(int i=0;i<size;++i){
        Node* newNode = malloc(sizeof(Node));

        if(!newNode) {
            printf("Failed to allocate memory.\n");
            pthread_mutex_unlock(&lock);
            return;
        }

        // Assign the SNR value. Increment it until it's unique or wrap around to a new range.
        do {
            snr_value += 1.f;

            if(snr_value > 127.f)
                snr_value = -128.f; // Wrap around to negative SNR values.

        } while (snr_value == tail->SNR || snr_value == head->SNR);

        newNode->txFrameDescriptor = createTxFrame(snr_value); // Fill txFrameDescriptor with appropriate data.
        newNode->SNR = snr_value;

        if(!head){
            head = tail = newNode;
            newNode->next = NULL;
        } else {
            Node* current = head;

            while(current && current->SNR >= filter_threshold)
                current = current->next;

            if(!current || (current != head && abs(current->SNR - snr_value) > 1.f)) { // Check for SNR difference of 1 to prevent consecutive structures from having the same SNR value.
                newNode->next = current;
                head = newNode;
