        fprintf(logFile, "Input string exceeds the specified limit\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char *output = malloc((appendSlash && length < limit/2 ? length+2 : length+1) * sizeof(char));

    if (output == NULL) {
        fprintf(logFile, "Memory allocation failure\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    memcpy(output, input, length);

    if (appendSlash && length < limit/2) {
        output[length] = '/';
        output[length+1] = '\0';
    } else {
        output[length] = '\0';
    }

    fprintf(logFile, "Original string: %s\nProcessed string: %s\n", input, output);

    pthread_mutex_unlock(&lock);

    return output;
