import java.io.*;
import javax.cache.Cache;
import javax.cache.Caching;

public class MoSTStateLoader {
    private Cache<String, Object> cache;

    public MoSTStateLoader() {
        // Create a caching provider
        CachingProviderFactory caching = Caching.getCachingProvider();

        // Access the default cache manager and create a cache named "mostStates"
        CacheManager manager = caching.getCacheManager();
        cache = manager.createCache("mostStates", new MutableConfiguration<>());
    }

    public MoSTState loadMoSTStateFromFile(String fileName) {
        ObjectInputStream inputStream = null;

        try {
            // Try to read from the cache first
            MoSTState state = (MoSTState)cache.get(fileName);

            if (state != null) return state;

            FileInputStream fileIn = new FileInputStream(fileName);
            inputStream = new ObjectInputStream(fileIn);

            // Read the object from the file
            Object obj = inputStream.readObject();

            if (obj instanceof MoSTState) {
                state = (MoSTState)obj;

                // Cache the read object for future use
                cache.put(fileName, state);

                return state;
            } else {
                System.out.println("File does not contain a MoSTState instance");
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        } finally {
            // Ensure the ObjectInputStream is closed even if an exception was thrown
            if (inputStream != null) try { inputStream.close(); } catch (IOException e) {}
        }

        return null;
    }
}
