from lxml import etree

def validateXMLDocument(xmlString):
    # Load XML schema definition
    with open("schema.xsd", "r") as schema_file:
        schema_doc = etree.parse(schema_file)

    schema = etree.XMLSchema(schema_doc)

    # Parse XML document
    try:
        doc = etree.fromstring(xmlString)
    except etree.XMLSyntaxError as e:
        print("Failed to parse the XML document")
        return False

    # Validate XML document against schema
