public class PokemonService {
    private final ReentrantLock lock = new ReentrantLock();

    // Map to store weaknesses for each type
    private static Map<String, List<String>> weaknessMap = new HashMap<>() {{
        put("fire", Arrays.asList("water", "grass"));
        put("water", Arrays.asList("electric", "grass"));
        // Add other types and their corresponding weaknesses here...
    }};

    public String getWeaknesses(Pokemon pokemon) {
        if (pokemon == null || pokemon.getName() == null || pokemon.getType() == null) 
            throw new IllegalArgumentException("Invalid Pokemon or missing data.");

        lock.lock(); // Ensure thread safety while reading from map
        try {
            StringBuilder weaknesses = new StringBuilder(pokemon.getName()).append(" is weak against: ");
            for (String type : pokemon.getType()) {
                List<String> weaknessList = weaknessMap.get(type);
                if (weaknessList != null) {
                    weaknesses.append(String.join(", ", weaknessList));
                } else {
                    weaknesses.append("Unknown type: ").append(type);
                }
            }
            return weaknesses.toString();
        } finally {
            lock.unlock(); // Unlock after reading from map
        }
    }
}
