```python
import hashlib
import json
import multiprocessing
from datetime import datetime

class GraphDatabaseSystem:
    def __init__(self):
        self.vertices = {}
        self.edges = []
        self.logs = []

    def _calculate_checksum(self, data):
        checksum = hashlib.md5()
        checksum.update(data)
        return checksum.hexdigest()

    def add_vertex(self, vertex):
        self.vertices[vertex] = 1
        checksum = self._calculate_checksum(json.dumps(vertex).encode())
        self.logs.append({'action': 'add', 'type': 'vertex', 'time': datetime.now().isoformat(), 'data': vertex, 'checksum': checksum})

    def add_edge(self, edge):
        self.edges.append(edge)
        checksum = self._calculate_checksum(json.dumps(edge).encode())
        self.logs.append({'action': 'add', 'type': 'edge', 'time': datetime.now().isoformat(), 'data': edge, 'checksum': checksum})

    def add_vertices_and_edges(self, vertices, edges):
        pool = multiprocessing.Pool()
        for vertex in vertices:
            pool.apply_async(self.add_vertex, (vertex,))
        for edge in edges:
            pool.apply_async(self.add_edge, (edge,))
        pool.close()
        pool.join()

    def verify_integrity(self):
        for log in self.logs:
            data = json.dumps(log['data']).encode()
            if self._calculate_checksum(data) != log['checksum']:
                print('Data integrity check failed for action', log['action'], 'and type', log['type'])

    def read_config(self, filename):
        try:
            with open(filename, 'r') as file:
                config = json.load(file)
            self.max_vertices_per_node = config.get('max_vertices_per_node', 1000)
            self.checkpoint_intervals = config.get('checkpoint_intervals', [60, 300])
