```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void readData(const char* filename, long** offsets, int** keys, record*** records, size_t* numElements) {
    FILE *file = fopen(filename, "r");

    if (file == NULL) {
        perror("Error opening the file.\n");
        exit(EXIT_FAILURE);
    }

    // Determine number of elements in file.
    fseek(file, 0L, SEEK_END);
    *numElements = ftell(file) / sizeof(int);

    rewind(file);

    // Allocate memory.
    *offsets = malloc(*numElements * sizeof(long));
    if (*offsets == NULL) { 
        perror("Could not allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(*numElements * sizeof(int));
    if (*keys == NULL) {
        perror("Could not allocate memory for keys.\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    *records = malloc(*numElements * sizeof(record*));
    if (*records == NULL) {
        perror("Could not allocate memory for records.\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Read data from file.
    for (size_t i = 0; i < *numElements; ++i) {
        fread(&((*keys)[i]), sizeof(int), 1, file);

        srand(time(NULL)); // Initialization, should only be called once.
        (*offsets)[i] = rand() % LONG_MAX; // Random offset value within long range.

        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            perror("Could not allocate memory for a record.\n");
            free(offsets);
            free(keys);

            // Free previously allocated records.
            for (size_t j = 0; j < i; ++j) {
                free((*records)[j]);
            }
            free(records);
            exit(EXIT_FAILURE);
        }

        (*records)[i]->value = (*keys)[i]; // Assign value from key.
    }

    fclose(file);
}
```

