#include <sys/stat.h>
#include <errno.h>

typedef struct {
    char* filename;
} NFAPI_CRC_INDICATION_PDU_T;

unsigned char* computeMD5(const char* filename) {
    int file_descript = open(filename, O_RDONLY);
    if (file_descript < 0) {
        printf("Failed to open %s: %s\n", filename, strerror(errno));
        return NULL;
    }

    MD5_CTX context;
    MD5_Init(&context);

    unsigned char buffer[8192];
    ssize_t bytesRead;
    while ((bytesRead = read(file_descript, buffer, sizeof(buffer))) > 0) {
        MD5_Update(&context, buffer, bytesRead);
    }

    if (bytesRead < 0) {
        printf("Failed to read from %s: %s\n", filename, strerror(errno));
        return NULL;
    }

    unsigned char* md5 = malloc(MD5_DIGEST_LENGTH);
    MD5_Final(md5, &context);

    close(file_descript);

    return md5;
}
``` 

This is a simple function that computes the MD5 hash of a file. It uses OpenSSL's MD5 functions to compute the hash and read from files using Linux system calls directly, which should be efficient for high-throughput data processing. However, please note that this function does not handle memory allocation failures gracefully, nor does it have unit tests or any kind of error handling beyond file I/O errors. You would need to add these features as part of your own development project.
