    char *logs;
    int num_logs;
} LogBatch;

void* process_batch(void *arg) {
    // In this function, you would implement the logic to parse a batch of logs, 
    // calculate statistics, and potentially handle errors.
}

void batch_process_logs_and_stat_aggregation(char *directory_path) {
    DIR *dir;
    struct dirent *ent;

    if ((dir = opendir (directory_path)) != NULL) {
        // Initialize log batches with 10,000 logs each.
        LogBatch **batches = malloc(sizeof(LogBatch*));
        int num_batches = 0;

        while ((ent = readdir (dir)) != NULL) {
            // Skip over '.' and '..' directories.
            if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, "..")) {
                continue;
            }

            // If the current log batch is full, allocate a new one and add it to the list.
            if (batches[num_batches]->num_logs == 10000) {
                num_batches++;
                batches = realloc(batches, sizeof(LogBatch*) * (num_batches + 1));
                batches[num_batches] = malloc(sizeof(LogBatch));
            }

            // Add the log to the current batch.
            strcat(batches[num_batches]->logs, ent->d_name);
            batches[num_batches]->num_logs++;
        }

        closedir (dir);

        // Create a thread for each batch of logs and start processing.
        pthread_t threads[num_batches];
        for (int i = 0; i < num_batches; ++i) {
            pthread_create(&threads[i], NULL, process_batch, batches[i]);
        }

        // Wait for all the threads to finish processing.
        for (int i = 0; i < num_batches; ++i) {
            pthread_join(threads[i], NULL);
        }

        // Free memory allocated for log batches.
        for (int i = 0; i <= num_batches; ++i) {
            free(batches[i]);
        }
        free(batches);
    } 
    else {
        /* Could not open directory */
        perror ("");
    }
}
```
This is a simplified example and does not cover all the requirements. Please, consider using a framework that supports concurrent programming (like C++ with threads or C#), more powerful logging and statistics libraries, and asynchronous I/O operations to handle larger directories efficiently. Additionally, unit tests and error handling will need to be implemented according to your specific needs.
']

