} error_handling_strategy;

error_handling_strategy parseErrorHandlingStrategy(const char* strategy) {
    if (strcmp(strategy, "retry-on-error") == 0) return RETRY_ON_ERROR;
    if (strcmp(strategy, "fail-fast") == 0) return FAIL_FAST;
    if (strcmp(strategy, "suppress-errors") == 0) return SUPPRESS_ERRORS;
}

void processConfigurationFile(const char* inputFileName, const char* outputFileName, 
                              const char* transformRules, error_handling_strategy strategy, int verboseLogging) {
