        switch (strategy) {
            case RETRY_ON_ERROR: /* retry */; break; 
            case FAIL_FAST: /* stop execution */ exit(-1); break;
            case SUPPRESS_ERRORS: return; /* skip error */
        }
    }

    FILE *outputFile = fopen(outputFileName, "w");
    if (outputFile == NULL) {
