#include "custom_log_library.h" //assume this is a custom logging library with functions like logInit, logMessage etc.

#define MAX_BUFFER_SIZE 1024

static int errorLogThreshold = 1;
static int warningLogThreshold = 5;
static int infoLogThreshold = 10;

typedef struct {
    time_t lastErrorTime;
    int errorCount;
} logCounter_t;

logCounter_t logCounters[SYS_gettid] = {{0, 0}}; // Initialize with default values.

static void logMessage(int level, const char *format, ...) {
    time_t currentTime = time(NULL);
    int tid = syscall(SYS_gettid);

    if (level == LOG_LEVEL_ERROR && logCounters[tid].errorCount >= errorLogThreshold) return;
    if (level == LOG_LEVEL_WARNING && logCounters[tid].errorCount >= warningLogThreshold) return;
    if (level == LOG_LEVEL_INFO && logCounters[tid].errorCount >= infoLogThreshold) return;

    char buffer[MAX_BUFFER_SIZE];
    va_list args;
    va_start(args, format);
    vsnprintf(buffer, MAX_BUFFER_SIZE, format, args); // truncate if necessary
    va_end(args);

    logInit(); 

    switch (level) {
        case LOG_LEVEL_ERROR:
            logError(tid, buffer);
            break;
        case LOG_LEVEL_WARNING:
            logWarning(tid, buffer);
            break;
        case LOG_LEVEL_INFO:
            logInfo(tid, buffer);
            break;
    }

    if (currentTime - logCounters[tid].lastErrorTime < 60) { // Checking if a minute has passed since the last error.
        logCounters[tid].errorCount++; 
    } else { 
        logCounters[tid].errorCount = 1; 
    }
    logCounters[tid].lastErrorTime = currentTime;
}
```
This function logs a message to the custom logging library, but only if the number of messages exceeds the specified threshold. The thresholds can be configured based on system load dynamically.
