['```cpp
#include <vector>
#include <algorithm>

void performOperation(std::vector<int>& vec, int target, int threshold) {
    auto it = std::find(vec.begin(), vec.end(), target);

    if (it != vec.end()) {
        *it += threshold;
        ++it;
        if (std::find(it, vec.end(), *it) == vec.end() && *it != target + threshold)
            vec.insert(it, *it);
    } else {
        vec.push_back(target+threshold);
    }
}
```
