class MetricsAggregatorClient {
public:
    MetricsAggregatorClient(int collection_interval, int sampling_rate) : 
        mCollectionInterval(collection_interval), 
        mSamplingRate(sampling_rate) {}

    void collectMetrics() {
        for (auto i = 0; i < mCollectionInterval; ++i) {
            auto start = std::chrono::high_resolution_clock::now();

            // Collect metrics as per the sampling rate and apply anomaly detection here

            auto end = std::chrono::high_resolution_clock::now();
            BOOST_LOG_TRIVIAL(info) << "Collection interval: " 
                                    << i << ", Samples collected: " 
                                    << mSamplesCollected << ", Anomalies detected: "
                                    << mAnomalyCount << ", Processing time: "
                                    << std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count() << "ms"; 
            // Sleep for collection interval to avoid overwhelming system
            std::this_thread::sleep_for(mSamplingRate);
        }
    }

private:
    int mCollectionInterval = 0;
    int mSamplingRate = 1;
    int mSamplesCollected = 0;
    int mAnomalyCount = 0;
};

int main(int argc, char* argv[]) {
    boost::log::add_file_log("sample.log");

    if (argc < 3) {
        BOOST_LOG_TRIVIAL(error) << "Usage: ./program <collection_interval> <sampling_rate>";
        return 1;
    }

    int collectionInterval = std::stoi(argv[1]);
    int samplingRate = std::stoi(argv[2]);

    MetricsAggregatorClient client(collectionInterval, samplingRate);
    client.collectMetrics();

    return 0;
}
```
