namespace RandomGenerator {
    class IRandomAlgorithm {
        public:
            virtual int generateRandomNumber() = 0; 
    };

    // Mersenne Twister algorithm implementation
    class MT19937 : public IRandomAlgorithm {
        std::mt19937 gen;
        std::uniform_int_distribution<> dis;

        public:
            MT19937() : dis(0, 1<<24) {}

            int generateRandomNumber() override {
                return dis(gen);
            }
    };

    class RandomService {
        private:
            std::mutex mtx; // for thread safety
            std::shared_ptr<IRandomAlgorithm> currentGenerator; 

