            RandomService() : currentGenerator(std::make_shared<MT19937>()) {}

            int getRandomNumber(){
                std::lock_guard<std::mutex> lock(mtx);
                return currentGenerator->generateRandomNumber();
            }

            void setAlgorithm(std::shared_ptr<IRandomAlgorithm> generator) {
                std::lock_guard<std::mutex> lock(mtx);
                currentGenerator = generator;
            }
    };
}
