using System.Threading.Tasks;
using System.Diagnostics;

public class BatchProcessor
{
    private SqlConnection _connection;
    private Func<object, Task>[] _transformRules;
    private int _concurrencyLevel;
    private object _lock = new object();

    public async Task<ProcessingResult> Process(List<object> inputData)
    {
        var results = new List<Task>();
        var stopwatch = Stopwatch.StartNew();
        var errorCount = 0;

        using (_connection)
        {
            _connection.Open();

            var throttler = new SemaphoreSlim(_concurrencyLevel);
            foreach (var data in inputData)
            {
                await throttler.WaitAsync().ConfigureAwait(false);

                results.Add(FetchAndTransformStore(data, _connection));

                if (_transformRules == null || !_transformRules.Any())
                    Interlocked.Increment(ref errorCount);

                throttler.Release();
            }

            await Task.WhenAll(results).ConfigureAwait(false);
        }

        return new ProcessingResult 
        {
            TotalItems = inputData.Count,
            ErrorCount = errorCount,
            ElapsedMilliseconds = stopwatch.ElapsedMilliseconds,
            AverageProcessingTimePerItem = 1.0 * stopwatch.ElapsedMilliseconds / inputData.Count
        };
    }

    private async Task FetchAndTransformStore(object data, SqlConnection connection)
    {
        var tasks = new List<Task>();

        foreach (var rule in _transformRules)
