public class StateLoader {
    private static final String APP_DIR = "/app/dir"; // Replace with actual app dir path
    private static Map<String, Object> cache = new ConcurrentHashMap<>();

    public static Object loadState(String filePath) throws Exception {
        File file = new File(APP_DIR, filePath);

        if (!file.exists() || !file.canRead()) {
            throw new IllegalArgumentException("Invalid file path: " + filePath);
        }

        String cacheKey = APP_DIR + "/" + filePath;
        Object stateObj = cache.get(cacheKey);

        if (stateObj == null) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                byte[] headerBytes = new byte[4];
                ois.readFully(headerBytes);
                String versionHeader = new String(headerBytes);

                if ("1.0".equals(versionHeader)) { // Replace with actual version checking logic
                    stateObj = new MoSTState();
                } else if ("2.0".equals(versionHeader)) { // Replace with actual version checking logic
                    stateObj = new LegacyState();
                } else {
                    throw new IllegalArgumentException("Unsupported file format");
                }

                ((State)stateObj).loadFromInputStream(ois);
            } catch (IOException e) {
                throw new Exception("Failed to load state from " + filePath, e);
            }

            cache.put(cacheKey, stateObj);
        }

        return stateObj;
    }

    public static void clearCacheEntry(String key){
        if (cache.containsKey(key)){
            cache.remove(key);
        }
    }
}
