const fs = require('fs');
const path = require('path');
const readdirp = require('readdirp'); // used for async directory traversal
const { promisify } = require('util');

// convert the callback-based 'readFile' into a promise-based function
const readFileAsync = promisify(fs.readFile); 

// Define custom error type
class MyCustomError extends Error {
  constructor(message) {
    super(message); // (1)
    this.name = "MyCustomError"; // (2)
  }
}

async function readAndConcatenateFiles(dirPath, extensions, limit, queueSystem){
   const filesToRead = [];
   let fileCount = 0;
   try {
      await readdirp(dirPath, { type: 'files', fileFilter: extensions })
         .on('data', (entry) => {
            if(fileCount < limit){
               filesToRead.push(path.join(dirPath, entry.name));
               fileCount++;
            }else{
               readAndConcatenateFiles = queueSystem.addTask(readAndConcatenateFiles); // Add task to distributed queue system
            }
         })
         .promise();

      let concatenatedString = '';

      for (const filePath of filesToRead) {
         try{
           const data = await readFileAsync(filePath, 'utf8'); // read and concatenate the contents
           concatenatedString += data;
         }catch(error){
            console.log(`Error reading ${filePath}: ${error}`);
         } 
      }

      return concatenatedString;

   } catch (error) {
      throw new MyCustomError('Failed to read files: ' + error.message);
   }
}
```
