["Here is a basic implementation of the `runTests` function using JavaScript, NodeJS and Promises. This version doesn't handle all edge cases mentioned in your requirements but should give you an idea of how to approach solving this problem.

Please note that error handling in this example might be insufficient for production use as it assumes all promises will always resolve or reject correctly. In real-world usage, make sure to add proper catch blocks or rejections handlers where necessary and also consider using libraries like `async` to handle errors in a more efficient way.

```javascript
const requireFromString = require('require-from-string');
const blueslip = require('blueslip');
const async = require('async');
let _loadedModules = {};
function runTests(moduleName, testLabels, testFunctions, maxConcurrency) {
    let module;
    if (!_loadedModules[moduleName]) {
        // Load the module asynchronously using requireFromString or similar methods
        try {
            const moduleCode = fs.readFileSync(`${moduleName}.js`, 'utf8');
            _loadedModules[moduleName] = new Promise((resolve, reject) => {
                resolve(requireFromString(moduleCode));
            });
        } catch (e) {
            console.error(`Error loading module ${moduleName}: ${e}`);
            return;
        }
    }

    let successCount = 0, failureCount = 0, totalCount = testFunctions.length;
    const queue = async.queue((testFunction, callback) => {
        blueslip.reset();
        console.time(`Test ${moduleName} - ${testLabels[testFunctions.indexOf(testFunction)]}`);
        testFunction()
            .then(() => {
                successCount++;
                console.log(`Success: Test ${moduleName} - ${testLabels[testFunctions.indexOf(testFunction)]}`);
            })
            .catch((err) => {
                failureCount++;
                console.error(`Failure: Test ${moduleName} - ${testLabels[testFunctions.indexOf(testFunction)]}: ${err.message}`);
            })
            .finally(() => {
                console.timeEnd(`Test ${moduleName} - ${testLabels[testFunctions.indexOf(testFunction)]}`);
                callback();
            });
    }, maxConcurrency);

    for (let i = 0; i < testFunctions.length; i++) {
        queue.push(testFunctions[i]);
    }

    // Callback function for when the entire queue is done
    queue.drain(() => {
        console.log(`Total tests: ${totalCount}, Successful tests: ${successCount}, Failed tests: ${failureCount}`);
    });
}
``` 
Please remember to replace 'fs' module with the suitable one based on your environment and requirements. The fs methods are used here just for demonstration purposes, actual implementation would vary according to how you load modules in your project (e.g., webpack). Also, error handling should be implemented carefully as required. Lastly, please note that this is a basic example and does not cover all the points specified in your question like exponential backoff for failed tests or partial mocking failures.
