```javascript
const express = require('express');
const router = express.Router();
const Product = require('../models/productModel'); // MongoDB product model

router.get('/api/products', async (req, res) => {
    const pageNumber = parseInt(req.query.page || 1);

    // Extract filter and sort parameters from the request query. 
    // Validate these inputs to prevent SQL injection or other malicious activity.
    const filters = req.query;
    delete filters.page;
    delete filters.limit;
    delete filters.sortBy;

    try {
        const productsCount = await Product.countDocuments(filters);

        // Calculate the total pages based on product count and limit per page.
        const totalPages = Math.ceil(productsCount / (req.query.limit || 10));

        // Query the MongoDB database for products with pagination, sorting and filters applied.
        const products = await Product
            .find(filters)
            .sort({[req.query.sortBy || '_id']: 1}) // Sort by _id by default
            .limit(parseInt(req.query.limit || 10)) // Limit to 10 per page by default
            .skip((pageNumber - 1) * (req.query.limit || 10)); // Skip previous pages

        res.json({products, totalPages});
    } catch (error) {
        console.error('Error fetching products from database', error);
        res.status(500).send('Internal Server Error');
    }
});

module.exports = router;
```
Please replace the product model path to your own MongoDB Product Model path and also make sure that your Node.js server is setup correctly with express and mongoose for handling API routes, middleware, and connecting with MongoDB. Also this code does not include any error checking or validation, which you should add in a production environment.
