```javascript
const fs = require('fs');
const path = require('path');
const vm = require('vm');
let cache = {};

function loadScript(filePath, version) {
    return new Promise((resolve, reject) => {
        // Checking if script is in cache
        if (cache[filePath] && cache[filePath][version]) {
            resolve(cache[filePath][version]);
        } else {
            const script = new vm.Script(fs.readFileSync(filePath, 'utf-8'));
            try {
                // Running the Script and Caching it for future use
                cache[filePath] = { [version]: script };
                resolve(script);
            } catch (error) {
                console.error("Script failed to execute", error);
                reject(error);
            }
        }
    });
}

async function loadAndExecute(scripts, version) {
    for (const script of scripts) {
        try {
            const filePath = path.resolve(process.cwd(), script);
            // Checking if the file exists
            if (!fs.existsSync(filePath)) throw new Error('File not found');

            // Handling symbolic links
            if (fs.lstatSync(filePath).isSymbolicLink()) {
                const realPath = fs.realpathSync(filePath);
                console.log('Resolved path:', realPath);
            }

            // Loading and executing script
            const scriptInstance = await loadScript(filePath, version);
            vm.runInNewContext(scriptInstance);
        } catch (error) {
            console.error("Error loading or executing the script", error);
        }
    }
}

module.exports = {
    loadAndExecute,
};
```
This code uses Node.js `fs` and `vm` modules to handle file system operations and JavaScript VM for execution of files. It also provides a basic versioning mechanism with the help of cache. The `loadScript` function is responsible for loading and executing scripts, ensuring each script runs in its own context. The `loadAndExecute` function manages multiple files, making sure they are loaded and executed one by one.
']

['Below is an implementation of `updateClinicStatus` function:

```java
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.net.InetAddress;
import java.sql.*;
import java.lang.Thread;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.log4j.Logger;

public class ClinicStatusUpdater {
    private static final Logger logger = Logger.getLogger(ClinicStatusUpdater.class);
    private ConcurrentHashMap<String, DirectoryNode> directories =  new ConcurrentHashMap<>();

    public String updateClinicStatus(List<Path> paths, int clinicId) {
        long startTime = System.nanoTime();
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/test?" + "user=root&password=root")) {
            String updateTableSQL = "UPDATE clinics SET status = ?, last_modified_ip = ?, last_modified_date = ? WHERE clinic_id = ?";

            PreparedStatement preparedStatement = conn.prepareStatement(updateTableSQL);

            for (Path path : paths) {
                directories.computeIfAbsent(path.getParent().toString(), DirectoryNode::new).addChild();
            }

            String ipAddress = InetAddress.getLocalHost().getHostAddress();

            preparedStatement.setString(1, "updated");
            preparedStatement.setString(2, ipAddress);
            preparedStatement.setTimestamp(3, Timestamp.valueOf(LocalDateTime.now()));
            preparedStatement.setInt(4, clinicId);

            int affectedRows = preparedStatement.executeUpdate();

            if (affectedRows > 0) {
                System.out.println("Database updated successfully!");

                long endTime = System.nanoTime();
                logger.info(String.format("Processed %d paths in %d ms", paths.size(), (endTime - startTime) / 1000000));

                return "Status updated successfully";
            } else {
                throw new SQLException("Updating clinic status failed, no rows affected.");
            }
        } catch (SQLException e) {
            logger.error(String.format("Database update error: %s", e.getMessage()));
            return "Status update failed";
        } catch (UnknownHostException e) {
            logger.error(String.format("IP retrieval error: %s", e.getMessage()));
            return "Status update failed";
        }
    }
}
```
This code uses a custom `DirectoryNode` class to represent directory hierarchies, and it also uses a `ConcurrentHashMap` to efficiently manage these directories. Note that this code uses JDBC for database operations and Apache log4j for logging. Also, Java's nio package is used for dealing with file paths.

In the multithreaded environment, each thread would have its own instance of `ClinicStatusUpdater` object, and hence its own `directories` map. Therefore, no concurrency issues should occur due to shared state across threads. 

Note: Please replace "jdbc:mysql://localhost/test?" + "user=root&password=root" with your actual DB connection string. The above code is just a guideline. Always handle your database connections and resources properly in real-world applications. For exception handling, it's advisable to customize the exceptions based on specific needs instead of general ones for better understanding and troubleshooting.
