['Here's a simple HTTP client in Rust that should cover most of your requirements. This is a very high level overview and doesn't include all the specific details you have listed like integration with logging service or handling network conditions. 

```rust
extern crate hyper;
use hyper::rt::{Future, Stream};
use hyper::client::response::Response;
use hyper::header::Connection;

pub struct HttpClient {
    client: hyper::Client<hyper::Body>,
}

impl HttpClient {
    pub fn new() -> Self {
        let client = match hyper::Client::new() {
            Ok(client) => client,
            Err(_) => panic_fail::panic_err(format_error::InvalidData("Failed to create http client")),
        };

        HttpClient { client }
    }

    pub fn get(&self, url: &str) -> impl Future<Item=Response, Error=hyper::Error> + Send {
        let uri = match url.parse() {
            Ok(uri) => uri,
            Err(_) => panic_fail::panic_err(format_error::InvalidData("Failed to parse URL")),
        };

        self.client.get(uri).header(Connection::close()).and_then(|response| {
            let result = match response {
                Ok(result) => result,
                Err(_) => panic_fail::panic_err(format_error::InvalidData("Failed to process request")),
            };

            // Response metrics collection can be added here. 

            Future::ok(result)
        })
    }
}
```
