    int LTE_RRCNAS_SequenceNumber;
} LTE_RRC_CriticalSections;

LTE_RRC_CriticalSections* initializeAndPopulateSections(char* TransactionID, int numOfStructures) {
    // Allocate memory for the array of structures.
    LTE_RRC_CriticalSections* sections = (LTE_RRC_CriticalSections*)malloc(sizeof(LTE_RRC_CriticalSections)*numOfStructures);

    if (sections == NULL) {
        printf("Memory allocation failed!\n");
        exit(0); 
    }

    // Memory allocation successful, initialize each structure.
    for (int i = 0; i < numOfStructures; ++i) {
        sections[i].LTE_RRCNAS_TransactionID = strdup(TransactionID);

        if (sections[i].LTE_RRCNAS_TransactionID == NULL) {
            printf("Memory allocation failed for LTE_RRCNAS_TransactionID of structure %d!\n", i+1);
            exit(0); 
        }

        // Assuming that the message size is fixed and known.
        sections[i].LTE_RRCNAS_Message = malloc(128);

        if (sections[i].LTE_RRCNAS_Message == NULL) {
            printf("Memory allocation failed for LTE_RRCNAS_Message of structure %d!\n", i+1);
            exit(0); 
        }

        // Assuming a sequence number starts from 1.
        sections[i].LTE_RRCNAS_SequenceNumber = i + 1;
    }

    printf("Memory allocated and populated successfully for %d structures.\n", numOfStructures);
    return sections;
}
