#define MAX_LEN 1024
typedef struct {
    char *password;
    void *connStructure;
    int (*callback)(void);
} MyStruct;

int myFunction(MyStruct *myStr) {
    if (myStr->password == NULL || strlen(myStr->password) == 0) return -1; // empty or null password 
    if (myStr->connStructure == NULL) return -2; // connection structure is not defined
    if (myStr->callback == NULL) return -3; // callback function is not defined

    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    const EVP_MD *md = EVP_get_digestbyname("sha256");
    if(!EVP_DigestInit_ex(mdctx, md, NULL)) return -4; // error initializing context

    char randomStr[MAX_LEN];
    int len = 0; // define the length of the string you want to generate here
    const char *charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"; // define your character set here

    for (int i = 0; i < len; ++i) {
        randomStr[i] = charset[rand() % strlen(charset)];
    }
    randomStr[len] = '\0';

    if(!EVP_DigestUpdate(mdctx, myStr->password, strlen(myStr->password))) return -5; // error updating context with password
    if(!EVP_DigestUpdate(mdctx, randomStr, len)) return -6; // error updating context with random string

    unsigned char md_value[EVP_MAX_MD_SIZE];
    unsigned int md_len = 0;
    if(!EVP_DigestFinal_ex(mdctx, md_value, &md_len)) return -7; // error finalizing context

    EVP_MD_CTX_free(mdctx);

    return myStr->callback(myStr->connStructure, md_value, md_len); // callback function called with connection structure and hashed password
}
