// Abstraction of your abilities
class Ability {
public:
    virtual void execute() = 0; // Pure virtual function, should be implemented in derived classes.
};

// Our game character with cooldown management
class Character {
private:
    std::mutex mtx;
    std::condition_variable cv;
    bool ready = true;

public:
    void manageCharacterAbilities(std::vector<Ability*> abilities) {
        while (true) { // Our game loop. Replace with your own logic.
            int abilityIndex = rand() % abilities.size(); // Randomly select an ability.

            std::unique_lock<std::mutex> lock(mtx);
            cv.wait(lock, [this]{ return ready; }); // Wait for cooldown to finish.

            Ability* selectedAbility = abilities[abilityIndex];
            selectedAbility->execute(); // Execute the ability.

            ready = false; // Start the cooldown.
            lock.unlock();

            std::thread t([this](){ // Asynchronous cooldown countdown.
                std::this_thread::sleep_for(std::chrono::seconds(10)); 

                std::lock_guard<std::mutex> lock(mtx);
                ready = true;
            });

            t.detach(); // Detaching the thread allows it to run independently even if manageCharacterAbilities returns.

            cv.notify_one(); // Notify one waiting thread (if any) that the cooldown has finished and it can continue.
        }
    }
};
``` 

This code assumes you'll have multiple classes derived from `Ability` implementing their own versions of `execute()` according to their specific logic, which is a common practice in OOP for polymorphism. The cooldown and random selection are handled by this character object and each execution of an ability is started on a separate thread not blocking the main game loop.

