['Here is a simple implementation of your task using C# language:
```csharp
using System;
using System.Threading;

public class DynamicRangeValueGenerator
{
    private double minValue;
    private double maxValue;
    private bool inclusive;
    private static Random random = new Random();
    private ReaderWriterLockSlim lock_ = new ReaderWriterLockSlim();

    public DynamicRangeValueGenerator(double min, double max, bool inclusive)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value must be less than or equal to maximum value.");
        }

        this.minValue = min;
        this.maxValue = max;
        this.inclusive = inclusive;
    }

    public int GetNextInteger()
    {
        lock_.EnterReadLock();
        try
        {
            double randomDouble = random.NextDouble();

            if (inclusive)
            {
                return (int)(minValue + randomDouble * (maxValue - minValue + 1));
            }
            else
            {
                return (int)(minValue + randomDouble * (maxValue - minValue));
            }
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }

    public double GetNextFloat()
    {
        lock_.EnterReadLock();
        try
        {
            double randomDouble = random.NextDouble();

            if (inclusive)
            {
                return minValue + randomDouble * (maxValue - minValue);
            }
            else
            {
                return minValue + randomDouble * (maxValue - minValue + 1);
            }
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }

    public override string ToString()
    {
        lock_.EnterReadLock();
        try
        {
            return $"Min: {minValue}, Max: {maxValue}, Inclusive: {inclusive}";
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }
}
```
This code generates random integers and floats within a specified range. The range can be inclusive or exclusive, as per the requirement. It uses a ReaderWriterLockSlim to ensure thread safety.
