import java.io.*;
import org.apache.commons.io.FileUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import ch.qos.logback.classic.Level;

public class ExecutionHandler {
    private static final Logger logger = LoggerFactory.getLogger(ExecutionHandler.class);

    public void executeCommand(String command, String[] args, Map<String, String> envVars) throws Exception {
        File tmpDir = FileUtils.getTempDirectory();
        File tmpFile = new File(tmpDir, "temp");

        ProcessBuilder pb = new ProcessBuilder(command);
        pb.directory(tmpDir);
        pb.redirectErrorStream(true);
        Map<String, String> tempEnvVars = pb.environment();
        tempEnvVars.putAll(envVars);

        try {
            Process process = pb.start();

            OutputStream outStream = new FileOutputStream(tmpFile);
            InputStream inputStream = process.getInputStream();
            PrintWriter printWriter = new PrintWriter(outStream);
            long startTime = System.currentTimeMillis();

            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                outStream.write(buffer, 0, bytesRead);
            }
            long endTime = System.currentTimeMillis();

            // Log execution time
            logger.info("Command '{}' executed in {} ms", command, (endTime-startTime));

            if ((endTime - startTime) > 10000) {
                process.destroy();
                throw new Exception("Command " + command + " took too long to execute");
            }

        } catch(IOException | InterruptedException ex) {
            logger.error("Error executing command: ", ex);
        } finally {
            FileUtils.deleteQuietly(tmpFile);
        }
    }
}
