['```csharp
using System;
using System.Security.Cryptography;
using System.Text;
using System.Linq;
using System.Collections.Generic;
using System.IO;
using Microsoft.Extensions.Caching.Memory;

public class ProcessAndCacheDecryptedData 
{
    private MemoryCache cache = new MemoryCache(new MemoryCacheOptions { SizeLimit = 1024 });

    public string processAndCacheDecryptedData(string base64EncryptedMessage, byte[] key, byte[] iv)
    {
        if (base64EncryptedMessage == null || key == null || iv == null)
            throw new ArgumentNullException("Input cannot be null");

        if (!MemoryCache.Default.Contains(base64EncryptedMessage)) 
        {
            string decodedAndDecrypted = DecodeAndDecrypt(base64EncryptedMessage, key, iv);

            string transformedData = TransformData(decodedAndDecrypted);

            MemoryCacheEntryOptions cacheEntryOptions = new MemoryCacheEntryOptions().SetSize(1).SetSlidingExpiration(TimeSpan.FromSeconds(60));
            cache.Set(base64EncryptedMessage, transformedData, cacheEntryOptions);
        } 

        string dataToHash;
        if (!cache.TryGetValue(base64EncryptedMessage, out dataToHash)) 
        {
            throw new Exception("Item not in the cache");
        }

        return ComputeSHA256Hash(dataToHash);
    }

    private string DecodeAndDecrypt(string base64EncryptedMessage, byte[] key, byte[] iv) 
    {
        if (key.Length != 16 && key.Length != 24) 
            throw new ArgumentException("Invalid DES key length");

        if (iv.Length != 8) 
            throw new ArgumentException("Invalid DES IV length");

        byte[] encryptedMessageBytes = Convert.FromBase64String(base64EncryptedMessage);

        using (TripleDES des = TripleDES.Create()) 
        {
            des.Key = key;
            des.IV = iv;

            ICryptoTransform decryptor = des.CreateDecryptor();

            byte[] decryptedMessageBytes;
            using (MemoryStream msDecrypt = new MemoryStream(encryptedMessageBytes)) 
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read)) 
                {
                    using (BinaryReader brDecrypt = new BinaryReader(csDecrypt)) 
                        decryptedMessageBytes = brDecrypt.ReadBytes(encryptedMessageBytes.Length);

                        return Encoding.UTF8.GetString(decryptedMessageBytes);
                }
            }
        }
    }

    private string TransformData(string data) 
    {
        StringBuilder sb = new StringBuilder();

        foreach (char c in data.Trim()) 
        {
            if (!Char.IsLetterOrDigit(c)) 
                sb.Append('_');
            else 
                sb.Append(Char.ToUpperInvariant(c));
        }

        return sb.ToString();
    }

    private string ComputeSHA256Hash(string data) 
    {
        using (var sha = SHA256.Create()) 
            return Convert.ToBase64String(sha.ComputeHash(Encoding.UTF8.GetBytes(data)));
    }
}
```
