import java.io.*;
import java.util.concurrent.*;

public class SerializationHelper {
    private final ExecutorService executor;
    private static final int THREAD_POOL_SIZE = 50;

    public SerializationHelper() {
        this.executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
    }

    public <T> Future<T> deserializeAsync(byte[] bytes, Class<T> clazz) {
        return executor.submit(() -> deserialize(bytes, clazz));
    }

    private <T> T deserialize(byte[] bytes, Class<T> clazz) {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
             ObjectInput in = new ObjectInputStream(bis)) {
            return clazz.cast(in.readObject());
        } catch (ClassNotFoundException e) {
            throw new RuntimeException("Deserialization failed: Required class not found", e);
        } catch (IOException e) {
            throw new RuntimeException("IO error during deserialization", e);
        }
    }

    public static void main(String[] args) throws Exception {
        byte[] bytes = serializeSampleObject(); // You need to replace this with your own sample object serialization. 
        SerializationHelper helper = new SerializationHelper();

        Future<MyClass> future = helper.deserializeAsync(bytes, MyClass.class);
        System.out.println("Result: " + future.get());
    }

    private static byte[] serializeSampleObject() throws IOException {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutput out = new ObjectOutputStream(bos)) {
            out.writeObject(new MyClass("test"));
            return bos.toByteArray();
        }
    }
}

class MyClass implements Serializable {
    private final String value;

    public MyClass(String value) {
        this.value = value;
    }

    @Override
    public String toString() {
        return "MyClass{" + "value='" + value + '\'' + '}';
    }
}
