void addPacket(unsigned char packet_id, const char* source_address, const char* destination_address) {
    pthread_mutex_lock(&lock);

    if (packets == NULL || packetCount == 0 || packets[packetCount - 1]->packet_id != packet_id) {
        DATA_PACKET_T* newPacket = malloc(sizeof(DATA_PACKET_T));

        if (newPacket == NULL) {
            // handle memory allocation failure, e.g., log an error message and return
            pthread_mutex_unlock(&lock);
            return;
        }

        newPacket->packet_id = packet_id;
        strncpy(newPacket->source_address, source_address, 15);
        newPacket->source_address[15] = '\0'; // ensure null termination
        strncpy(newPacket->destination_address, destination_address, 15);
        newPacket->destination_address[15] = '\0'; // ensure null termination

        packets = realloc(packets, sizeof(DATA_PACKET_T*) * (packetCount + 1));
        if (packets == NULL) {
            // handle memory allocation failure again
            free(newPacket);
            pthread_mutex_unlock(&lock);
            return;
        }

        packets[packetCount++] = newPacket;
