```c
#include <pthread.h>
#include <stdatomic.h>

typedef struct { /* NFAPI_CRC_INDICATION_PDU_T structure */ } NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    atomic_uint allocationCount;
    pthread_mutex_t mutex;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* elements;
} SafeArray;

void InitializeSafeArray(SafeArray *arr) {
    arr->capacity = 10000;
    arr->elements = (NFAPI_CRC_INDICATION_PDU_T*) calloc(arr->capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    atomic_init(&arr->allocationCount, 0);
    pthread_mutex_init(&arr->mutex, NULL);
}

int AddElement(SafeArray *arr) {
    if (atomic_load(&arr->allocationCount) >= 15000) {
        printf("Maximum allocation count limit reached!\n");
        return -1;  // Error code for limit being reached
    }

    pthread_mutex_lock(&arr->mutex);
    if (atomic_load(&arr->allocationCount) == arr->capacity) {  // Array is full, resize it
        size_t newCapacity = arr->capacity * 1.5;  // Increase the capacity by 50%
        NFAPI_CRC_INDICATION_PDU_T* newElements = (NFAPI_CRC_INDICATION_PDU_T*) realloc(arr->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (newElements == NULL) {  // Check for out of memory error
            pthread_mutex_unlock(&arr->mutex);
            return -2;  // Error code for out of memory
        }
        arr->elements = newElements;
        arr->capacity = newCapacity;
    }

    atomic_fetch_add(&arr->allocationCount, 1);  // Add a new element
    pthread_mutex_unlock(&arr->mutex);
    return 0;  // Success code
}

void RemoveElement(SafeArray *arr) {
    if (atomic_load(&arr->allocationCount) > 0) {
        atomic_fetch_sub(&arr->allocationCount, 1);  // Remove an element

        pthread_mutex_lock(&arr->mutex);
        if (((double) arr->capacity / 3) > atomic_load(&arr->allocationCount)) {  // If the array is less than a third full, shrink it
            size_t newCapacity = arr->capacity / 2;  // Decrease the capacity by half
            NFAPI_CRC_INDICATION_PDU_T* newElements = (NFAPI_CRC_INDICATION_PDU_T*) realloc(arr->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (newElements != NULL) {  // Only update capacity and elements if reallocation succeeded
                arr->elements = newElements;
                arr->capacity = newCapacity;
            }
        }
        pthread_mutex_unlock(&arr->mutex);
    }
}

void DestroySafeArray(SafeArray *arr) {
    free(arr->elements);
    atomic_store(&arr->allocationCount, 0);
    pthread_mutex_destroy(&arr->mutex);
}
```
