NetworkInterfaceStatistics* findByName(const char* name) {
    pthread_mutex_lock(&array.lock);

    for (size_t i = 0; i < array.size; ++i) {
        if (strcmp(array.statistics[i].networkInterfaceName, name) == 0) {
            NetworkInterfaceStatistics* result = &array.statistics[i];
            pthread_mutex_unlock(&array.lock);
            return result;
        }
    }

    pthread_mutex_unlock(&array.lock);
    return NULL;
}

void addOrUpdate(NetworkInterfaceStatistics stats) {
    NetworkInterfaceStatistics* existing = findByName(stats.networkInterfaceName);
    if (existing != NULL) {
        // Update existing entry
        *existing = stats;
    } else {
        pthread_mutex_lock(&array.lock);

        // Resize array
        if (array.size == array.capacity) {
            array.capacity = (array.capacity + 1) * 2;
            array.statistics = realloc(array.statistics, array.capacity * sizeof(NetworkInterfaceStatistics));
        }

        // Add new entry
        array.statistics[array.size++] = stats;
        pthread_mutex_unlock(&array.lock);
