    GraphDatabase* graph = malloc(sizeof(GraphDatabase));
    if (graph == NULL) return NULL; // Error handling

    graph->vertexCount = 0;
    graph->vertices = NULL;
    graph->edgeCount = 0;
    graph->edges = NULL;

    pthread_mutex_init(&(graph->lock), NULL); // Initialize lock for synchronization

    return graph;
}

void addVertex(GraphDatabase* graph, VertexData data) {
    if (graph == NULL || data.string_property == NULL) return; // Error handling

    pthread_mutex_lock(&(graph->lock)); // Lock for synchronization during operation

    // Check and manage unique vertex identifiers here 

    graph->vertexCount++;
    graph->vertices = realloc(graph->vertices, sizeof(VertexData) * graph->vertexCount);
    if (graph->vertices == NULL) return; // Error handling

    VertexData* vertex = &(graph->vertices[graph->vertexCount - 1]);
    vertex->index = data.index;
    vertex->string_property = strdup(data.string_property); // Copy string to avoid memory issues
    if (vertex->string_property == NULL) return; // Error handling

    pthread_mutex_unlock(&(graph->lock)); // Unlock after operation completed
}

void addEdge(GraphDatabase* graph, EdgeData data) {
    if (graph == NULL) return; // Error handling

    pthread_mutex_lock(&(graph->lock)); // Lock for synchronization during operation

    // Check and manage edge cases here 

