    EdgeData* edge = &(graph->edges[graph->edgeCount - 1]);
    edge->source = data.source;
    edge->destination = data.destination;
    edge->weight = data.weight;

    pthread_mutex_unlock(&(graph->lock)); // Unlock after operation completed
