// Define the structure for network interface statistics
typedef struct {
    time_t timestamp;
    int activeConnections;
    char* name;
} NetworkInterfaceStatistics;

// Define a dynamic array of network interfaces
typedef struct {
    NetworkInterfaceStatistics** arr;
    size_t used;
    size_t size;
} DynamicArray;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
DynamicArray interfaceStats;

// Initialize the dynamic array of network interfaces
void initInterfaceStats(int initialSize) {
    interfaceStats.arr = (NetworkInterfaceStatistics**) malloc(initialSize * sizeof(NetworkInterfaceStatistics*));
    for(int i = 0; i < initialSize; i++) 
        interfaceStats.arr[i] = NULL;

    interfaceStats.used = 0;
    interfaceStats.size = initialSize;
}

// Add a new entry or update an existing one based on the network interface name
void addOrUpdateEntry(NetworkInterfaceStatistics* newEntry) {
    pthread_mutex_lock(&lock);  // Locking for thread safety

    for (size_t i = 0; i < interfaceStats.used; i++) {
        if (!strcmp(interfaceStats.arr[i]->name, newEntry->name)) {
            free(interfaceStats.arr[i]);
            interfaceStats.arr[i] = newEntry;

            pthread_mutex_unlock(&lock); // Unlocking after critical section is over
            return;
        }
    }

    if (interfaceStats.used == interfaceStats.size) {
        interfaceStats.size *= 2;
        interfaceStats.arr = realloc(interfaceStats.arr, interfaceStats.size * sizeof(NetworkInterfaceStatistics*));
    }

    interfaceStats.arr[interfaceStats.used++] = newEntry;

    pthread_mutex_unlock(&lock); // Unlocking after critical section is over
}

// Retrieve statistics for a specific interface
NetworkInterfaceStatistics* getStatsForInterface(char* name) {
    pthread_mutex_lock(&lock);  // Locking for thread safety

    for (size_t i = 0; i < interfaceStats.used; i++) {
        if (!strcmp(interfaceStats.arr[i]->name, name)) {
            NetworkInterfaceStatistics* stats = malloc(sizeof(NetworkInterfaceStatistics));
            memcpy(stats, interfaceStats.arr[i], sizeof(NetworkInterfaceStatistics));

            pthread_mutex_unlock(&lock); // Unlocking after critical section is over
            return stats;
        }
    }

    pthread_mutex_unlock(&lock); // Unlocking after critical section is over
    return NULL;
}
```
