```javascript
const fs = require('fs');
const {promisify} = require('util');
const readFileAsync = promisify(fs.readFile);

class DeserializerError extends Error {}

async function deserializeFileContent (filePath, DataStructureType) {
    try {
        const fileData = await readFileAsync(filePath);
        return new DataStructureType(Buffer.from(fileData)); // assuming your data structure class has a constructor that accepts Buffer
    } catch (error) {
        throw new DeserializerError(`Failed to deserialize content from file: ${filePath}. Error: ${error}`);
    }
}

async function deserializeFilesInParallel (filePaths, DataStructureType) {
    const promises = filePaths.map((path) => deserializeFileContent(path, DataStructureType));
    return Promise.all(promises);
}
```
