    }

    return manager;
}

void mac_context_manager_resize(MacContextManager* manager, size_t newCapacity) {
    pthread_mutex_lock(&manager->mutex);
    if (newCapacity > manager->capacity) {  // only resize larger to avoid loss of data
        MAC_CONTEXT_T* contexts = realloc(manager->contexts, sizeof(MAC_CONTEXT_T) * newCapacity);

