char* conditionalStringTrimmer(const char* inputString, size_t stringLength, int maxLength, _Bool isTimezoneAdjusted) {
    if (inputString == NULL || strlen(inputString) > maxLength) {
        return NULL;
    }

    // Allocate memory for the new string. +2 is for the slash and null terminator
    char* result = malloc((stringLength + 2) * sizeof(char));

    if (result == NULL) {
        // Handle out of memory error
        return NULL;
    }

    strncpy(result, inputString, stringLength);

    if (!isTimezoneAdjusted && result[stringLength - 1] != '/') {
        result[stringLength] = '/';
        result[stringLength + 1] = '\0'; // Null terminate the new string
    } else {
        result[stringLength] = '\0'; // Null terminate the new string
    }

    return result;
}
