#include <stdio.h>
#include <string.h>
#include <time.h>
#include <ctype.h>
#include <pthread.h>

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

char* modifyFilename(const char *filename, size_t maxLen) {
    static char newName[61]; // Assuming the maximum length as 60 + 1 for null terminator

    pthread_mutex_lock(&mutex);

    int digits = 0;
    const char *extension = strrchr(filename, '.');
    if (extension == NULL || extension[1] == '\0') {
        printf("Invalid file name: %s\n", filename);
        pthread_mutex_unlock(&mutex);
        return NULL; // No valid extension
    }

    strncpy(newName, filename, maxLen - 20); // reserve space for appending timestamp and null terminator

    if (strcmp(extension, ".txt") == 0) {
        for (const char *p = filename; *p != '\0'; ++p) {
            if (isdigit((unsigned char)*p)) {
                ++digits;
            }
        }

        sprintf(newName + strlen(newName), "%s%d", extension, digits);
    } else if (strcmp(extension, ".jpg") == 0 || strcmp(extension, ".png") == 0) {
        time_t now = time(NULL);

        sprintf(newName + strlen(newName), "%lu%s", now, extension);
    } else {
        printf("Unsupported file type: %s\n", filename);
        pthread_mutex_unlock(&mutex);
        return NULL; // Unsupported file type
    }

    if (strlen(newName) > maxLen - 1) {
        size_t truncated = strlen(newName) - (maxLen - 1);

        printf("Filename truncation occurred: %s, %s, %zu\n", filename, newName, truncated);
        newName[maxLen - 1] = '\0'; // Truncate and null terminate
    }

    pthread_mutex_unlock(&mutex);

    return newName;
}
```

