        return -1;
    }

    int digits = 0;
    for (char *p = filename; *p != '\0'; p++) {
        if (*p >= '0' && *p <= '9') {
            digits++;
        }
    }

    char newFilename[maxLength];
    strcpy(newFilename, filename); // copy original filename to new one

    if (strcmp(extension, ".txt") == 0) { 
        sprintf(extension, "%s.%d", extension + 1, digits);
    } else if (strcmp(extension, ".jpg") == 0 || strcmp(extension, ".png") == 0) {
        time_t timestamp = time(NULL);
        sprintf(newFilename, "%s.%ld%s", filename, timestamp, extension + 1);
