#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t timestamp;
    int activeConnections;
    char* networkInterfaceName;
    float packetLoss;
    double latency;
    double bandwidthUsage;
} NetworkInterfaceStatistics;

typedef struct Node {
    NetworkInterfaceStatistics data;
    struct Node *next;
} Node;

Node *head = NULL;
pthread_mutex_t lock;

void addEntry(NetworkInterfaceStatistics stats) {
    pthread_mutex_lock(&lock);

    Node *newNode = malloc(sizeof(Node));
    newNode->data = stats;
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void updateEntry(char* networkInterfaceName, NetworkInterfaceStatistics newStats) {
    pthread_mutex_lock(&lock);

    Node *temp = head;
    while (temp != NULL) {
        if (strcmp(temp->data.networkInterfaceName, networkInterfaceName) == 0) {
            temp->data = newStats;
            break;
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
}

NetworkInterfaceStatistics* getEntry(char* networkInterfaceName) {
    pthread_mutex_lock(&lock);

    Node *temp = head;
    while (temp != NULL) {
        if (strcmp(temp->data.networkInterfaceName, networkInterfaceName) == 0) {
            pthread_mutex_unlock(&lock);
            return &(temp->data);
        }
        temp = temp->next;
    }

    pthread_mutex_unlock(&lock);
    return NULL;
}
```

