import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import org.apache.http.client.HttpClient;
import org.apache.http.impl.client.DefaultHttpClient;
import com.google.gson.Gson;

public class PokemonReportGenerator {
    private static final String API_URL = "https://pokeapi.co/api/v2/type/{type}";
    private HttpClient httpClient = new DefaultHttpClient();
    private Gson gson = new Gson();
    private ConcurrentHashMap<String, List<TypeDetails>> cache = new ConcurrentHashMap<>();
    private volatile boolean cacheInvalidated;

    public String generateReport(Pokemon pokemon) {
        // Retrieve types from the library function.
        List<String> types = pokemon.getTypes();

        // Use a switch statement to determine weaknesses, resistances, and immunities.
        List<TypeDetails> typeDetailsList = new ArrayList<>();
        for (String type : types) {
            if (!cache.containsKey(type) || cacheInvalidated) {
                TypeDetails typeDetails = fetchTypeDetailsFromAPI(type);
                if (typeDetails != null) {
                    List<TypeDetails> currentList = cache.getOrDefault(type, new ArrayList<>());
                    currentList.add(typeDetails);
                    cache.put(type, currentList);
                }
            }
            typeDetailsList.addAll(cache.get(type));
        }

        // Generate and return the detailed report as a string.
        StringBuilder sb = new StringBuilder();
        sb.append("Pokemon: ").append(pokemon.getName()).append("\n");
        for (TypeDetails typeDetails : typeDetailsList) {
            sb.append("Weaknesses: ").append(typeDetails.getDamage_relations().getDouble_damage_from()).append("\n")
              .append("Resistances: ").append(typeDetails.getDamage_relations().getHalf_damage_to()).append("\n");
        }

        return sb.toString();
    }

    private TypeDetails fetchTypeDetailsFromAPI(String type) {
        try {
            String apiUrl = API_URL.replace("{type}", type);
            HttpResponse response = httpClient.execute(new HttpGet(apiUrl));
            return gson.fromJson(EntityUtils.toString(response.getEntity()), TypeDetails.class);
        } catch (IOException e) {
            System.err.println("Error calling API: " + e.getMessage());
            return null;
        }
    }

    // Other helper classes and methods...
}
```

