typedef struct {
    time_t tv_sec;
    int32_t tv_nsec;
} timestamp;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Thread-safe function to generate and append the current UTC timestamp in ISO 8601 format.
void getCurrentTimestamp(timestamp* ts) {
    struct timespec spec;
    clock_gettime(CLOCK_REALTIME, &spec);

    pthread_mutex_lock(&lock);
    ts->tv_sec = spec.tv_sec;
    ts->tv_nsec = spec.tv_nsec;
    pthread_mutex_unlock(&lock);
}

// Thread-safe function to append a timestamp in ISO 8601 format.
void appendTimestamp(char* inputString, size_t stringLength) {
    char buffer[32]; // Enough space for the ISO 8601 date string and null terminator

    timestamp ts;
    getCurrentTimestamp(&ts);

    struct tm result;
    gmtime_r(&(ts.tv_sec), &result);

    strftime(buffer, sizeof buffer, "%FT%TZ", &result);

    pthread_mutex_lock(&lock);
    strncat(inputString + stringLength, "/", 1);
    strncat(inputString + stringLength + 1, buffer, sizeof(buffer));
    pthread_mutex_unlock(&lock);
}

// Function to trim inputString based on maxLength and conditionally append a timestamp.
char* conditionalStringTrimmer(char* inputString, size_t stringLength, int maxLength, bool appendTimestamp) {

    if (stringLength > maxLength) {
