void initializeOctreeWithConfig(int featureSize, int numLeafNodes, size_t dataCapacity, 
                               int minValue, int maxValue, std::string configPath, 
                               std::forward_list<std::string>& dataList, const std::string& searchString, 
                               const std::string& targetString) {

    // Dynamically allocate memory for octree and records
    Octree* octree = new (std::nothrow) Octree();
    if(octree == nullptr){
        std::cerr << "Memory allocation failed" << std::endl;
        return;
    }

    std::vector<int> records(dataCapacity);

    // Initialize the records with random values between min and max value
    std::random_device rd;  
    std::mt19937 gen(rd()); 
    std::uniform_int_distribution<> dis(minValue, maxValue);

    for (size_t i = 0; i < records.size(); ++i) {
        records[i] = dis(gen);
    }

    // Load settings from XML configuration file
    std::ifstream configFile(configPath);
    if (!configFile.is_open()){
       std::cerr << "Failed to open the file!" << std::endl;
       return;
    } 

    int tileSize, worldWidth, worldHeight, cameraSpeed;
    configFile >> tileSize >> worldWidth >> worldHeight >> cameraSpeed;

    // Add string after searchString in dataList or append it if not found
    auto insertionPoint = std::find(dataList.begin(), dataList.end(), searchString);

    if (insertionPoint != dataList.end()){
        dataList.insert_after(insertionPoint, targetString);
    } else {
        dataList.push_front(targetString);  // or push_back to append at the end
    }
}
