['This is quite a large task to be solved in one go and may not cover all details depending on project specifics. Below is a simplified pseudo code version of what this might look like. Please note, it's not runnable as a C program but gives an idea about how such a logging framework could function.

```c
#include <stdarg.h>
#include <pthread.h>

// Define the logging levels
enum LogLevel { DEBUG, INFO, WARN, ERROR, FATAL };

typedef struct Logger {
  enum LogLevel level;
  void (*log)(struct Logger* logger, const char *fmt, ...);
} Logger;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log(Logger* logger, const char *fmt, ...) {
  va_list args;
  va_start(args, fmt);

  // Locking for thread safety
  pthread_mutex_lock(&mutex);

  switch (logger->level) {
    case DEBUG:
