from neo4j import GraphDatabase, basic_auth
import time
import logging
import threading
import random
from concurrent.futures import ThreadPoolExecutor

class NeoDB():
    def __init__(self):
        self.driver = GraphDatabase.driver(
            "bolt://localhost:7687", 
            auth=basic_auth("neo4j", "password")
        )
        logging.basicConfig(level=logging.INFO)

    def add_node(self, tx):
        result = tx.run('CREATE (a:Node {name: $name}) RETURN id(a)', name='new node')
        record = result.single()
        return record[0]  # this will be the internal Neo4j ID of the new node

    def start_transactions(self, num_threads):
        with self.driver.session() as session:
            for _ in range(num_threads):
                session.write_transaction(self.add_node)

if __name__ == "__main__":
