["Implementing this is quite complex task, but here's a simplified version that provides some guidance on how you might approach it. Note that error handling and extensive testing are crucial parts of writing such functions which will be responsible for managing resources like file descriptors or heap memory. 

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#define IP_LEN 16 // This could change based on the format of your IP addresses

typedef struct TCP_CONNECTION_RECORD {
    int socket;
    char *clientIP, *serverIP;
    struct TCP_CONNECTION_RECORD *next, *prev;
} ConnectionRecord;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
ConnectionRecord *head = NULL;

void add(int socket, char* clientIP, char* serverIP) {
    if (socket < 0) return; // Invalid socket fd 

    ConnectionRecord *node = malloc(sizeof(ConnectionRecord));
    node->clientIP = malloc(IP_LEN);
    node->serverIP = malloc(IP_LEN);
    strcpy(node->clientIP, clientIP);
    strcpy(node->serverIP, serverIP); 
    node->socket = socket;

    pthread_mutex_lock(&lock); // Lock for concurrent access handling
    if (head == NULL || head->socket > socket) {
        node->next = head;
        if(head != NULL) { 
            head->prev = node;
        }
        head = node;
    } else {
        ConnectionRecord *curr = head;
        while (curr->next != NULL && curr->next->socket < socket) {
            curr = curr->next;
        }
        node->next = curr->next;
        if(curr->next != NULL) { 
            curr->next->prev = node;
        }
        curr->next = node;
    }
    pthread_mutex_unlock(&lock); // Unlock after operation
}

void remove(int socket) {
    pthread_mutex_lock(&lock);
    ConnectionRecord *curr = head, *prev = NULL; 

    while (curr != NULL && curr->socket != socket) {
        prev = curr;
        curr = curr->next;
    }

    if(curr == NULL) { // node not found
        pthread_mutex_unlock(&lock);
        return; 
    }

    if (prev != NULL) {
        prev->next = curr->next;
    } else {
        head = curr->next;
    }
    free(curr->clientIP);
