    struct TCP_CONNECTION_RECORD *record;
    struct NODE *prev;
    struct NODE *next;
} Node;

// Head node for doubly linked list
Node *head = NULL;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Lock for thread safety

int validateIP(char *ip) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ip, &(sa.sin_addr)) == 1 || inet_pton(AF_INET6, ip, &(sa.sin_addr)) == 1;
}

void handleError(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

Node* createNode(ConnectionRecord *record) {
    if (validateIP(record->clientIP) && validateIP(record->serverIP)) {
        Node *node = malloc(sizeof(Node));
        if (node == NULL) handleError("malloc");

        node->record = record;
        node->prev = NULL;
        node->next = NULL;

        return node;
    } else {
        printf("Invalid IP address detected\n");
        exit(EXIT_FAILURE);
    }
}

void insertNode(Node *node) {
    pthread_mutex_lock(&lock);  // Acquire lock before modifying list

    if (head == NULL || head->record->socketFD > node->record->socketFD) {  // If list is empty or new node has lower FD than head
        node->next = head;
        if(head != NULL) head->prev = node;
        head = node;
    } else {
        Node *currentNode = head;
        while (currentNode->next != NULL && currentNode->next->record->socketFD < node->record->socketFD) {  // Find the correct position for insertion based on socket FD
            currentNode = currentNode->next;
        }
        node->next = currentNode->next;
        if (currentNode->next != NULL) currentNode->next->prev = node;
        currentNode->next = node;
        node->prev = currentNode;
    }

    pthread_mutex_unlock(&lock);  // Release lock after modification
}

void removeInactiveConnections() {
    Node *node = head;
    while (node != NULL) {
        if (!isSocketActive(node->record->socketFD)) {  // Assuming isSocketActive function checks socket activity
            pthread_mutex_lock(&lock);  // Acquire lock before modifying list

            Node *nextNode = node->next;
            if (node->prev != NULL) node->prev->next = node->next;
            else head = nextNode;
            if (nextNode != NULL) nextNode->prev = node->prev;

            free(node);  // Free memory occupied by inactive connection record

            pthread_mutex_unlock(&lock);  // Release lock after modification
        }

        node = node->next;
    }
}
