def log_info(msg):
    logging.info(msg)

class JSONStructureFactory:
    factories = defaultdict()

    @staticmethod
    def add_factory(id, factory):
        JSONStructureFactory.factories[id] = factory

    @staticmethod
    def create(id, jsonStr=None):
        if id not in JSONStructureFactory.factories:
            log_info("No such structure.")
            return None

        try:
