```C
#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct QoS_FLOW_INFO_T {
    int FLOW_ID;
    int PRIORITY_LEVEL;
    void *PACKET_BUFFER;
} QoS_FLOW_INFO_T;

#define MAX_SIZE 1024
#define TOTAL_MEMORY_USAGE 8 * 1024 * 1024 // 8 MB in bytes

typedef struct Queue {
    int front, rear, size;
    unsigned capacity;
    QoS_FLOW_INFO_T* array;
} Queue;

Queue* createQueue(unsigned capacity)
{
    Queue* queue = (Queue*) malloc(sizeof(struct Queue));
    queue->capacity = capacity;
    queue->front = queue->size = 0; 
    queue->rear = capacity - 1;  
    queue->array = (QoS_FLOW_INFO_T*) malloc(queue->capacity * sizeof(QoS_FLOW_INFO_T));
    return queue;
}

int isFull(Queue* queue)
{  return (queue->size == queue->capacity); }

int isEmpty(Queue* queue)
{  return (queue->size == 0); }

void enqueue(Queue* queue, int item)
{
    if (isFull(queue))
        return;
    queue->rear = (queue->rear + 1)%queue->capacity;
    queue->array[queue->rear].FLOW_ID = item;
    queue->array[queue->rear].PRIORITY_LEVEL = 0;
    queue->array[queue->rear].PACKET_BUFFER = malloc(MAX_SIZE);
    memset(queue->array[queue->rear].PACKET_BUFFER, 0, MAX_SIZE); // Initialize packet buffer to 0's
    queue->size = queue->size + 1;
}

QoS_FLOW_INFO_T dequeue(Queue* queue)
{
    if (isEmpty(queue))
        assert("empty queue" && 0); // raise error

    QoS_FLOW_INFO_T item = queue->array[queue->front];
    free(item.PACKET_BUFFER); // Free dynamically allocated memory
    queue->front = (queue->front + 1)%queue->capacity;
    queue->size = queue->size - 1;
    return item;
}
```
