#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>

enum class NetworkStatus { UP, DOWN, ISSUE };

class NetworkStatusMonitor{
private:
    std::mutex mtx;
    std::map<std::string, NetworkStatus> interfaceStatuses;
    std::map<std::string, int> checkIntervals; // in milliseconds

    void periodicCheck(const std::string &interface){
        while(true) { 
            // Get system call to fetch network status
            NetworkStatus status = getNetworkInterfaceStatusFromSystemCall(interface);

            // Lock mutex before updating interface statuses map
            std::lock_guard<std::mutex> lock(mtx);
            interfaceStatuses[interface] = status;
        } 
    }
public:
     NetworkStatusMonitor(){
         // Adding some dummy interfaces and check intervals for demonstration
         interfaceStatuses["eth0"] = NetworkStatus::UP;
         interfaceStatuses["wlan0"] = NetworkStatus::DOWN;

         checkIntervals["eth0"] = 1000;  // milliseconds
         checkIntervals["wlan0"] = 2000; // milliseconds
     }

    void startMonitoring(){
        for(auto const &[interface, interval] : checkIntervals){
            std::thread t(&NetworkStatusMonitor::periodicCheck, this, interface);
            t.detach(); 
        }
    }

    NetworkStatus getInterfaceStatus(const std::string& interface) {
        std::lock_guard<std::mutex> lock(mtx);
         if (interfaceStatuses.find(interface) == interfaceStatuses.end()) {
            throw std::invalid_argument("Invalid network interface name");
         }
         return interfaceStatuses[interface];
    }

     void simulateChangeInNetworkStatus(const std::string& interface, NetworkStatus status){
        std::lock_guard<std::mutex> lock(mtx);
         if (interfaceStatuses.find(interface) == interfaceStatuses.end()) {
            throw std::invalid_argument("Invalid network interface name");
         }
         interfaceStatuses[interface] = status; 
    }

     std::string getStatus() const{
        std::lock_guard<std::mutex> lock(mtx);
        std::string result;
        for (auto& it : interfaceStatuses){
            result += "Interface: " + it.first + ", Status: ";
            switch(it.second){
                case NetworkStatus::UP:   result+="Up\n"; break;
                case NetworkStatus::DOWN: result+="Down\n"; break;
                case NetworkStatus::ISSUE:result+="Issue\n";break;
            }
        }
        return result;
    }  
};
```
