from collections import deque

class NFAPI_CRC_INDICATION_PDU_T:
    _factory_registry = {}
    _max_active = 500

    def __init__(self, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG):
        self.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG
        self.RNTI = RNTI
        self.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG

    def to_json(self):
        try:
            return json.dumps(self.__dict__)
        except MemoryError as e:
            logging.error("Memory allocation failed during JSON creation.", exc_info=True)

    @classmethod
    def from_json(cls, json_string):
        try:
            data = json.loads(json_string)
            if len(list(NFAPI_CRC_INDICATION_PDU_T._factory_registry)) > cls._max_active:
                logging.warning("Maximum active structures exceeded.")
                return None
            else:
                return NFAPI_CRC_INDICATION_PDU_T(**data)
        except MemoryError as e:
            logging.error("Memory allocation failed during object creation.", exc_info=True)

    @classmethod
    def add_factory(cls, id, factory):
        cls._factory_registry[id] = factory

    @classmethod
    def create_instance(cls, id, *args):
        if id in cls._factory_registry:
            try:
                return cls._factory_registry[id](*args)
            except MemoryError as e:
                logging.error("Memory allocation failed during object creation.", exc_info=True)
``` 

