Please note that due to the complexities and potential security issues involved with file handling, especially in larger applications, you'd typically want to use some kind of established library for this kind of work in a production environment rather than attempting to roll your own. However, here is an example of how you might start structuring your code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <openssl/md5.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#define READ_SIZE 1024 * 1024 // 1MB
#define RETRY_LIMIT 3

typedef struct {
    unsigned char digest[MD5_DIGEST_LENGTH];
    int length;
} MD5Result;

void getFileMD5(const char* filename, MD5Result* result) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open file");
        return;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Failed to get file stats");
        close(fd);
        return;
    }

    result->length = st.st_size;

    MD5_CTX context;
    unsigned char buffer[READ_SIZE];
    ssize_t bytesRead = 0;
    int retryCount = 0;

    do {
        MD5_Init(&context);

        while ((bytesRead = read(fd, buffer, READ_SIZE)) > 0) {
            MD5_Update(&context, buffer, bytesRead);
        }

        if (bytesRead == -1 && retryCount++ < RETRY_LIMIT) {
            perror("Failed to read file, retrying...");
            continue;
        } else if (bytesRead == -1) {
            perror("Failed to read file after multiple attempts");
            close(fd);
            return;
        }
    } while (lseek(fd, 0, SEEK_SET) != 0 && retryCount++ < RETRY_LIMIT);

    if (retryCount >= RETRY_LIMIT) {
        perror("Failed to seek file after multiple attempts");
        close(fd);
        return;
    }

    MD5_Final(result->digest, &context);
    close(fd);
}
```
This is just a sketch and does not handle all the requirements you've mentioned. It also lacks error handling and logging mechanisms. You would need to implement these yourself or use some existing library like glib for logging and error handling. 

