typedef struct {
    char PHY_STATS_TAG[RB_ID_SIZE];
    int CELL_ID;
    long TIME_STAMP;
} PHY_STATS_PDU_T;

int allocateAndPopulate(PHY_STATS_PDU_T **pdu, size_t N) {
    if (N <= 0 || N > MAX_ARRAY_SIZE) {
        printf("Error: Invalid array size\n");
        return -1;
    }

    // Calculate total memory usage and check for overflow
    size_t totalMemoryUsage = N * sizeof(PHY_STATS_PDU_T);
    if (totalMemoryUsage > MAX_MEMORY_USAGE) {
        printf("Error: Not enough memory\n");
        return -2;
    }

    // Allocate memory for the array
    *pdu = malloc(N * sizeof(PHY_STATS_PDU_T));
    if (*pdu == NULL) {
        printf("Error: Failed to allocate memory\n");
        return -3;
    }

    // Populate the array with valid data
    for (size_t i = 0; i < N; ++i) {
        strncpy((*pdu)[i].PHY_STATS_TAG, "RB", RB_ID_SIZE);
        (*pdu)[i].CELL_ID = i + 1;
        (*pdu)[i].TIME_STAMP = 0;
    }

    return 0;
}

void serialize(const PHY_STATS_PDU_T *array, size_t N, char **buffer) {
    // Calculate total memory usage and check for overflow
    size_t totalMemoryUsage = N * sizeof(PHY_STATS_PDU_T);

    if (totalMemoryUsage > MAX_MEMORY_USAGE) {
        printf("Error: Not enough memory\n");
        return;
    }

    // Allocate memory for the buffer
    *buffer = malloc(totalMemoryUsage);
    if (*buffer == NULL) {
        printf("Error: Failed to allocate memory\n");
        return;
    }

    // Serialize the array into a byte array
    memcpy(*buffer, array, totalMemoryUsage);
}
```
