['```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define BUFFER_SIZE 50
#define MAX_SEMAPHORES 100

// Define the semaphore struct with index and unique value
typedef struct {
    int id;
    int value;
    sem_t* sem;
} Semaphore;

Semaphore* semaphores[MAX_SEMAPHORES];
int top = -1;
pthread_mutex_t lock;

// Function to create semaphore with unique name and initial value
void createSemaphore(const int id, const int value) {
    if (top >= MAX_SEMAPHORES-1) {
        printf("Maximum number of semaphores reached\n");
        return;
    }

    // Allocate memory for new Semaphore
    Semaphore* s = malloc(sizeof(*s));
    if (s == NULL) {
        perror("Failed to allocate memory for semaphore");
        exit(EXIT_FAILURE);
    }

    // Create the semaphore with unique name and initial value
    char* name = malloc(20 * sizeof(*name));
    sprintf(name, "Sem%d", id);
    s->sem = sem_open(name, O_CREAT | O_EXCL, 0644, value);
    free(name); // Free the allocated memory for name

    if (s->sem == SEM_FAILED) {
        perror("Failed to create semaphore");
        exit(EXIT_FAILURE);
    }

    s->id = id;
    s->value = value;

    // Add the new Semaphore to array of Semaphores
    pthread_mutex_lock(&lock); 
    semaphores[++top] = s;
    pthread_mutex_unlock(&lock); 
}

// Function to delete all created semaphores
void deleteSemaphores() {
    for (int i = 0; i <= top; i++) {
        sem_close(semaphores[i]->sem); // close the semaphore 
        sem_unlink(semaphores[i]->sem); // unlink it from system
        free(semaphores[i]); // Free the allocated memory for Semaphore struct
    }
}
```
This is a C program that creates and manages multiple named semaphores using POSIX semaphore library. It also includes error handling for semaphore creation, deletion, and synchronization with mutex lock to avoid race conditions. 

