#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <stdio.h>

typedef struct {
    sem_t sem;
    int priority;
} PrioritySemaphore;

PrioritySemaphore sharedBuffer[50]; // The shared buffer has a fixed size of 50 elements
int bufferIndex = 0; // Index to the next available position in the shared buffer

pthread_mutex_t bufferMutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for synchronizing access to the shared buffer

void* produce(void *arg) {
    int index = *((int*) arg);

    while (1) {
        /* Simulate network latency */
        struct timespec ts = {0, 50000000}; // 50 ms
        nanosleep(&ts, NULL);

        sem_wait(&sharedBuffer[index].sem);

        pthread_mutex_lock(&bufferMutex);
        if (bufferIndex < 50) {
            /* Produce item */
            sharedBuffer[bufferIndex].priority = index; // Set the priority of this operation
            bufferIndex++; // Increment the next available position in the shared buffer

            printf("Produced item with priority %d\n", index);
        } else {
            printf("Buffer is full. Producer waits for empty space.\n");
        }

        pthread_mutex_unlock(&bufferMutex);
    }

    return NULL;
}

void* consume(void *arg) {
    int index = *((int*) arg);

    while (1) {
        /* Simulate network latency */
        struct timespec ts = {0, 50000000}; // 50 ms
        nanosleep(&ts, NULL);

        pthread_mutex_lock(&bufferMutex);
        if (bufferIndex > 0) {
            /* Consume item */
            bufferIndex--; // Decrement the next available position in the shared buffer

            printf("Consumed item with priority %d\n", index);
        } else {
            printf("Buffer is empty. Consumer waits for items.\n");
        }

        pthread_mutex_unlock(&bufferMutex);
    }

    return NULL;
}

int main() {
    /* Initialize semaphores */
    int i;
    for (i = 0; i < 100; i++) {
        if (sem_init(&sharedBuffer[i].sem, 0, i % 50) != 0) { // Unique initial value
            printf("Semaphore initialization failed\n");
            return 1;
        }
    }

    /* Create producer and consumer threads */
    pthread_t producers[10];
    for (i = 0; i < 10; i++) {
        if (pthread_create(&producers[i], NULL, produce, &i) != 0) {
            printf("Producer thread creation failed\n");
            return 1;
        }
    }

    pthread_t consumers[10];
    for (i = 0; i < 10; i++) {
        if (pthread_create(&consumers[i], NULL, consume, &i) != 0) {
            printf("Consumer thread creation failed\n");
            return 1;
        }
    }

    /* Wait for all threads to complete */
    for (i = 0; i < 10; i++) {
        pthread_join(producers[i], NULL);
        pthread_join(consumers[i], NULL);
    }

    /* Delete semaphores */
    for (i = 0; i < 100; i++) {
        if (sem_destroy(&sharedBuffer[i].sem) != 0) {
            printf("Semaphore deletion failed\n");
            return 1;
        }
    }

    return 0;
}
```

