// Definition for ECC and QoS, you can replace these with actual definitions
typedef int ECC;
typedef float QoS;

typedef struct {
    double timestamp;
    unsigned long frame_number;
    int signal_strength;
    char modulation_type[32]; // Assume the length of Modulation type as 32
    int channel_bandwidth;
    float packet_loss_rate;
    float jitter;
    ECC ecc_parity_bits;
    QoS qos_rating;
} FrameStatistics;

typedef struct {
    pthread_mutex_t lock;
    int size;
    int max_size;
    FrameStatistics* data; // Array of FrameStatistics structures
    FrameStatistics* sorted_data; // Sorted array of FrameStatistics structures for quick access
} DynamicArray;

DynamicArray* create(int max_size) {
    if (max_size > 50000) return NULL; // Limit the maximum size to 50,000
    DynamicArray* arr = malloc(sizeof(DynamicArray));
    if (!arr) return NULL;
    arr->data = calloc(max_size, sizeof(FrameStatistics));
    arr->sorted_data = calloc(max_size, sizeof(FrameStatistics));
    if (!arr->data || !arr->sorted_data) {
        free(arr->data);
        free(arr->sorted_data);
        free(arr);
        return NULL;
    }
    arr->size = 0;
    arr->max_size = max_size;
    pthread_mutex_init(&arr->lock, NULL); // Initialize lock for thread safety
    return arr;
}

void destroy(DynamicArray* arr) {
    if (arr) {
        free(arr->data);
        free(arr->sorted_data);
        pthread_mutex_destroy(&arr->lock); // Destroy lock
        free(arr);
    }
}

void add(DynamicArray* arr, FrameStatistics frame) {
    if (pthread_mutex_lock(&arr->lock)) return; // Lock before modifying the array
    if (arr->size < arr->max_size) {
        arr->data[arr->size] = frame;
        arr->size++;
    }
    pthread_mutex_unlock(&arr->lock); // Unlock after modifying the array
}
```
