typedef struct node {
    SESSION_CACHE_ENTRY entry;
    struct node *next;
} NODE;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
NODE* head = NULL;
int currentSize = 0;  // Current size in bytes of SESSION_DATA in the cache.

// Function to add an entry into the cache, with thread safety and error checking
bool manage_user_session_cache(SESSION_CACHE_ENTRY *entry) {
    pthread_mutex_lock(&lock);

    // Check if adding this entry will exceed 8MB limit. If so, fail to add.
    if (currentSize + strlen(entry->USER_NAME) + 1 > MAX_CACHE_SIZE) {
        pthread_mutex_unlock(&lock);
        return false;
    }

    // Create a new node and add the entry to it.
    NODE *newNode = malloc(sizeof(NODE));
    if (newNode == NULL) {
        pthread_mutex_unlock(&lock);
        return false;  // Failed to allocate memory for new node.
    }

    newNode->entry = *entry;  // Copy the entry data into the new node.
    currentSize += strlen(entry->USER_NAME) + 1;  // Update the size counter.
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
    return true;
}
