public class WeatherActivityService {
    private static final Logger logger = LoggerFactory.getLogger(WeatherActivityService.class);

    // Assuming you have a WeatherAPI interface with methods to fetch weather data and activity recommendations
    Retrofit retrofit = new Retrofit.Builder()
            .baseUrl("http://api.weatherandactivity.com/")
            .addConverterFactory(GsonConverterFactory.create())
            .build();

    WeatherAPI api = retrofit.create(WeatherAPI.class);

    // Using Guava's Cache for caching weather data and activities
    Cache<String, String> cache = CacheBuilder.newBuilder()
            .maximumSize(1000)
            .expireAfterWrite(1, TimeUnit.HOURS)
            .build();

    // Using Apache HttpClient for network calls
    CloseableHttpClient httpclient = HttpClients.createDefault();

    public synchronized String getReport(String query) {
        // Check if report is in cache
        String cachedResponse = cache.getIfPresent(query);

        if (cachedResponse != null) return cachedResponse;

        try {
            HttpGet request = new HttpGet("http://api.weatherandactivity.com/" + query);
            HttpResponse response = httpclient.execute(request);

            int statusCode = response.getStatusLine().getStatusCode();

            if (statusCode == 200) {
                String result = EntityUtils.toString(response.getEntity());

                // Add to cache for future use
                cache.put(query, result);
                return result;
            } else {
                logger.error("API request failed with status code: " + statusCode);

                // Provide fallback options or handle error as per your requirements
                return null;
            }
        } catch (IOException e) {
            logger.error("Network error", e);

            // Provide fallback options or handle error as per your requirements
            return null;
        }
    }
}
