int poolCount = 0;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initPool() {
    for (int i=0; i<POOLSIZE; i++) {
        pool[i] = malloc(sizeof(node));
    }
}

// Function to populate list with random structures
node* createList(int n, int *allocs, int *fails) {
    node* head = NULL;
    node** current = &head;

    srand(time(0));  // For generating different values each time the program is run

    for (int i=0; i<n; i++) {
        pthread_mutex_lock(&mutex);   // Lock mutex for thread safety

        if (*current == NULL && poolCount < POOLSIZE) {
            *current = pool[poolCount++];  // Reuse from memory pool if possible
            (*allocs)++;
        } else if (poolCount >= POOLSIZE) {
            pthread_mutex_unlock(&mutex);
            (*fails)++;
            continue;   // Skip this iteration and try again later if pool is full or allocation fails
        } else {
            *current = malloc(sizeof(node));  // Allocate new memory
            (*allocs)++;
        }

        pthread_mutex_unlock(&mutex);   // Unlock mutex after critical section

        if (!(*current)) {
            printf("Memory allocation failed\n");
            continue;
        }

        // Populate the structure in this node with random values
        (*current)->data.RNTI = rand();
        (*current)->data.CRCFLAG = rand() % 2;   // Assuming valid CRCFLAG is either 0 or 1

        current = &((*current)->next);
    }

    return head;
}
