    AES_KEY dec_key;
    AES_set_decrypt_key(key, 128, &dec_key);
    AES_cbc_encrypt(ciphertext, decrypted, ciphertext_len, &dec_key, iv, AES_DECRYPT);
}

// MD5 hashing function wrapper
void md5_hash(unsigned char* input, unsigned long length, unsigned char* output) {
    MD5_CTX context;
    MD5_Init(&context);
    MD5_Update(&context, input, length);
    MD5_Final(output, &context);
}
