    char* payload;
} NFAPI_RX_FRAME_PAYLOAD_T;

typedef struct {
    int RNTI;
    NFAPI_RX_FRAME_PAYLOAD_T* payload;
} NFAPI_RX_FRAME_PDU_T;

NFAPI_RX_FRAME_PDU_T* createFrame(int frameLength, int RNTI) {
    if (frameLength <= 0 || RNTI < 0) {
        return NULL; // Invalid input
    }

    NFAPI_RX_FRAME_PAYLOAD_T* payload = malloc(sizeof(NFAPI_RX_FRAME_PAYLOAD_T));
    if (payload == NULL) {
        return NULL; // Out of memory
    }

    payload->frame_length = frameLength;
    payload->payload = malloc(sizeof(char) * frameLength);
    if (payload->payload == NULL) {
        free(payload);
        return NULL; // Out of memory
    }

    memset(payload->payload, 0, sizeof(char) * frameLength); // Initialize the payload with zeroes

    NFAPI_RX_FRAME_PDU_T* frame = malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    if (frame == NULL) {
        free(payload->payload);
        free(payload);
        return NULL; // Out of memory
    }

    frame->RNTI = RNTI;
    frame->payload = payload;

    return frame;
}

void destroyFrame(NFAPI_RX_FRAME_PDU_T* frame) {
    if (frame == NULL || frame->payload == NULL) {
        return; // Null pointer
    }

    free(frame->payload->payload);
    free(frame->payload);
    free(frame);
}
