['Here is a C code snippet that satisfies all your requirements using glibc and getaddrinfo() function to perform DNS resolution:
```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>

// Define the maximum number of DNS queries per session and IP address buffer size
#define MAX_QUERIES 1000
#define BUFFER_SIZE 256

// Declare a static variable to track the current number of DNS queries performed in this session
static int numQueries = 0;

int resolveHostname(const char *hostname, u_char ipAddr[BUFFER_SIZE]) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[INET6_ADDRSTRLEN];

    // Check if maximum number of queries per session has been reached
    if (numQueries >= MAX_QUERIES) {
        fprintf(stderr, "Maximum DNS queries limit reached.\n");
        return -1;
    }

    numQueries++;

    // Setup hints for getaddrinfo() function
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_INET; // Use IPv4 only
    hints.ai_socktype = SOCK_STREAM; // TCP socket

    // Perform DNS resolution
    if ((errcode = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo() failed: %s\n", gai_strerror(errcode));
        return -2;
    }

    // Extract IP address from the result
    void *addr;
    if (res->ai_family == AF_INET) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
        addr = &(ipv4->sin_addr);
    } else { // IPv6
        struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
        addr = &(ipv6->sin6_addr);
    }

    // Convert the IP address to a string and copy it into ipAddr buffer
    inet_ntop(res->ai_family, addr, (char *)ipAddr, BUFFER_SIZE);

    freeaddrinfo(res); // Free memory allocated by getaddrinfo()

    return 0;
}
```
This function takes a hostname as input and returns the IP address in a u_char array. It also has error checking to ensure that it does not exceed the maximum number of DNS queries per session. The maximum number of DNS queries per session is defined by the MAX_QUERIES macro at the top of the file, which you can adjust according to your needs.
']

