#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>

void computeMD5(const char *filepath) {
    FILE *inFile = fopen (filepath, "rb");
    MD5_CTX mdContext;
    int bytes;
    unsigned char data[1024];

    if (inFile == NULL) {
        printf ("%s can't be opened.\n", filepath);
        return;
    }

    MD5_Init(&mdContext);
    while((bytes = fread(data, 1, 1024, inFile)) != 0){
        MD5_Update(&mdContext, data, bytes);
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Final(digest, &mdContext);

    char mdString[33];
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);
    }

    printf("%s\n", mdString);
}
```
This example uses OpenSSL library for MD5 hash generation. It opens a file in binary mode, reads 1024 bytes at a time and feed it to the MD5 context until there is no more data to read from the file. After that, it computes the final digest.

Keep in mind this is just the basic implementation for computing MD5 hash of large files. The rest part of your requirements would involve much more complex coding and I strongly suggest breaking down such a large project into smaller manageable tasks and tackling them one at a time.
