        LogEntry entry = pq.top();
        pq.pop();

        std::thread t([&processor, &monitor, entry]() {
            for (int i = 0; i < 5; ++i) { // Retry up to 5 times on failure.
                try {
                    processor.process(entry);
                    monitor.reportStatus();
                    break;
                } catch (const std::exception& e) {
                    if (i == 4) {
                        // Log error and continue execution after maximum retries reached.
                        std::cerr << "Failed to process entry after 5 attempts." << std::endl;
                    } else {
                        // Sleep for exponential backoff before next attempt.
                        std::this_thread::sleep_for(std::chrono::seconds(1 << i));
                    }
                }
            }
        });

        threads.push_back(std::move(t));
    }

    // Join all threads to ensure they have finished before exiting the main function.
    for (auto& t : threads) {
        if (t.joinable()) {
            t.join();
        }
    }

    return 0;
}
```
