class LogReader:
    def __init__(self, filename):
        self.filename = filename

    def read_file(self):
        try: 
            if self.filename.endswith('.gz'):
                with gzip.open(self.filename, 'rt') as f:
                    return self._read_chunks(f)

            elif self.filename.endswith('.bz2'):
                with bz2.open(self.filename, 'rt') as f:
                    return self._read_chunks(f)

            else: 
                with open(self.filename, 'r', errors='replace') as f:
                    return self._read_chunks(f)

        except Exception as e:
            logger.error('Error while reading file {}'.format(self.filename))
            logger.debug(str(e), exc_info=True)

    def _read_chunks(self, f):
        while True: 
            data = f.readlines(CHUNK_SIZE)
            if not data: break
            yield data

