#include <stdio.h>

void process_packet(u_char *args, const struct pcap_pkthdr *header, const u_char *packet) {
    //Ethernet Header
    struct ethhdr *eth = (struct ethhdr *)packet;
    if(ntohs(eth->h_proto) != ETH_P_IP) {
        printf("Not an IP Packet\n");
        return;
    }
    packet += sizeof(struct ethhdr);

    //Ip Header
    struct iphdr *iph = (struct iphdr *)packet;
    if(iph->protocol != IPPROTO_TCP) {
        printf("Not a TCP Packet\n");
        return;
    }
    packet += sizeof(struct iphdr);

    //Tcp Header
    struct tcphdr *tcph = (struct tcphdr *)packet;

    //Print Sequence Number, Window Size and Calculate RTT. 
    printf("Sequence number: %u\n", ntohl(tcph->seq));
    printf("Window size: %hu\n", ntohs(tcph->window));
}

void process_pcap_files() {
