typedef struct {
    int (*log)(const char*); // Logging function to be used
    void (*callback)(int, int); // Callback for progress updates
} Config;

EVP_CIPHER_CTX *encryptFile(const char* inpath, const char* mode, size_t bufferSize, Config* config) {
    FILE* infile = fopen(inpath, "r");
    if (infile == NULL) {
        (*config->log)("Failed to open input file.");
        return NULL; // Return null on error
    }

    OpenSSL_add_all_ciphers();
    const EVP_CIPHER* cipher = EVP_get_cipherbyname(mode);
    if (cipher == NULL) {
        (*config->log)("Unsupported encryption mode.");
        return NULL; // Return null on error
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        (*config->log)("Failed to create cipher context.");
        return NULL; // Return null on error
    }

    unsigned char key[EVP_MAX_KEY_LENGTH] = {0};
    unsigned char iv[EVP_MAX_IV_LENGTH] = {0};

    if (!EVP_CIPHER_CTX_init(ctx)) { // Initialize the cipher context with a default key and IV
        (*config->log)("Failed to initialize cipher context.");
        return NULL; // Return null on error
    }

    (*config->log)("Encryption process started.");

    unsigned char buffer[bufferSize];
    size_t bytesRead, totalBytes = 0;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), infile)) > 0) {
        int outlen1 = 0;
        if (!EVP_CIPHER_CTX_update(ctx, buffer, bytesRead, &outlen1)) { // Encrypt the chunk
            (*config->log)("Failed to update cipher context.");
            return NULL; // Return null on error
        }

        totalBytes += bytesRead;

        if (bufferSize < bytesRead && !(*config->log)("Buffer size exceeded. Adjusting dynamically.")) {
            bufferSize = bytesRead;
        }

        (*config->callback)(totalBytes, outlen1); // Update progress
    }

    fclose(infile);

    (*config->log)("Encryption process completed.");

    return ctx;
}
```
Please note that this is a basic example and does not include the functionality for RSA or ECC encryption modes, and the progress callback might need additional implementation to handle edge cases. Also, you should adjust the buffer size dynamically based on available memory if needed in your specific use case.
