MACArray* initializeMacArray() {
    MACArray *array = (MACArray *)malloc(sizeof(MACArray));
    pthread_mutex_init(&(array->lock), NULL);
    array->capacity = 10;  // Initial capacity.
    array->size = 0;
    array->data = malloc(array->capacity * sizeof(MAC_CONTEXT_T));
    return array;
}

void resizeMacArray(MACArray* macArray, int newCapacity) {
    pthread_mutex_lock(&(macArray->lock));

    if (newCapacity > macArray->capacity) {
        MAC_CONTEXT_T *oldData = macArray->data;
        macArray->data = malloc(newCapacity * sizeof(MAC_CONTEXT_T));

        // Copy data to the new array.
        for (int i = 0; i < macArray->size; ++i) {
            macArray->data[i] = oldData[i];
        }

        free(oldData);  // Free the old data.
    } else if (newCapacity <= macArray->capacity / 2 && newCapacity > 10) {
        MAC_CONTEXT_T *oldData = macArray->data;
        macArray->data = malloc(newCapacity * sizeof(MAC_CONTEXT_T));

        // Copy data to the new array.
        for (int i = 0; i < macArray->size && i < newCapacity; ++i) {
            macArray->data[i] = oldData[i];
        }

        free(oldData);  // Free the old data.
    }

    macArray->capacity = newCapacity;
    pthread_mutex_unlock(&(macArray->lock));
}

MAC_CONTEXT_T* addContextToMacArray(MACArray* array, MAC_CONTEXT_T context) {
    pthread_mutex_lock(&(array->lock));

    if (array->size == array->capacity) {
        resizeMacArray(array, array->capacity * 2);
    }

    int index = array->size;
    array->data[index] = context;
    array->size++;

    pthread_mutex_unlock(&(array->lock));
    return &array->data[index];
}

