int num_contexts = 0;
pthread_mutex_t contexts_lock = PTHREAD_MUTEX_INITIALIZER;

void *manage_and_process(void *arg) {
    // Get the thread-specific index from the argument
    int index = *((int *) arg);

    while (1) {
        pthread_mutex_lock(&contexts_lock);

        if (index >= num_contexts) {
            pthread_mutex_unlock(&contexts_lock);
            break;
        }

        MAC_CONTEXT_T *ctx = contexts[index];

        // Handle asynchronous updates, error handling etc.

        pthread_mutex_unlock(&contexts_lock);

        // Sleep for a while to avoid busy waiting
        usleep(100000);
    }

    free(arg);
    return NULL;
}

void reconfigure_managed_structures(int N) {
    pthread_mutex_lock(&contexts_lock);

    // Reallocate the array with a new size
    contexts = realloc(contexts, sizeof(MAC_CONTEXT_T *) * N);

    if (N > num_contexts) {
        // Initialize any new structures
        for (int i = num_contexts; i < N; ++i) {
            contexts[i] = malloc(sizeof(MAC_CONTEXT_T));
            // ... initialize fields as needed
        }
    } else if (N < num_contexts) {
        // Free any structures that are no longer needed
        for (int i = N; i < num_contexts; ++i) {
            free(contexts[i]);
        }
    }

    num_contexts = N;

    pthread_mutex_unlock(&contexts_lock);
}
```

In this skeleton code, `manage_and_process` is the function run by each thread. It continually checks and processes a part of the structures, ensuring that threads don't step on each other toes by locking access to the shared array with a mutex. The `reconfigure_managed_structures` function can be used to adjust the number of managed structures dynamically.

