    }
}

void removeFromQueue(int pid) {
    for(int i = qStart; i != qEnd; i = (i + 1) % 1024) {
        if(queue[i]->pid == pid) {
            free(queue[i]);
            for(int j = i; j < qEnd - 1; ++j) {
                queue[j] = queue[j + 1];
            }
            --qEnd;
            break;
        }
    }
}

