}

int runCommand(Process *p) {
    pid_t pid = fork();
    if (pid == 0) {  // Child process
        dup2(p->in_fd, STDIN_FILENO);
        dup2(p->out_fd, STDOUT_FILENO);
        dup2(p->err_fd, STDERR_FILENO);
        execve(strtok(p->cmd," \t"), &p->cmd, p->envp);
    } else if (pid < 0) {  // Error forking process
        return -1;
    } else {  // Parent process
        int status;
        waitpid(pid, &status, 0);
        removeFromQueue(pid);
        if(WIFEXITED(status)) {
            logError("Command exited with status: %d", WEXITSTATUS(status));
            return 1;
        } else if (WIFSIGNALED(status)) {
