        exit(-1);
    }

    while(!stopFlag) { // Main loop that processes commands in the queue
        if(qStart != qEnd) {
            int result = runCommand(queue[qStart]);
            if(result == 0) {
                sendLogToMonitoringService("Successfully executed command");
            } else if(result < 0) {
                logError("Failed to execute command: %s", strerror(errno));
                sendLogToMonitoringService("Failed to execute command");
            }
            ++qStart; // Move the start pointer of the queue
        }
