import com.mashape.unirest.http.HttpResponse;
import com.mashape.unirest.http.Unirest;
import com.mashape.unirest.http.exceptions.UnirestException;
import com.google.gson.Gson;
import java.util.*;

public class PokemonWeaknessFetcher {
    private static final String API_URL = "https://pokeapi.co/api/v2/pokemon/{name}";
    private Map<String, List<String>> cache = new HashMap<>();

    public List<String> getWeaknesses(Pokemon pokemon) {
        if (cache.containsKey(pokemon.getName())) {
            return cache.get(pokemon.getName());
        } else {
            try {
                HttpResponse<String> response = Unirest.get(API_URL)
                        .routeParam("name", pokemon.getName())
                        .asString();

                if (response.getStatus() == 200) {
                    Gson gson = new Gson();
                    PokemonApiResponse apiResponse = gson.fromJson(response.getBody(), PokemonApiResponse.class);

                    List<String> weaknesses = getWeaknessesFromType(apiResponse.types[0].type.name);
                    cache.put(pokemon.getName(), weaknesses);
                    return weaknesses;
                } else {
                    System.out.println("Failed to fetch Pokemon data, status: " + response.getStatus());
                    return Collections.emptyList();
                }
            } catch (UnirestException e) {
                System.out.println("Failed to make API request");
                return Collections.emptyList();
            }
        }
    }

    private List<String> getWeaknessesFromType(String type) {
        switch (type) {
            case "fire":
                return Arrays.asList("water", "ground", "rock");
            case "water":
                return Arrays.asList("electric", "grass");
            // Add other types here...
            default:
                System.out.println("Unknown type: " + type);
                return Collections.emptyList();
        }
    }
}
```

