["Here is a sample implementation in C using OpenSSL library for MD5 hashing and pthreads library for thread safety. It uses a simple hashtable cache to optimize performance by avoiding duplicate computations. 

```c
#include <stdio.h>
#include <string.h>
#include <openssl/md5.h>
#include <pthread.h>

typedef struct node {
    char *key;
    unsigned char value[MD5_DIGEST_LENGTH];
    struct node *next;
} Node;

Node **cache = NULL;
const int CACHE_SIZE = 1024;  // size of the cache array
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

unsigned char* process_and_hash_string(char *str) {
    static unsigned char result[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;

    // Trim whitespace and convert to uppercase
    int i, j = 0;
    for (i = 0; str[i] != '\0'; ++i) {
        if (str[i] != ' ' && (str[i] < 'A' || str[i] > 'Z')) {
            str[j++] = toupper(str[i]);
        } else if (str[i] == ' ') {
            str[j++] = '_';
        }
    }
    str[j] = '\0';  // mark the end of string

    pthread_mutex_lock(&lock);

    // Check cache
    Node *node;
    for (int i = 0; i < CACHE_SIZE; ++i) {
        node = cache[i];
        while (node != NULL) {
            if (strcmp(node->key, str) == 0) {  // found in cache
                memcpy(result, node->value, MD5_DIGEST_LENGTH);
                pthread_mutex_unlock(&lock);
                return result;
            }
            node = node->next;
        }
    }

    // Compute hash and add to cache
    MD5_Init(&ctx);
    MD5_Update(&ctx, str, strlen(str));
    MD5_Final(result, &ctx);

    // Add to cache
    node = malloc(sizeof(Node));  // allocate memory from heap for new node
    node->key = strdup(str);
    memcpy(node->value, result, MD5_DIGEST_LENGTH);
    int index = (int)result[0] % CACHE_SIZE;  // simple hash function
    node->next = cache[index];
    cache[index] = node;

    pthread_mutex_unlock(&lock);

    return result;
}
```

This is a basic implementation and may need additional modifications to handle edge cases, error handling, memory management, and performance optimizations. It uses heap allocation for caching hashed strings as they are dynamically allocated in the function based on the input string. 

