typedef struct {
    int CELL_ID;
    time_t TIMESTAMP;
    int CONNECTION_STATUS;
} MAC_CONTEXT_T;

MAC_CONTEXT_T* contexts = NULL;
int N = 0;
pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;

void reconfigure(int newN) {
    pthread_rwlock_wrlock(&lock);

    if (newN != N) {
        MAC_CONTEXT_T* oldContexts = contexts;

        contexts = calloc(newN, sizeof(MAC_CONTEXT_T));
        for (int i = 0; i < newN && i < N; ++i) {
            contexts[i] = oldContexts[i];
        }

        if (oldContexts != NULL) {
            free(oldContexts);
        }

        N = newN;
    }

    pthread_rwlock_unlock(&lock);
}

// Other functions for handling data updates, error handling, thread safety etc. would go here...
```
