class LogProcessor {
public:
    LogProcessor(int alertThreshold, int timeWindow) 
        : alertThreshold_(alertThreshold), timeWindow_(timeWindow) {}
    ~LogProcessor() { if (logFile_.is_open()) logFile_.close(); }

    void processEntry(const LogEntry& entry) {
        lock_guard<mutex> guard(jobMutex_);

        // Generate unique job ID and track progress
        string jobId = generateJobID(entry);
        sendStatusUpdateToMonitoringAPI(jobId, "In Progress");

        if (!processLogEntrySafely(entry)) {
            int retryAttempts = 0;

            while (retryAttempts < 5) {
                // Retry processing the log up to five times using exponential backoff.
                this_thread::sleep_for(chrono::seconds(pow(2, retryAttempts)));

                if (processLogEntrySafely(entry)) break;
                else ++retryAttempts;
            }

            // If log processing failed even after five attempts, send a warning to the monitoring API and continue.
            if (retryAttempts == 5) {
                string errorMsg = "Failed to process log entry after 5 attempts.";
                sendWarningToLog(errorMsg);
            }
        }

        sendStatusUpdateToMonitoringAPI(jobId, "Completed");
    }

private:
