pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initializeEmm(int emmType, const char* gummei) {
    pthread_mutex_lock(&mutex);

    if (emmCount >= emmCapacity) {
        emmCapacity = emmCapacity ? 2 * emmCapacity : 1;
        LTE_EMM_MESSAGE* newArray = realloc(emmArray, sizeof(*newArray) * emmCapacity);

        if (!newArray) {
            pthread_mutex_unlock(&mutex);
            perror("Failed to allocate memory");
            exit(EXIT_FAILURE);
        }

        emmArray = newArray;
    }

    emmArray[emmCount].EMM_TYPE = emmType;
    snprintf(emmArray[emmCount].GUMMEI, sizeof(emmArray[emmCount].GUMMEI), "%s", gummei);

