static size_t size = 0;

void init() {
    pthread_mutex_lock(&mutex);
    if (array == NULL) {
        array = malloc(16 * sizeof(LTE_EMM_MESSAGE));
        if (array == NULL) {
            exit(-1); // Out of memory
        }
        capacity = 16;
        size = 0;
    }
    pthread_mutex_unlock(&mutex);
}

void add(LTE_EMM_MESSAGE msg) {
    pthread_mutex_lock(&mutex);
    if (size == capacity) {
        LTE_EMM_MESSAGE* newArray = realloc(array, (capacity + 16) * sizeof(LTE_EMM_MESSAGE));
        if (newArray == NULL) {
            pthread_mutex_unlock(&mutex);
            exit(-1); // Out of memory
        }
        array = newArray;
        capacity += 16;
    }
    array[size++] = msg;
    pthread_mutex_unlock(&mutex);
}
