// Define your data structures 
typedef struct {
    // ...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    unsigned char *key;
    int key_len;
    unsigned char *iv;
    EVP_CIPHER_CTX *ctx;
} cipher_data;

// Generate IV
unsigned char* generate_IV(int iv_length) {
    unsigned char* iv = malloc(iv_length);
    RAND_bytes(iv, iv_length);
    return iv;
}

// Derive key using PBKDF2
unsigned char* derive_key(const char *password, const unsigned char *salt, int iterations) {
    unsigned char* derived_key = malloc(EVP_MAX_KEY_LENGTH); // Assume maximum AES-256 key length.

    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), salt, 16, iterations, EVP_aes_256_cbc(), EVP_MAX_KEY_LENGTH, derived_key)) {
        ERR_print_errors_fp(stderr);
        return NULL;
    }

    return derived_key;
}

// Initialize cipher context with key and IV
cipher_data* init_cipher(const char *password, const unsigned char *salt) {
    // Allocate memory for the cipher_data structure
    cipher_data* data = malloc(sizeof(cipher_data));

    if (NULL == password || NULL == salt) {
        free(data);
        return NULL;
    }

    // Derive key using PBKDF2 with 2000 iterations and a random salt
    data->key = derive_key(password, salt, 2000);
    if (NULL == data->key) {
        free(data);
        return NULL;
    }

    // Generate IV with dynamic length based on AES block size
    data->iv = generate_IV(EVP_CIPHER_block_size(EVP_aes_256_cbc()));
    if (NULL == data->iv) {
        free(data);
        return NULL;
    }

    // Create and initialize the cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    assert(1 == EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, data->key, data->iv));

    // Store the cipher context and IV in the cipher_data structure.
    data->ctx = ctx;

    return data;
}

// Clean up and disable the cipher when it is no longer needed.
void cleanup_cipher(cipher_data* data) {
    // Free the key, IV and cipher context from memory
    free(data->key);
    free(data->iv);
    EVP_CIPHER_CTX_free(data->ctx);

    // Free the entire cipher_data structure
    free(data);
}
```
