```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[16];  // Adjust this based on your requirement
    int RNTI;
    int CRC_INDICATION_REL8_TAG;   // Assuming integer type, adjust as per actual data type
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* pdu;
    struct Node *prev, *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node* head = NULL;
Node* tail = NULL;
int count = 0;

void addToList(NFAPI_CRC_INDICATION_PDU_T *newData) {
    pthread_mutex_lock(&lock);  // Lock the thread to prevent concurrent access

    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) {
        printf("Memory allocation failed!\n");
        exit(-1);  // Exit program as memory allocation failure is critical
    }

    // Copy data to the node
    newNode->pdu = newData;

    if (count == 0) {   // List is empty
        head = tail = newNode;
        newNode->prev = NULL;
        newNode->next = NULL;
    } else {  // List is not empty
        tail->next = newNode;
        newNode->prev = tail;
        tail = newNode;
    }

    count++;  // Increase the counter
    printf("Inserted tag: %s\n", newData->RX_UE_INFORMATION_TAG);   // Logging operation

    pthread_mutex_unlock(&lock);  // Release the lock after successful insertion
}

// Function to check if a tag already exists in list
int isTagExist(char* tag) {
    Node* temp = head;
    while (temp != NULL) {
        if (strcmp(tag, temp->pdu->RX_UE_INFORMATION_TAG) == 0)  // Tag found in list
            return 1;
        temp = temp->next;
    }
    return 0;   // Tag not found in the list
}

// Function to clear the list and free memory
void clearList() {
    pthread_mutex_lock(&lock);  // Lock the thread to prevent concurrent access

    Node* temp = head;
    while (temp != NULL) {
        Node* nextNode = temp->next;

        free(temp->pdu);   // Free memory of PDU
        free(temp);  // Free node

        temp = nextNode;
    }

    head = tail = NULL;
    count = 0;

    pthread_mutex_unlock(&lock);  // Release the lock after successful clearance
}
```
This is a basic skeleton. To modify the tag if duplicate is found, you can use an additional loop to append a counter until a unique value is found. For concurrent access, this code uses a mutex lock and ensures that only one thread at a time modifies the list. Also, error handling for memory allocation failures is also implemented in `addToList` function.
