#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct MAC_HEADER {
    int header_id;
} MAC_HEADER;

typedef struct MAC_PDU {
    MAC_HEADER header;
    int PDCP_SN;
    char SRB_TYPE[256];
} MAC_PDU;

// A node in the linked list.
typedef struct Node {
    MAC_PDU* pdu;
    struct Node* next;
} Node;

// Our dynamically growing list of PDUs.
typedef struct List {
    Node* head;
    int size;
    pthread_mutex_t mutex;
} List;

List* createList() {
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->head = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroyList(List* list) {
    // Clear the list.
    while (list->head != NULL) {
        Node* next = list->head->next;
        free(list->head);
        list->head = next;
    }

    pthread_mutex_destroy(&list->mutex);
    free(list);
}

MAC_PDU* createPDUPopulateRandomly() {
    MAC_PDU* pdu = malloc(sizeof(MAC_PDU));
