const size_t incrementSize = 16; // fixed increments for efficient memory allocation.

// Logging details
void logOperation(char *operation) {
    pthread_mutex_lock(&lock); 

    time_t t = time(NULL);
    struct tm* currentTime = localtime(&t);

    printf("Thread: %ld Operation: %s Current Time: %02d:%02d:%02d\n", pthread_self(), operation, 
            currentTime->tm_hour, currentTime->tm_min, currentTime->tm_sec);

    pthread_mutex_unlock(&lock);
}

// Allocating memory and initializing array
LTE_EMM_MESSAGE* initializeArray(size_t size) {
    LTE_EMM_MESSAGE* arr = (LTE_EMM_MESSAGE*)calloc(size, sizeof(LTE_EMM_MESSAGE));

    if(!arr) {
        fprintf(stderr, "Memory allocation failed!");
        return NULL;
    }

    logOperation("Initialized array");
    return arr;
}

// Resizing the array
int resizeArray() {
    pthread_mutex_lock(&lock); 

    LTE_EMM_MESSAGE* newArr = realloc(array, sizeof(LTE_EMM_MESSAGE) * (arraySize + incrementSize));

    if(!newArr) {
        fprintf(stderr, "Memory allocation failed while resizing!");
        pthread_mutex_unlock(&lock); 
        return -1;
    }

    array = newArr;
    arraySize += incrementSize;

    logOperation("Resized array");

    pthread_mutex_unlock(&lock); 

    return 0;
}

// Deallocating memory from array
void deinitializeArray() {
    pthread_mutex_lock(&lock); 

    free(array);
    array = NULL;
    arraySize = 0;

    logOperation("Deinitialized array");

    pthread_mutex_unlock(&lock); 
}
