#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "jsmn.h" // JSON parsing library

typedef struct {
    double temperature;
    double humidity;
    double pressure;
    time_t timestamp;
    int calibrationStatus;
} SensorCalibration;

SensorCalibration* readSensorData(const char* filename, int* numSensors) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open the file");
        return NULL;
    }

    // Read the whole file into a buffer
    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);
    char* buffer = malloc(length + 1);
    if (buffer == NULL) {
        perror("Failed to allocate memory for the buffer");
        return NULL;
    }
    fread(buffer, 1, length, file);
    buffer[length] = '\0'; // Null-terminate the string manually

    // Parse JSON
    int capacity = 256;
    jsmn_parser parser;
    jsmntok_t* tokens = malloc(sizeof(jsmntok_t) * capacity);
    jsmn_init(&parser);
    while (1) {
        int result = jsmn_parse(&parser, buffer, length, tokens, capacity);
        if (result >= 0) {
            break; // Parsed successfully
        } else if (result == JSMN_ERROR_NOMEM) {
            // Reallocate more memory for the tokens
            capacity *= 2;
            tokens = realloc(tokens, sizeof(jsmntok_t) * capacity);
            if (tokens == NULL) {
                perror("Failed to reallocate memory");
                return NULL;
            }
        } else {
            // Error occurred while parsing
            perror("Failed to parse JSON");
            return NULL;
        }
    }

    // Extract sensor data from the parsed tokens... (omitted for brevity)

    free(buffer);
    free(tokens);
    fclose(file);
}
```
