SensorRecord* initializeLinkedList(int numRecords) {
    srand(time(NULL));  // Seed the random number generator with current time

    SensorRecord *head = NULL;
    SensorRecord *tail = NULL;

    for (int i = 0; i < numRecords; ++i) {
        SensorRecord *newNode = malloc(sizeof(SensorRecord));

        if (!newNode) {
            // Handle allocation error, clean up memory and return.
            while (head != NULL) {
                SensorRecord *nextNode = head->next;
                free(head);
                head = nextNode;
            }

            return NULL;  // Return NULL to signal an error occurred
        }

        newNode->temperature = 0.0f;  // Fill in with real data
        newNode->humidity = 0.0f;
        newNode->pressure = 0.0f;
        newNode->timestamp = time(NULL);
        newNode->calibrationStatus = rand() % 2;  // Randomize calibration status

        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    return head;
}
