import { createPool } from 'mysql';
import { ConnectionError, RequestError } from './errorHandlers';

const dbConfig = {
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
  connectionLimit: parseInt(process.env.MAX_CONNECTIONS) || 10
};

const pool = createPool(dbConfig);

export function getEmployees({ supervisorId, pageSize = 10, orderDirection = 'ASC', jobTitleFilter }) {
  return new Promise((resolve, reject) => {
    const startTime = Date.now();

    pool.getConnection((err, connection) => {
      if (err) {
        console.error(`Failed to get DB connection: ${err}`);
        reject(new ConnectionError('Database connection error'));
      } else {
        const query = `SELECT name, city, address 
                        FROM Employees 
                        WHERE supervisor_id = ${connection.escape(supervisorId)}
                        ${jobTitleFilter ? `AND job_title = ${connection.escape(jobTitleFilter)}` : ''}
                        ORDER BY name ${orderDirection} LIMIT ${pageSize};`;

        connection.query(query, (err, results) => {
          connection.release(); 

          if (err) {
            console.error(`Failed to execute query: ${err}`);
            reject(new RequestError('Query execution error'));
          } else {
            const endTime = Date.now();

            console.log({
              message: 'Successfully executed SQL query',
              executionTime: `${endTime - startTime} ms`,
              resourcesUsed: 'n/a' // Resource usage monitoring depends on the hosting environment
            });

            resolve(results);
          }
        });
      }
    });
  });
}
