["The problem seems quite complex as it involves dynamic memory allocation, managing of concurrency, and automatic cleanup of expired sessions. This could be implemented using C++ with the use of STL features like `std::mutex` for thread safety, `std::shared_ptr` or `std::unique_ptr` to handle shared access to session data, and `std::thread`/`std::async` for concurrency control.

Here is a simplified implementation using these C++ features:

```cpp
#include <memory>
#include <mutex>
#include <unordered_map>
#include <string>
#include <chrono>
#include <thread>

enum class SessionStatus { Active, Inactive, Expired };

struct SessionData {
    std::time_t lastActivity;
    SessionStatus status;
};

class SessionManager {
public:
    using SharedSession = std::shared_ptr<SessionData>;

private:
    std::unordered_map<std::string, SharedSession> sessions; // unique session ID to session data mapping
    mutable std::mutex mtx;

public:
    SessionManager() {
        // start cleanup thread 
        std::thread cleaner(&SessionManager::cleanExpiredSessions, this);
        cleaner.detach();
    }

    void addOrUpdateSession(const std::string& sessionID) {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = sessions.find(sessionID);
        if (it != sessions.end()) {
            // update existing session
            it->second->lastActivity = std::time(nullptr);
            return;
        } 

        // create new session
        auto session = std::make_shared<SessionData>();
        session->status = SessionStatus::Active;
        session->lastActivity = std::time(nullptr);

        sessions[sessionID] = session;
    }

    SharedSession getSessionData(const std::string& sessionID) const {
        std::lock_guard<std::mutex> lock(mtx);

        auto it = sessions.find(sessionID);
        if (it != sessions.end()) {
            return it->second;
        } else {
            return nullptr; // session not found
        }
    }

    void cleanExpiredSessions() const {
        while (true) {
            std::this_thread::sleep_for(std::chrono::minutes(5));

            auto now = std::time(nullptr);
            std::lock_guard<std::mutex> lock(mtx);

            for (auto it = sessions.begin(); it != sessions.end();) {
                if ((now - it->second->lastActivity) > 3600 /* expiration time is 1 hour */) {
                    // mark session as expired and erase from map
                    it->second->status = SessionStatus::Expired;
                    sessions.erase(it++);
                } else {
                    ++it;
                }
            }
        }
    }
};
```
Please note that this code is a simplified version and might not work in real world applications due to various factors (like handling of exceptions, error checking, graceful termination etc.). It's also not fully C compliant as it uses some features only available in C++ like threading. To implement it in pure C, we would need to use platform-specific APIs/libraries for concurrency management and memory allocation.
"]

