    temp = temp->next;
    }

    data->RX_UE_INFORMATION_TAG = malloc((strlen(tag)+1)*sizeof(char)); // +1 for null terminator
    if (data->RX_UE_INFORMATION_TAG == NULL){
        free(data);
        pthread_mutex_unlock(&mutexLock);
        handleMemoryAllocationFailure();
        return;
    }

    strcpy(data->RX_UE_INFORMATION_TAG, tag);

    // Fill other members of NFAPI_CRC_INDICATION_PDU_T struct.
    data->RNTI = 0; // Random value or valid one? 
    data->CRC_INDICATION_REL8_TAG = rand() % 2; //Random flag for test purpose

    // Add to linked list
    ListNode* newNode = malloc(sizeof(ListNode));
    if (newNode == NULL) {
        free(data->RX_UE_INFORMATION_TAG);
        free(data);
        pthread_mutex_unlock(&mutexLock);
        handleMemoryAllocationFailure();
        return;
    }

    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = head;

    if(head != NULL) {
        head->prev = newNode;
    }

    head = newNode;

    pthread_mutex_unlock(&mutexLock);
}
```
