```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct user_info {
    char *userID;
} user_info;

typedef enum session_status { ACTIVE, INACTIVE } session_status;

typedef struct session_info {
    user_info *user;
    session_status *status;
    float *weights;
} session_info;

typedef struct metadata {
    char *payload;
    time_t timestamp;
    session_info *info;
} metadata;

typedef struct message {
    char *payload;
    time_t timestamp;
    metadata *metadata;
} message;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int sessionCount = 0;

void pauseSession(struct message *msg) {
    pthread_mutex_lock(&lock);

    if (msg == NULL || msg->metadata == NULL || msg->metadata->info == NULL || 
        msg->metadata->info->status == NULL) {
            pthread_mutex_unlock(&lock);
            return;  // handle null pointers
    }

    if (*(msg->metadata->info->status) != ACTIVE) {
        pthread_mutex_unlock(&lock);
        return;  // session already paused or finished
    }

    *(msg->metadata->info->status) = INACTIVE;
    logEvent("Session paused", msg->timestamp, EXTERNAL_LOGGER);

    pthread_mutex_unlock(&lock);
}

void resumeSession(struct message *msg) {
    pthread_mutex_lock(&lock);

    if (msg == NULL || msg->metadata == NULL || msg->metadata->info == NULL || 
        msg->metadata->info->status == NULL) {
            pthread_mutex_unlock(&lock);
            return;  // handle null pointers
    }

    if (*(msg->metadata->info->status) != INACTIVE) {
        pthread_mutex_unlock(&lock);
        return;  // session already active or finished
    }

    *(msg->metadata->info->status) = ACTIVE;
    logEvent("Session resumed", msg->timestamp, EXTERNAL_LOGGER);

    pthread_mutex_unlock(&lock);
}

void resetSession(struct message *msg) {
    pthread_mutex_lock(&lock);

    if (msg == NULL || msg->metadata == NULL || msg->metadata->info == NULL || 
        msg->metadata->info->status == NULL) {
            pthread_mutex_unlock(&lock);
            return;  // handle null pointers
    }

    *(msg->metadata->info->status) = ACTIVE;
    logEvent("Session reset", msg->timestamp, EXTERNAL_LOGGER);

    pthread_mutex_unlock(&lock);
}
```
This code segment includes error checking for null pointers and ensures the correct locking of resources to prevent data race conditions. It also logs session events using an external logger. The implementation of this function is dependent on how you handle sessions, so the actual implementation may vary based on your specific use case. Also, note that actual integration with JSON-based settings file, authentication methods and external logging framework needs to be handled separately depending upon your application's requirements. This code segment only covers the concurrency management for handling pausing, resuming, and resetting of sessions.
