const int MAX_RETRIES = 5; // Maximum number of retries.
unsigned long backoffMillisecs = 1000; // Initial exponential backoff time in milliseconds.

void* fetchInitialConfiguration(int retryCount) {
    if (retryCount > MAX_RETRIES) {
        return NULL; // Return after maximum retries.
