    struct Config *config = malloc(sizeof(struct Config));
    // Fetch configuration from external service
    // Check for errors and handle them accordingly.
    srand((unsigned int) time(NULL) * configUpdated++); // Random seed
    int randNum = rand();

    if (config == NULL || latestConfig == NULL || randNum % 5 == 0) { // Simulate outdated or incorrect configuration
        printf("WARN: Outdated or incorrect configuration received, retrying...\n");
        usleep(backoffMillisecs * 1000);
        backoffMillisecs *= 2;
        return fetchInitialConfiguration(retryCount + 1); // Retry after exponential backoff.
    } else {
        printf("INFO: Configuration updated successfully.\n");
        pthread_mutex_lock(&mutex); // Lock mutex for thread safety.
        if (latestConfig != NULL) free(latestConfig);  // Free previous configuration.
        latestConfig = config;
        backoffMillisecs = 1000; // Reset exponential backoff time.
        pthread_mutex_unlock(&mutex); // Unlock mutex.
    }

    return latestConfig;
}

