#define MAX_RETRIES 5
#define RETRY_BACKOFF 1000 // microseconds

// A global mutex to ensure thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* fetchConfig(void *service) {
    int retries = 0, maxSizeLimit, capacity;
    while (retries < MAX_RETRIES) {
        if (get_config((ExternalService *) service, &maxSizeLimit, &capacity)) {
            return service;
        }
        usleep(retries++ * RETRY_BACKOFF);
    }
    // Logging an error message for unavailable configuration parameters 
    fprintf(stderr, "Unable to fetch configuration from external service after %d retries\n", MAX_RETRIES);
    return NULL;
}

int initList(LTEPHYTLV **list, int phyphyid, int maxSizeLimit, int capacity) {
