            sprintf(newIdentifier, "%s_%d", node->pdu.header.identifier, currentNode->pdu.PDCP_SN);
            strcpy(node->pdu.header.identifier, newIdentifier);
        }
    }

    pthread_mutex_lock(&list->lock);
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        node->prev = list->tail;
        list->tail->next = node;
        list->tail = node;
    }
    ++list->count;
    pthread_mutex_unlock(&list->lock);

    return 0;
}
```
The above code provides a basic implementation of thread-safe linked list with a MAC_PDU structure. The `insertUniqueNode` function checks if the header already exists in the list before inserting, and if so, appends a counter to the identifier. Note that this is a simplified version and doesn't include network interfaces or logging functionality. A production-level implementation would require additional code for these features.
