        free(new_session->message->metadata);
        free(new_session->message);
        free(new_session);
        return -3; // insufficient memory available
    }

    new_session->next = NULL;

    if (*session_list) {
        struct session *last_session = *session_list;

        while (last_session->next != NULL) {
            last_session = last_session->next;
        }

        last_session->next = new_session;
    } else {
        *session_list = new_session;
    }

    // handle pausing, resuming, and resetting operations here
    if (pthread_mutex_unlock(&lock)) {
      return -4; // error in unlocking the mutex
    }

    return 0; // success
}
