    if(!json_is_integer(maxDevicesJson)) {
        fprintf(stderr, "Error: 'maxDevices' is not an integer\n");
        exit(-1);
    }

    maxDevices = (int)json_integer_value(maxDevicesJson);
    if (file == NULL) file = fopen(logFilePath,"w");
}

void logEvent(const char* eventType, const char* message) {
    pthread_mutex_lock(&lock);

    time_t now;
    struct tm *nowStruct;
    now = time(0);
    nowStruct = localtime(&now);

    fprintf(file, "%d-%02d-%02d %02d:%02d:%02d [%s] %s\n", 
        nowStruct->tm_year + 1900, nowStruct->tm_mon + 1, nowStruct->tm_mday, 
        nowStruct->tm_hour, nowStruct->tm_min, nowStruct->tm_sec, eventType, message);
    fflush(file);

    pthread_mutex_unlock(&lock);
}

// Assume allocateSensorEventLog and allocateNFAPIStruct are functions that 
// create new SensorEventLog and NFAPI_CRC_INDICATION_PDU_T structures.
Node* addDevice() {
    if (size >= maxDevices) return NULL; // Maximum number of devices limit reached

    pthread_mutex_lock(&lock);

    Node* node = malloc(sizeof(Node));
    node->sensorEvent = allocateSensorEventLog(); 
    node->nfapiStruct = allocateNFAPIStruct();
    node->next = NULL;

    if (head == NULL) head = node;
    else tail->next = node;

    tail = node;
    size++;
    logEvent("INFO", "New device added");

    pthread_mutex_unlock(&lock);
    return node;
}

void removeDevice(Node* node) {
    if (node == NULL || head == NULL) return; // No devices to remove or device not found

    pthread_mutex_lock(&lock);

    if (head == node) head = node->next;
    else {
        Node* current = head;
        while(current && current->next != node) current = current->next;
        if (!current) return; // Device not found in the list
        current->next = node->next;
        if (tail == node) tail = current;
    }

    free(node); // assuming this will also deallocate the SensorEventLog and NFAPI_CRC_INDICATION_PDU_T structures
    size--;
    logEvent("INFO", "Device removed");

    pthread_mutex_unlock(&lock);
}
``` 

