```csharp
using System;
using System.IO;
using ICSharpCode.SharpZipLib.GZip;
using ICSharpCode.SharpZipLib.Core;
using System.Runtime.Serialization.Formatters.Binary;

public object LoadFromFile(string filePath) {
    var fileSize = new FileInfo(filePath).Length;

    using (var stream = File.OpenRead(filePath)) {
        Stream decompressedStream;

        // If the file is large, use a non-buffered stream for better memory efficiency
        if (fileSize > 1024 * 1024) { // 1MB
            decompressedStream = new GZipInputStream(stream);
        } else {
            var buffer = new byte[stream.Length];
            stream.Read(buffer, 0, buffer.Length);

            var memStream = new MemoryStream();
            using (var gzipStream = new GZipInputStream(new MemoryStream(buffer))) {
                gzipStream.CopyTo(memStream);
            }
            decompressedStream = memStream;
        }

        var formatter = new BinaryFormatter();
        return formatter.Deserialize(decompressedStream);
    }
}
```
