["Implementing this task in C requires extensive understanding of socket programming, DNS resolution, concurrency control, and memory management which are typically not covered in the standard library or require OS-specific implementation.

Here is a high-level pseudocode to illustrate how you might accomplish this:

```c
#include <arpa/inet.h> // for inet_addr()
#include <netdb.h> 
#include <string.h>   // for memset() and strncpy()
#include <stdlib.h>  // for malloc(), free()
#include <pthread.h> // for thread-safe cache implementation
#include <errno.h>   // for error handling
#define MAX_QUERIES 1000 // define maximum DNS queries per session

// Define a simple doubly linked list node structure to hold resolved IP addresses
typedef struct ListNode {
    u_char* ip;
    time_t timestamp; // used for caching expiration
    struct ListNode* prev;
    struct ListNode* next;
} ListNode;

// Global variables for thread-safe cache implementation and query count
ListNode *cacheHead = NULL, *cacheTail = NULL;
int queryCount = 0;
pthread_mutex_t mutex; // used to prevent data race conditions during concurrent requests

u_char* resolveDNS(const char* hostname) {
    pthread_mutex_lock(&mutex); // lock the mutex for thread safety 

    // Check if we've already resolved this hostname recently, return cached IP if so
    ListNode* current = cacheHead;
    while (current != NULL) {
        if (!strcmp(hostname, inet_ntoa(*((struct in_addr *) current->ip)))) { 
            pthread_mutex_unlock(&mutex); // unlock the mutex
            return current->ip;
        }
        current = current->next;
    }

    // Check if we've exceeded our maximum DNS query limit
    if (queryCount >= MAX_QUERIES) { 
        pthread_mutex_unlock(&mutex); // unlock the mutex
        return NULL;
    }

    struct hostent* host = gethostbyname(hostname);

    if (host == NULL || host->h_addr_list[0] == NULL) { 
        pthread_mutex_unlock(&mutex); // unlock the mutex
        return NULL; // invalid or non-existent domain
    }

    u_char* ip = (u_char*) malloc(sizeof(u_char) * INET_ADDRSTRLEN);

    if (ip == NULL) { 
        pthread_mutex_unlock(&mutex); // unlock the mutex
        return NULL; // memory allocation failure
    }

    memcpy(ip, host->h_addr_list[0], INET_ADDRSTRLEN);

    // Add resolved IP to cache and increment query count
    ListNode* node = (ListNode*) malloc(sizeof(ListNode)); 
    if (node == NULL) { 
        pthread_mutex_unlock(&mutex); // unlock the mutex
        free(ip); // clean up if memory allocation fails for cache node
        return NULL;
    }

    time(&(node->timestamp)); // record current time as timestamp for caching expiration
    node->ip = ip; 
    node->prev = NULL;
    node->next = cacheHead; // add new resolved IP to the head of our cache list

    if (cacheHead != NULL) {
        cacheHead->prev = node;
    }
    else {
        cacheTail = node;
    }

    queryCount++; 

    pthread_mutex_unlock(&mutex); // unlock the mutex

    return ip;
}
```

Please note that this is a simple example and does not include all details such as timeout handling, cleaning up expired cache entries, error checking for memory allocation failures etc. Also, you may need to adjust some parameters based on your specific use case (e.g., maximum cache size). 

You would need to handle these aspects carefully in a production environment, considering factors like error handling and edge cases.
"]

