// A function to validate if the logger already exists in the current set of loggers
int isLoggerExist(LogConfig* loggers, int size, const char* loggerName) {
    for (int i = 0; i < size; ++i) {
        pthread_mutex_lock(&loggers[i].lock);
        if (!strcmp(loggers[i].name, loggerName)) {
            return 1;
        }
        pthread_mutex_unlock(&loggers[i].lock);
    }
    return 0;
}

// Function to dynamically allocate memory for an array of LogConfig structures based on user input N
LogConfig* createLogger(int n, ...) {
    assert(n > 0 && "Number of loggers must be greater than 0");
    va_list ap;
    va_start(ap, n);
    LogConfig *loggers = calloc(n, sizeof(LogConfig));

    for (int i = 0; i < n; ++i) {
        const char* loggerName = va_arg(ap, const char*);
        assert(!isLoggerExist(loggers, n, loggerName) && "Duplicate Logger Name found");

