```python
import hashlib
import os
from typing import Generator

BUF_SIZE = 65536  # read files in 64kb chunks

def get_file_chunk(path: str) -> Generator[bytes, None, None]:
    with open(path, 'rb') as f:
        while True:
            data = f.read(BUF_SIZE)
            if not data:
                break
            yield data

def compute_md5(file_path: str) -> str:
    hasher = hashlib.md5()

    for chunk in get_file_chunk(file_path):
        hasher.update(chunk)

    return hasher.hexdigest()
``` 

