logging.basicConfig(filename='auth.log', level=logging.DEBUG, 
                    format=f'%(asctime)s %(levelname)s %(name)s %(threadName)s : %(message)s')

def handle_file(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        try:
            with open('filename', 'r', encoding='utf-8') as file: # replace filename and encoding if required
                lines = file.readlines()

                # sorting lines
                lines.sort()

                # extract sequence number from the last line, replace with custom logic for extraction
