                return func(*args, **kwargs, seq_num=seq_num)
        except Exception as e:
            logging.error("Error occurred while handling file", exc_info=True)
    return wrapper

def handle_authentication(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        # Extract user info from kwargs
        user = kwargs.get('user') 

        if not redis_cache.exists(user):
            logging.info("User session doesn't exist, creating new one")

            # Create JWT token and store in cache
            access_token = create_access_token(identity=user)
            redis_cache.set(name=user, value=access_token)

        return func(*args, **kwargs, jwt_token=redis_cache.get(user))
    return wrapper

@jwt.expired_token_loader
