} NFAPI_RX_FRAME_PDU_T;

NFAPI_RX_FRAME_PDU_T* initializeFramePDUs(size_t N, size_t minPayloadSize, size_t maxPayloadSize) {
    srand((unsigned int)time(NULL)); // Seed the random number generator

    NFAPI_RX_FRAME_PDU_T* frames = (NFAPI_RX_FRAME_PDU_T*)malloc(N * sizeof(NFAPI_RX_FRAME_PDU_T));
    if (frames == NULL) {
        // Handle memory allocation error
        return NULL;
    }

    for (size_t i = 0; i < N; ++i) {
        frames[i].PCI = i + 1;  // Set a valid PCI value here

        // Generate a random payload size within the specified range
        frames[i].payloadSize = minPayloadSize + rand() % (maxPayloadSize - minPayloadSize + 1);

        frames[i].payloadBuffer = malloc(frames[i].payloadSize);
        if (frames[i].payloadBuffer == NULL) {
            // Handle memory allocation error for payload buffer
            free(frames); // Clean up previously allocated frames
            return NULL;
        }

        // Initialize the RRC_CONNECTION_RECONFIGURATION message
        if (!initRRCConnectionReconfiguration(&(frames[i].message))) {
            // Handle RRC message initialization error
            free(frames[i].payloadBuffer); // Clean up payload buffer
            free(frames); // Clean up previously allocated frames
            return NULL;
        }
    }

    return frames;
}
