    unsigned char hash[SHA256_DIGEST_LENGTH];
    size_t size;
    pthread_mutex_t mutex;
    NetworkEventLog* logs;
} EventData;

int computeHash(char *configPath, unsigned char hash[], int *error) {
    FILE *file = fopen(configPath, "rb");
    if(!file) {
        perror("Couldn't open the file: ");
        return errno;
    }

    SHA256_CTX context;
    unsigned char buffer[4096];
    size_t bytesRead = 0;

    if(!SHA256_Init(&context)) {
        *error = -1;
        return errno;
    }

    while((bytesRead = fread(buffer, 1, sizeof buffer, file))) {
        if(!SHA256_Update(&context, buffer, bytesRead)) {
            *error = -1;
            return errno;
        }
    }

    if(ferror(file)) {
        perror("Error while reading the file: ");
        return errno;
    }

    if(!SHA256_Final(hash, &context)) {
        *error = -1;
        return errno;
    }

    fclose(file);
    return 0;
}

EventData* generateLogs(char *configPath) {
    // Initialize mutex for thread safety.
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    unsigned char hash[SHA256_DIGEST_LENGTH];
    int error = 0;
    if(computeHash(configPath, hash, &error)) {
        fprintf(stderr, "Error while computing the hash: %s\n", strerror(errno));
        return NULL;
    }

    // Assuming that logs can be computed based on a static list or function.
