    }

    memcpy(data->hash, hash, sizeof(hash));
    data->size = logCount;
    pthread_mutex_init(&data->mutex, NULL);
    data->logs = malloc(logCount * sizeof(*data->logs));

    if(!data->logs) {
        perror("Couldn't allocate memory: ");
        free(data);
        return NULL;
    }

    // Populate logs.
    for (size_t i = 0; i < logCount; ++i) {
        data->logs[i].timestamp = time(NULL);
        data->logs[i].eventID = i;  // Placeholder event ID computation.
        snprintf(data->logs[i].UID, sizeof(data->logs[i].UID), "UniqueID%zu", i + 1);
    }

    return data;
}
