LogEntry* getNetworkEventLogs(const char *configFilePath) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&lock);

    LogEntry* logs = NULL;  // Array of logs
    int numLogs = 0;  // Number of log entries

    // Validate the configuration file path for existence and readability
    if (access(configFilePath, F_OK | R_OK) != -1 ) {
        FILE *file = fopen(configFilePath, "rb");  // Open the file in binary mode

        if (file != NULL) {
            unsigned char hash[SHA256_DIGEST_LENGTH];  // Computed SHA-256 hash

            // Compute the SHA-256 hash of the configuration file path using OpenSSL library
            SHA256_CTX sha256;
            SHA256_Init(&sha256);
            const int bufSize = 32768;
            unsigned char *buffer = malloc(bufSize);
            size_t bytesRead = 0;

            if (buffer != NULL) {
                while ((bytesRead = fread(buffer, 1, bufSize, file))) {
                    SHA256_Update(&sha256, buffer, bytesRead);
                }

                SHA256_Final(hash, &sha256);
            } else {
                // Handle memory allocation failure
                printf("Memory allocation failed.\n");
