            // Copy the computed hash into the log entry structure
            memcpy(logs[numLogs].sha256Hash, hash, SHA256_DIGEST_LENGTH);

            numLogs++;
        } else {
            printf("Failed to open file.\n");
        }
    } else {
        printf("File does not exist or is unreadable.\n");
    }

    // Unlock the mutex after accessing shared resources
    pthread_mutex_unlock(&lock);

    return logs;  // Return array of log entries
}
