    if (mode == DEBUG) {
        fprintf(fptr, "Initializing PCI: %d\n", pci);
    }

    srand(time(NULL)); // Initialize random seed
    size_t payloadSize = rand() % (MAX - MIN + 1) + MIN; // Generate a random number within the specified range for the payload

    frame->payload.data = malloc(payloadSize);
    if (!frame->payload.data) {
        fprintf(fptr, "Failed to allocate memory for PCI: %d\n", pci);
        ++failed_frames;
        pthread_mutex_unlock(&lock); // Unlock the mutex before return in case of error
        return -1; 
    }

    frame->payload.length = payloadSize;
    memset(frame->payload.data, 0, payloadSize); // Zero out the memory for security

    if (mode == DEBUG) {
        fprintf(fptr, "Successfully initialized PCI: %d\n", pci);
    }

    pthread_mutex_unlock(&lock); // Unlock the mutex after successful initialization
    return 0;
}

void get_stats(int *total, int *failed) {
    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread safety during read operation
    *total = total_frames;
    *failed = failed_frames;
    pthread_mutex_unlock(&lock); // Unlock the mutex after reading statistics
}

void serialize(NFAPI_RX_FRAME_PDU_T *frame, FILE *file) {
    fwrite(&frame->pci, sizeof(int), 1, file);
    fwrite(&frame->msg, sizeof(RRC_CONNECTION_RECONFIGURATION), 1, file);
    fwrite(&frame->payload.length, sizeof(size_t), 1, file);
    fwrite(frame->payload.data, frame->payload.length, 1, file);
}

void deserialize(NFAPI_RX_FRAME_PDU_T *frame, FILE *file) {
    fread(&frame->pci, sizeof(int), 1, file);
    fread(&frame->msg, sizeof(RRC_CONNECTION_RECONFIGURATION), 1, file);
    fread(&frame->payload.length, sizeof(size_t), 1, file);
    frame->payload.data = malloc(frame->payload.length);
    if (frame->payload.data) {
        fread(frame->payload.data, frame->payload.length, 1, file);
    } else {
        ++failed_frames;
    }
}
```

