LTE_ENB* initializeArray(int numMessages, int seqLimit) {
    // Allocate memory for the array
    LTE_ENB* messages = malloc(numMessages * sizeof(LTE_ENB));

    if (messages == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        numMessages /= 2;  // Fallback strategy: reduce the number of messages
        messages = malloc(numMessages * sizeof(LTE_ENB));

        if (messages == NULL) {
            fprintf(stderr, "Failed to allocate memory even after fallback\n");
            return NULL;  // Even after the fallback strategy, it failed. Return NULL
        }
    }

    int seqNum = 0;

    for (int i = 0; i < numMessages; ++i) {
        // Lock before accessing and modifying messages to prevent race conditions
        pthread_mutex_lock(&lock);

        // Set UE_ID and timestamp based on your specific requirements. This is a placeholder
        messages[i].UE_ID = i;
        messages[i].timestamp = time(NULL);

        // Ensure sequence numbers are monotonically increasing and do not exceed the limit
        if (seqNum >= seqLimit) {
            seqNum = 0;
        }
        messages[i].seqNum = seqNum++;

        pthread_mutex_unlock(&lock);  // Unlock after accessing and modifying messages
    }

    return messages;
}
