        print("File does not exist")
        return None

    with open(filename, 'r') as f:
        lines = f.readlines()

    log_entries = []
    for line in lines:
        try:
            entry = json.loads(line)

            # Assuming the timestamp is stored under "timestamp" key and sequence number under "seqNum"
            time = datetime.strptime(entry['timestamp'], '%Y-%m-%d %H:%M:%S')
            seq_num = entry['seqNum']

            log_entries.append((time, seq_num))
        except Exception as e:
            print("Exception occurred while parsing line:", str(e))

    # Sort logs based on timestamp
    log_entries.sort()

    if log_entries:
        last_entry = log_entries[-1]
        return last_entry[0], last_entry[1]  # return (timestamp, sequence number) of the last entry
    else:
        print("No valid entries in log file")
        return None
```
