['Here's an example implementation of the problem using C programming language with pthread for multi-threading support.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#define MAX_CONNECTIONS 100

typedef struct {
    char ip[20];
    time_t timestamp;
    int sessionID;
} ConnectionState;

ConnectionState connections[MAX_CONNECTIONS];
int numConnections = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
time_t ageThreshold;

void addConnection(char* ip, time_t timestamp, int sessionID) {
    pthread_mutex_lock(&lock);

    // Check if the session ID already exists
    for (int i = 0; i < numConnections; i++) {
        if (connections[i].sessionID == sessionID) {
            printf("Session ID already exists.\n");
            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // Add new connection state to the list
    ConnectionState* newConnection = &connections[numConnections++];
    strcpy(newConnection->ip, ip);
    newConnection->timestamp = timestamp;
    newConnection->sessionID = sessionID;

    pthread_mutex_unlock(&lock);
}

void cleanupOldConnections() {
    time_t currentTime = time(NULL);
    pthread_mutex_lock(&lock);

    for (int i = 0; i < numConnections; i++) {
        if (currentTime - connections[i].timestamp > ageThreshold) {
            // Move the last connection state to this position and decrement numConnections
            connections[i] = connections[--numConnections];
            i--;  // Need to recheck this index since contents moved
        }
    }

    pthread_mutex_unlock(&lock);
}

int getNumActiveConnections() {
    pthread_mutex_lock(&lock);
    int num = numConnections;
    pthread_mutex_unlock(&lock);
    return num;
}
```
In this code, we use a mutex lock to prevent data corruption when multiple threads are accessing or modifying the shared connections list. The `addConnection` function adds a new connection state only if its session ID is unique across all existing sessions. Also, every time you want to clean up old connections based on age threshold, you need to call `cleanupOldConnections()`. 

This solution has a space complexity of O(n) due to the usage of an array to store connection states and a time complexity of O(m*n) for cleanup operation where m is the number of connections and n is average length of a session. Also, this code doesn't include any mechanism for deleting specific connections, it should be added if needed.
