["Here's a simple implementation in C using POSIX threads for threading and ANSI C99 for data structures:

```c
#include <pthread.h>
#include <time.h>
#include <stdlib.h>
#include <string.h>

typedef struct session {
    char *user_id;
    char *auth_token;
    time_t last_accessed;
    time_t expiration_time;
} session_t;

struct node {
    session_t *session;
    struct node *next;
};
typedef struct node node_t;

node_t *head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int totalSessions = 0;

// Function to check if a token exists in the list already.
bool tokenExists(char *token) {
    node_t *current = head;
    while (current != NULL) {
        if (strcmp(current->session->auth_token, token) == 0)
            return true;
        current = current->next;
    }
    return false;
}

// Function to add a new session.
void addSession(char *userID, char *token) {
    pthread_mutex_lock(&lock);

    if (tokenExists(token)) {
        // Handle duplicate token case here.
        // For now, we'll just return without adding the session.
        pthread_mutex_unlock(&lock);
        return;
    }

    node_t *newNode = malloc(sizeof(node_t));
    newNode->session = malloc(sizeof(session_t));

    newNode->session->user_id = strdup(userID);
    newNode->session->auth_token = strdup(token);
    newNode->session->last_accessed = time(NULL);
    newNode->session->expiration_time = time(NULL) + 3600; // Set to 1 hour from now.

    newNode->next = head;
    head = newNode;

    totalSessions++;

    pthread_mutex_unlock(&lock);
}

// Function to remove a session.
void removeSession(node_t *node) {
    if (node == NULL || node->session == NULL) return;

    free(node->session->user_id);
    free(node->session->auth_token);
    free(node->session);
    free(node);
}

// Function to invalidate expired sessions.
void invalidateSessions() {
    pthread_mutex_lock(&lock);

    node_t *current = head;
    while (current != NULL) {
        if (time(NULL) > current->session->expiration_time) {
            // Invalidate the session.

            totalSessions--;
            removeSession(current);
        }

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}

// Function to get the number of active sessions.
int getTotalActiveSessions() {
    int count = 0;

    node_t *current = head;
    while (current != NULL) {
        if (time(NULL) < current->session->expiration_time) 
            count++;

        current = current->next;
    }

    return count;
}
```

This code uses a linked list to store the sessions, with each node containing a session and a pointer to the next node. Sessions are added at the beginning of the list for efficient insertion. 
The `tokenExists` function checks if a token already exists in the list by iterating through it until it finds either a match or reaches the end. The `addSession` function locks the mutex before adding, ensuring that only one thread can add a session at a time to prevent race conditions. Similarly, `invalidateSessions` and `getTotalActiveSessions` also lock the mutex for consistency when checking or updating the number of active sessions.
It's assumed here that all tokens are unique and there is no need to handle concurrent login attempts from the same user; if this was a requirement, a different data structure would have to be used (like a hash table where the keys are the user IDs).
