int allocateMemoryForStructures(NetworkConnection **networkConnections, NetworkTrafficLog **trafficLogs, TCP_HEADER_INFO_T **tcpHeaders, UDP_HEADER_INFO_T **udpHeaders, int N) {
    pthread_mutex_lock(&lock); // lock for thread synchronization

    if (N <= 0 || N > MAX_SIZE_CONNECTIONS || N > MAX_LOGS) {
        return -1; // Invalid input
    }

    *networkConnections = calloc(N, sizeof(NetworkConnection));
    *trafficLogs = calloc(N, sizeof(NetworkTrafficLog));
    *tcpHeaders = calloc(N, sizeof(TCP_HEADER_INFO_T));
    *udpHeaders = calloc(N, sizeof(UDP_HEADER_INFO_T));

    if (*networkConnections == NULL || *trafficLogs == NULL || *tcpHeaders == NULL || *udpHeaders == NULL) {
        return -2; // Memory allocation failure
    }

    pthread_mutex_unlock(&lock); // unlock for thread synchronization
    return 0;
}
