int init_tls_session(char* cert, char* key, unsigned char** iv, size_t* ivlen) {
    pthread_mutex_lock(&tls_sessions.lock);

    if (!tls_sessions.ctx) {
        tls_sessions.ctx = SSL_CTX_new(TLSv1_2_server_method());

        // Configure TLS session cache
        tls_sessions.sessions = SSL_CTX_get0_session_cache(tls_sessions.ctx);

