typedef struct Logger {
    char *debugFilePath;
    char *infoFilePath;
    char *warningFilePath;
    char *errorFilePath;
} Logger;

// Global variables and mutexes for thread safety.
pthread_mutex_t listMutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_CRC_INDICATION_PDU_T **listHead, **listTail;
Logger *logger;

// Forward declarations of component functions.
void createStructure(uint16_t RNTI, void* CRC_INDICATION_REL8_TAG, uint32_t sequenceNumber, int statusFlag);
void logMessage(int level, char* message);
void* memoryManager();
