// Function to create and populate a doubly linked list of structures.
void createStructure(uint16_t RNTI, void* CRC_INDICATION_REL8_TAG, uint32_t sequenceNumber, int statusFlag) {
    pthread_mutex_lock(&listMutex);

    // Allocate memory for the new structure using memory manager.
    NFAPI_CRC_INDICATION_PDU_T *newStruct = memoryManager(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newStruct == NULL) {
        logMessage(3, "Memory allocation error");
        return;
    }

    // Populate the structure.
