    newStruct->sequenceNumber = sequenceNumber;
    newStruct->statusFlag = statusFlag;

    // Add the structure to the list.
    if (*listHead == NULL) {
        *listHead = newStruct;
        *listTail = newStruct;
    } else {
        (*listTail)->next = newStruct;
        newStruct->prev = *listTail;
        *listTail = newStruct;
    }

    pthread_mutex_unlock(&listMutex);
}

