void* allocateAndPopulate(size_t count, int seed) {
    pthread_setcancelstate(PTHREAD_CANCEL_DISABLE, NULL);

    MAC_PDU *array = (MAC_PDU*) malloc(count * sizeof(MAC_PDU));
    if (!array) {
        return NULL;  // Could not allocate memory
    }

    srand(seed);
    for (size_t i = 0; i < count; ++i) {
