  struct cache_entry *next, *prev; // make it a circular doubly-linked list 
  time_t timestamp; // last accessed time
  NFAPI_CRC_INDICATION_PDU_T *pdu;
  UT_hash_handle hh; // makes this structure hashable
} cache_entry;

