int cache_timeout = 3600;    // Default cache timeout is 1 hour (in seconds)
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to check if file exists in the cache and has not expired.
cache_entry* get_from_cache(const char *key) {
    cache_entry *entry;

    HASH_FIND_STR(cache, key, entry); /* id already in the hash? */
    if (entry != NULL && time(NULL) - entry->timestamp <= cache_timeout) {
        return entry;
    }
    else if (entry != NULL) { // If it is expired delete from cache.
        HASH_DELETE(hh, cache, entry); 
        free_cache_entry(entry);
        return NULL;
    }

    return NULL;
}

