["```C
#include <stdlib.h>
#include <pthread.h>

typedef struct Connection {
    int id;
    // other connection related data...
} Connection;

typedef struct ConnectionContext {
    pthread_mutex_t mutex;
    int sessionId;
    Connection** connections;
    int numConnections;
} ConnectionContext;

ConnectionContext* createContext(int sessionId) {
    ConnectionContext* context = malloc(sizeof(ConnectionContext));
    if (context == NULL) return NULL; // out of memory error

    pthread_mutex_init(&context->mutex, NULL); 
    context->sessionId = sessionId;
    context->connections = NULL;
    context->numConnections = 0;

    return context;
}

void destroyContext(ConnectionContext* context) {
    pthread_mutex_destroy(&context->mutex);
    for (int i = 0; i < context->numConnections; ++i) {
        free(context->connections[i]);
    }
    free(context->connections);
    free(context);
}

void addConnection(ConnectionContext* context, Connection* connection) {
    pthread_mutex_lock(&context->mutex);

    // reallocate connections array and add the new one
    context->connections = realloc(context->connections, sizeof(Connection*) * (context->numConnections + 1));
    if (context->connections == NULL) { 
        pthread_mutex_unlock(&context->mutex); // out of memory error
        return;
    }
    context->connections[context->numConnections++] = connection;

    pthread_mutex_unlock(&context->mutex);
}

void removeConnection(ConnectionContext* context, Connection* connection) {
    pthread_mutex_lock(&context->mutex);

    // find the connection and remove it
    for (int i = 0; i < context->numConnections; ++i) {
        if (context->connections[i] == connection) {
            free(context->connections[i]);
            context->connections[i] = context->connections[--context->numConnections];
            break;
        }
    }

    // reallocate connections array to remove the null entry at the end
    if (context->numConnections > 0) {
        context->connections = realloc(context->connections, sizeof(Connection*) * context->numConnections);
    } else {
        free(context->connections);
        context->connections = NULL;
    }

    pthread_mutex_unlock(&context->mutex);
}
```
