#include "cJSON.h"
#include <stdio.h>

void parse_json(const char *filename){
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open %s\n", filename);
        return;
    }

    // Read the entire file into a string
    fseek(file, 0, SEEK_END);
    long length = ftell(file);
    fseek(file, 0, SEEK_SET);
    char *json_str = malloc(length + 1);
    if (fread(json_str, 1, length, file) != length) {
        printf("Failed to read %s\n", filename);
        free(json_str);
        fclose(file);
        return;
    }
    json_str[length] = '\0'; // Null-terminate the string

    cJSON *json = cJSON_Parse(json_str);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            printf("Failed to parse JSON: %s\n", error_ptr);
        }
    } else {
        // Use the parsed JSON here...

        cJSON_Delete(json);
    }

    free(json_str);
    fclose(file);
}
