fn get_config(log_system_name: &str) -> Result<Config, ConfigError> {
    let mut s = Sha256::new();
    s.input_str(&format_unique_id(get_unique_identifier(), log_system_name));
    let config_file_path = format_config_file_path(s.result_str());

    if fs::metadata(config_file_path).is_err() {
        // create new configuration file and fill it with default values
        return Ok(Config { log_level: String::from("info") });
    } else {
        let settings = config::File::with_name(&format_config_file_path(s.result_str()))
            .separator('=')
            .build()?;

        return settings.try_deserialize();
    }
}

fn log(log_system_name: &str, log_level: String, message: String) {
    let client = Client::new();
    let config = get_config(log_system_name).unwrap();

    if log_level == "error" && config.log_level != "info" {
        error_with_rest(&client, message);
    } else if log_level == "info" {
        info_with_rest(&client, message);
    }
}

fn error_with_rest(client: &Client, message: String) {
    let encrypted_message = encrypt_data(message.as_bytes());

    client.post("http://your-logs-service.com/error")
        .body(encrypted_message)
        .send()
        .map_err(|e| error_with_rest(&client, format_error_msg(&e)))
}

fn info_with_rest(client: &Client, message: String) {
    let encrypted_message = encrypt_data(message.as_bytes());

    client.post("http://your-logs-service.com/info")
        .body(encrypted_message)
        .send()
        .map_err(|e| error_with_rest(&client, format_error_msg(&e)))
}
