```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>

typedef struct {
    char* key;
    char* code;
} ScriptObject;

// Thread synchronization lock
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

char* render_footer_scripts(ScriptObject *scriptObjects, size_t count) {
    char* renderedHTML = malloc(1); // Allocate memory for the final HTML string
    if (renderedHTML == NULL) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    renderedHTML[0] = '\0'; // Initialize the string to empty

    char* tempBuffer = malloc(1); // Temporary buffer for each <script> tag
    if (tempBuffer == NULL) {
        printf("Memory allocation failed!\n");
        free(renderedHTML);
        return NULL;
    }

    pthread_mutex_lock(&lock); // Acquire the lock before accessing shared data

    for (size_t i = 0; i < count; ++i) {
        asprintf(&tempBuffer, "<script id='%s'>%s</script>", scriptObjects[i].key, scriptObjects[i].code); // Format each <script> tag
        if (tempBuffer == NULL) {
            printf("Memory allocation failed!\n");
            free(renderedHTML);
            pthread_mutex_unlock(&lock); // Unlock the lock before returning
            return NULL;
        }

        renderedHTML = realloc(renderedHTML, strlen(renderedHTML) + strlen(tempBuffer) + 1); // Allocate memory for the new HTML string
        if (renderedHTML == NULL) {
            printf("Memory allocation failed!\n");
            free(tempBuffer);
            pthread_mutex_unlock(&lock); // Unlock the lock before returning
            return NULL;
        }

        strcat(renderedHTML, tempBuffer); // Append the new <script> tag to the HTML string
    }

    free(tempBuffer); // Cleanup: no longer needed
    pthread_mutex_unlock(&lock); // Unlock the lock after all operations are done

    return renderedHTML;
}
```
